def find_default_service_account_path() -> str:
    """Find credentials locally while still allowing an explicit override."""
    configured = os.environ.get("GOOGLE_APPLICATION_CREDENTIALS")
    if configured:
        return configured
    script_path = Path(__file__).resolve()
    for parent in (script_path.parent, *script_path.parents):
        for filename in ("google_credentials.json", "service_account.json"):
            candidate = parent / filename
            if candidate.is_file():
                return str(candidate)
    return str(script_path.parent / "google_credentials.json")


