def calculate_services_business_activity_outputs(raw_df: Any) -> Any:
    return calculate_pmi_style_outputs(raw_df, SERVICES_BUSINESS_ACTIVITY_LABELS)


def calculate_pmi_indicator_outputs(raw_df: Any) -> Any:
    return calculate_manufacturing_pmi_outputs(raw_df)


def _subject_prefix(subject: str) -> str:
    return f"{subject} " if subject else ""


def _regime_momentum_label(b: float, l: float, config: PmiLabelConfig) -> str:
    subject = _subject_prefix(config.regime_subject)
    if b >= 50 and l >= 2:
        return (
            f"{subject}expansion accelerating".capitalize()
            if not subject
            else f"{subject}expansion accelerating"
        )
    if b >= 50 and l <= -2:
        return (
            f"{subject}expansion slowing".capitalize()
            if not subject
            else f"{subject}expansion slowing"
        )
    if b >= 50 and -2 < l < 2:
        return (
            f"{subject}expansion stable".capitalize()
            if not subject
            else f"{subject}expansion stable"
        )
    if b < 50 and l >= 2:
        return (
            f"{subject}contraction easing".capitalize()
            if not subject
            else f"{subject}contraction easing"
        )
    if b < 50 and l <= -2:
        return (
            f"{subject}contraction worsening".capitalize()
            if not subject
            else f"{subject}contraction worsening"
        )
    if b < 50 and -2 < l < 2:
        return (
            f"{subject}contraction stable".capitalize()
            if not subject
            else f"{subject}contraction stable"
        )
    return ""


def _signal(
    t: float, u: float, config: PmiLabelConfig = MANUFACTURING_PMI_LABELS
) -> str:
    subject = _subject_prefix(config.interpretation_subject)
    mixed_subject = (
        f" {config.interpretation_subject}" if config.interpretation_subject else ""
    )
    if t >= 6 and u >= 0:
        return (
            f"Strong positive {subject}leading signal with supportive warning profile"
        )
    if t >= 6 and u < 0:
        return f"Strong positive {subject}leading signal, but warning risk is negative"
    if t >= 2 and u >= 0:
        return f"Moderately positive {subject}leading signal"
    if t >= 2 and u < 0:
        return f"Positive {subject}leading signal, but fragile"
    if t > -2 and u > -3 and u < 3:
        return f"Neutral/mixed{mixed_subject} signal"
    if t <= -6 and u <= 0:
        return f"Strong negative {subject}leading signal with downside warning confirmation"
    if t <= -6 and u > 0:
        return (
            f"Strong negative {subject}leading signal, but warning profile is improving"
        )
    if t <= -2 and u <= 0:
        return f"Moderately negative {subject}leading signal"
    if t <= -2 and u > 0:
        return f"Negative {subject}leading signal, but stabilisation risk is present"
    return f"Mixed/transition{mixed_subject} signal"


def _warning_label(u: float, config: PmiLabelConfig) -> str:
    subject = _subject_prefix(config.warning_subject)
    if u <= -6:
        return f"High {subject}warning risk"
    if u <= -3:
        return f"Moderate {subject}warning risk"
    if u < 3:
        return f"Neutral {subject}warning profile"
    if u < 6:
        return f"Constructive {subject}warning profile"
    return f"Strong positive {subject}turn / warning cleared"


def _manufacturing_signal_label(
    b: float, g: float, h: float, config: PmiLabelConfig
) -> str:
    if config is NEW_ORDERS_LABELS:
        if b < 48 and g < 0 and h < 0:
            return "High new orders contraction risk"
        if b < 50 and g < 0:
            return "New orders contraction worsening"
        if b < 50 and g > 0:
            return "New orders contraction easing"
        if b > 50 and g < 0:
            return "New orders expansion losing momentum"
        if b > 50 and g > 0:
            return "New orders expansion strengthening"
        return "Mixed new orders signal"
    if config is SERVICES_PMI_LABELS:
        if b < 48 and g < 0 and h < 0:
            return "High services contraction risk"
        if b < 50 and g < 0:
            return "Services contraction worsening"
        if b < 50 and g > 0:
            return "Services contraction easing"
        if b > 50 and g < 0:
            return "Services expansion losing momentum"
        if b > 50 and g > 0:
            return "Services expansion strengthening"
        return "Mixed services signal"
    if config is SERVICES_NEW_ORDERS_LABELS:
        if b < 48 and g < 0 and h < 0:
            return "High services new orders contraction risk"
        if b < 50 and g < 0:
            return "Services new orders contraction worsening"
        if b < 50 and g > 0:
            return "Services new orders contraction easing"
        if b > 50 and g < 0:
            return "Services new orders expansion losing momentum"
        if b > 50 and g > 0:
            return "Services new orders expansion strengthening"
        return "Mixed services new orders signal"
    if config is SERVICES_BUSINESS_ACTIVITY_LABELS:
        if b < 48 and g < 0 and h < 0:
            return "High services business activity contraction risk"
        if b < 50 and g < 0:
            return "Services business activity contraction worsening"
        if b < 50 and g > 0:
            return "Services business activity contraction easing"
        if b > 50 and g < 0:
            return "Services business activity expansion losing momentum"
        if b > 50 and g > 0:
            return "Services business activity expansion strengthening"
        return "Mixed services business activity signal"
    if b < 48 and g < 0 and h < 0:
        return "High manufacturing recession risk"
    if b < 50 and g < 0:
        return "Manufacturing contraction worsening"
    if b < 50 and g > 0:
        return "Manufacturing contraction easing"
    if b > 50 and g < 0:
        return "Expansion losing momentum"
    if b > 50 and g > 0:
        return "Expansion strengthening"
    return "Mixed manufacturing signal"


def _manufacturing(b: float, g: float, h: float) -> str:
    return _manufacturing_signal_label(b, g, h, MANUFACTURING_PMI_LABELS)


def _safe_growth(current: Any, lagged: Any, exponent: float = 1.0) -> Any:
    c = to_float_or_none(current)
    l = to_float_or_none(lagged)
    if c is None or l is None or l == 0:
        return ""
    ratio = c / l
    if ratio <= 0:
        return ""
    return (ratio**exponent) - 1


def _industrial_recovery_score(h: Any, i: Any, j: Any) -> Any:
    if any(is_blank(x) for x in (h, i, j)):
        return ""
    if h < 0 and i > 0 and j > 0:
        return 6
    if h < 0 and i < 0 and j < 0:
        return -6
    if h > 0 and i < 0 and j < 0:
        return -5
    if h > 0 and i > 0 and j > 0:
        return 4
    return 0


def _industrial_warning_raw(h: Any, i: Any, j: Any) -> Any:
    if any(is_blank(x) for x in (h, i, j)):
        return ""
    if h < 0 and i < 0 and j < 0:
        return -8
    if h < 0 and i < 0:
        return -6
    if h >= 0 and i < 0 and j < 0:
        return -5
    if h >= 0 and i < 0:
        return -3
    if h < 0 and i > 0 and j > 0:
        return 4
    return 0


def expanding_zscore_sample(
    values: list[object], gates: list[int] | None = None, min_gate: int = 120
) -> list[object]:
    out: list[object] = []
    n = 0
    mean = 0.0
    m2 = 0.0
    for idx, value in enumerate(values):
        x = to_float_or_none(value)
        if x is not None:
            n += 1
            delta = x - mean
            mean += delta / n
            m2 += delta * (x - mean)
        gate_ok = gates is None or gates[idx] >= min_gate
        if x is None or not gate_ok or n < 2:
            out.append("")
            continue
        variance = m2 / (n - 1)
        if variance <= 0:
            out.append("")
        else:
            out.append((x - mean) / math.sqrt(variance))
    return out


def _industrial_outlier_score(zs: Sequence[Any]) -> Any:
    if any(is_blank(z) for z in zs):
        return ""
    if any(z <= -3 for z in zs):
        return -6
    if any(z <= -2 for z in zs):
        return -4
    if any(z >= 3 for z in zs):
        return 3
    if any(z >= 2 for z in zs):
        return 2
    return 0


def _industrial_outlier_label(zs: Sequence[Any]) -> str:
    if any(is_blank(z) for z in zs):
        return ""
    if any(z >= 3 for z in zs):
        return "Extreme positive outlier"
    if any(z <= -3 for z in zs):
        return "Extreme negative outlier"
    if any(z >= 2 for z in zs):
        return "Strong positive outlier"
    if any(z <= -2 for z in zs):
        return "Strong negative outlier"
    return "Normal range"


def _industrial_regime_momentum_label(h: Any, r: Any) -> str:
    if any(is_blank(x) for x in (h, r)):
        return ""
    if h >= 0 and r >= 2:
        return "Industrial expansion accelerating"
    if h >= 0 and r <= -2:
        return "Industrial expansion slowing"
    if h >= 0 and -2 < r < 2:
        return "Industrial expansion stable"
    if h < 0 and r >= 2:
        return "Industrial contraction easing"
    if h < 0 and r <= -2:
        return "Industrial contraction worsening"
    if h < 0 and -2 < r < 2:
        return "Industrial contraction stable"
    return ""


def _industrial_signal_interpretation(w: Any, x: Any) -> str:
    if any(is_blank(v) for v in (w, x)):
        return ""
    if w >= 6 and x >= 0:
        return "Strong positive industrial production leading signal with supportive warning profile"
    if w >= 6 and x < 0:
        return "Strong positive industrial production leading signal, but warning risk is negative"
    if w >= 2 and x >= 0:
        return "Moderately positive industrial production leading signal"
    if w >= 2 and x < 0:
        return "Positive industrial production leading signal, but fragile"
    if w > -2 and x > -3 and x < 3:
        return "Neutral/mixed industrial production signal"
    if w <= -6 and x <= 0:
        return "Strong negative industrial production leading signal with downside warning confirmation"
    if w <= -6 and x > 0:
        return "Strong negative industrial production leading signal, but warning profile is improving"
    if w <= -2 and x <= 0:
        return "Moderately negative industrial production leading signal"
    if w <= -2 and x > 0:
        return "Negative industrial production leading signal, but stabilisation risk is present"
    return "Mixed/transition industrial production signal"


def _industrial_warning_label(x: Any) -> str:
    if is_blank(x):
        return ""
    if x <= -6:
        return "High industrial production warning risk"
    if x <= -3:
        return "Moderate industrial production warning risk"
    if x < 3:
        return "Neutral industrial production warning profile"
    if x < 6:
        return "Constructive industrial production warning profile"
    return "Strong positive industrial production turn / warning cleared"


def _industrial_signal_label(h: Any, r: Any, x: Any) -> str:
    if any(is_blank(v) for v in (h, r, x)):
        return ""
    if h < 0 and x <= -6:
        return "High industrial slowdown/recession risk"
    if h < 0 and x <= -3:
        return "Industrial contraction risk"
    if h < 0 and r >= 2:
        return "Industrial contraction easing / recovery impulse"
    if h >= 0 and x <= -3:
        return "Industrial expansion fragile / downside risk"
    if h >= 0 and r <= -2:
        return "Industrial expansion losing momentum"
    if h >= 0 and r >= 2:
        return "Industrial expansion strengthening"
    return "Neutral industrial production signal"


def _industrial_percent_display(value: Any, decimals: int = 2) -> Any:
    number = to_float_or_none(value)
    if number is None:
        return ""
    return f"{number * 100:.{decimals}f}%"


def _industrial_percentile_display(value: Any) -> Any:
    return _industrial_percent_display(value, 2)


def _industrial_percent_rank_rounded_3(
    history: Sequence[float], current: Any, sample_count: int
) -> Any:
    current_float = to_float_or_none(current)
    if sample_count < 120 or current_float is None:
        return ""
    rank = percentrank_inc(history, current_float)
    return "" if rank is None else round(rank, 3)


def _industrial_downside_warning_score(l: Any, n: Any, p: Any, r: Any) -> Any:
    if any(is_blank(x) for x in (l, n, p, r)):
        return ""
    return round(clamp(0.40 * l + 0.25 * n + 0.20 * p + 0.15 * r), 2)


def calculate_industrial_production_outputs(raw_df: Any) -> Any:
    records = df_records(raw_df)
    b = [
        to_float_or_none(r.get("Raw Value", r.get("B", r.get("Value", ""))))
        for r in records
    ]
    c_vals: list[Any] = []
    d_vals: list[int] = []
    numeric_b_count = 0
    numeric_c_count = 0
    for i, val in enumerate(b):
        if val is not None:
            numeric_b_count += 1
        window = [x for x in b[max(0, i - 2) : i + 1] if x is not None]
        c = (sum(window) / len(window)) if numeric_b_count >= 3 and window else ""
        c_vals.append(c)
        if c != "":
            numeric_c_count += 1
        d_vals.append(numeric_c_count)
    e_vals = []
    f_vals = []
    g_vals = []
    h_vals = []
    i_vals = []
    j_vals = []
    for idx, c in enumerate(c_vals):
        d = d_vals[idx]
        e_vals.append(_safe_growth(c, c_vals[idx - 1]) if d >= 2 and idx >= 1 else "")
        f_vals.append(
            _safe_growth(c, c_vals[idx - 3], 4) if d >= 4 and idx >= 3 else ""
        )
        g_vals.append(
            _safe_growth(c, c_vals[idx - 6], 2) if d >= 7 and idx >= 6 else ""
        )
        h_vals.append(
            _safe_growth(c, c_vals[idx - 12]) if d >= 13 and idx >= 12 else ""
        )
        i_vals.append(
            h_vals[idx] - h_vals[idx - 3]
            if d >= 16 and idx >= 3 and h_vals[idx] != "" and h_vals[idx - 3] != ""
            else ""
        )
        j_vals.append(
            h_vals[idx] - h_vals[idx - 6]
            if d >= 19 and idx >= 6 and h_vals[idx] != "" and h_vals[idx - 6] != ""
            else ""
        )
    af_vals = expanding_zscore_sample(h_vals, d_vals, 120)
    ag_vals = expanding_zscore_sample(f_vals, d_vals, 120)
    ah_vals = expanding_zscore_sample(g_vals, d_vals, 120)
    ai_vals = expanding_zscore_sample(i_vals, d_vals, 120)
    sorted_h: list[float] = []
    sorted_f: list[float] = []
    sorted_g: list[float] = []
    sorted_i: list[float] = []
    rows = []
    for idx in range(len(b)):
        out = {col: "" for col in INDUSTRIAL_PRODUCTION_OUTPUT_COLUMNS}
        h = h_vals[idx]
        f = f_vals[idx]
        g = g_vals[idx]
        i_ch = i_vals[idx]
        for val, arr in ((h, sorted_h), (f, sorted_f), (g, sorted_g), (i_ch, sorted_i)):
            if val != "":
                bisect.insort(arr, float(val))
        d = d_vals[idx]
        k = _industrial_percent_rank_rounded_3(sorted_h, h, d)
        m = _industrial_percent_rank_rounded_3(sorted_f, f, d)
        o = _industrial_percent_rank_rounded_3(sorted_g, g, d)
        q = _industrial_percent_rank_rounded_3(sorted_i, i_ch, d)
        l = _score_percent_rank(k)
        n = _score_percent_rank(m)
        p = _score_percent_rank(o)
        r = _score_percent_rank(q)
        s = _industrial_recovery_score(h, i_ch, j_vals[idx])
        t = _industrial_downside_warning_score(l, n, p, r)
        zs = [af_vals[idx], ag_vals[idx], ah_vals[idx], ai_vals[idx]]
        u = _industrial_outlier_score(zs)
        v = (
            round(clamp(0.45 * l + 0.25 * n + 0.2 * p + 0.1 * r), 2)
            if all(x != "" for x in (l, n, p, r))
            else ""
        )
        w = (
            round(clamp(0.1 * l + 0.25 * n + 0.15 * p + 0.45 * r + 0.05 * s), 2)
            if all(x != "" for x in (l, n, p, r, s))
            else ""
        )
        x = (
            round(clamp(0.3 * s + 0.5 * t + 0.2 * u), 2)
            if all(z != "" for z in (s, t, u))
            else ""
        )
        out.update(
            {
                "3M MA": c_vals[idx],
                "Sample Count": d,
                "1M % Change": e_vals[idx],
                "3M Annualised Growth": f,
                "6M Annualised Growth": g,
                "YoY Growth": h,
                "3M Change in YoY Growth": _industrial_percent_display(i_ch),
                "6M Change in YoY Growth": _industrial_percent_display(j_vals[idx]),
                "YoY Growth Percentile": _industrial_percentile_display(k),
                "YoY Growth Score": l,
                "3M Growth Percentile": _industrial_percentile_display(m),
                "3M Growth Score": n,
                "6M Growth Percentile": _industrial_percentile_display(o),
                "6M Growth Score": p,
                "Momentum Percentile": _industrial_percentile_display(q),
                "Momentum Score": r,
                "Industrial Cycle Turning Point Score": s,
                "Industrial Downside Warning Score": t,
                "Industrial Extreme Score": u,
                "Coincident Score": v,
                "Leading Score": w,
                "Warning Score": x,
                "State": "" if h == "" else ("Expansion" if h >= 0 else "Contraction"),
                "Regime": _industrial_regime_momentum_label(h, r),
                "Signal Comment": _industrial_signal_interpretation(w, x),
                "Reliability": (
                    ""
                    if b[idx] is None
                    else (
                        "Insufficient history"
                        if d < 60
                        else ("Medium reliability" if d < 120 else "High reliability")
                    )
                ),
                "Signal Validity": (
                    "Missing Data"
                    if b[idx] is None
                    else (
                        "Low Sample"
                        if d < 120
                        else (
                            "Incomplete Score"
                            if any(z == "" for z in (v, w, x))
                            else "Valid"
                        )
                    )
                ),
                "Warning Flag": _industrial_warning_label(x),
                "Slowdown Risk Flag": _industrial_signal_label(h, r, x),
                "YoY Growth Z-Score": af_vals[idx],
                "3M Growth Z-Score": ag_vals[idx],
                "6M Growth Z-Score": ah_vals[idx],
                "Momentum Z-Score": ai_vals[idx],
                "Extreme Flag": _industrial_outlier_label(zs),
            }
        )
        rows.append(out)
    return make_dataframe(rows, INDUSTRIAL_PRODUCTION_OUTPUT_COLUMNS)


def _metric_counts(values: Sequence[Any]) -> list[int]:
    out = []
    count = 0
    for v in values:
        if to_float_or_none(v) is not None:
            count += 1
        out.append(count)
    return out


