def calculate_consumer_spending_outputs(raw_df: Any) -> Any:
    records = df_records(raw_df)
    b = [
        to_float_or_none(r.get("Raw Value", r.get("B", r.get("Value", ""))))
        for r in records
    ]
    c_vals = []
    d_vals = []
    numeric_b_count = 0
    numeric_c_count = 0
    for idx, val in enumerate(b):
        if val is not None:
            numeric_b_count += 1
        window = [x for x in b[max(0, idx - 2) : idx + 1] if x is not None]
        c = (sum(window) / len(window)) if numeric_b_count >= 3 and window else ""
        c_vals.append(c)
        if c != "":
            numeric_c_count += 1
        d_vals.append(numeric_c_count)
    e_vals = []
    f_vals = []
    g_vals = []
    h_vals = []
    i_vals = []
    j_vals = []
    for idx, c in enumerate(c_vals):
        d = d_vals[idx]
        e_vals.append(_safe_growth(c, c_vals[idx - 1]) if d >= 2 and idx >= 1 else "")
        f_vals.append(
            _safe_growth(c, c_vals[idx - 3], 4) if d >= 4 and idx >= 3 else ""
        )
        g_vals.append(
            _safe_growth(c, c_vals[idx - 6], 2) if d >= 7 and idx >= 6 else ""
        )
        h_vals.append(
            _safe_growth(c, c_vals[idx - 12]) if d >= 13 and idx >= 12 else ""
        )
        i_vals.append(
            h_vals[idx] - h_vals[idx - 3]
            if d >= 16 and idx >= 3 and h_vals[idx] != "" and h_vals[idx - 3] != ""
            else ""
        )
        j_vals.append(
            h_vals[idx] - h_vals[idx - 6]
            if d >= 19 and idx >= 6 and h_vals[idx] != "" and h_vals[idx - 6] != ""
            else ""
        )
    h_counts = _metric_counts(h_vals)
    f_counts = _metric_counts(f_vals)
    g_counts = _metric_counts(g_vals)
    i_counts = _metric_counts(i_vals)
    af_vals = expanding_zscore_sample(h_vals, h_counts, 60)
    ag_vals = expanding_zscore_sample(f_vals, f_counts, 60)
    ah_vals = expanding_zscore_sample(g_vals, g_counts, 60)
    ai_vals = expanding_zscore_sample(i_vals, i_counts, 60)
    sorted_h = []
    sorted_f = []
    sorted_g = []
    sorted_i = []
    rows = []
    for idx in range(len(b)):
        out = {col: "" for col in CONSUMER_SPENDING_OUTPUT_COLUMNS}
        h = h_vals[idx]
        f = f_vals[idx]
        g = g_vals[idx]
        i_ch = i_vals[idx]
        for val, arr in ((h, sorted_h), (f, sorted_f), (g, sorted_g), (i_ch, sorted_i)):
            if val != "":
                bisect.insort(arr, float(val))
        k = (
            percentrank_inc(sorted_h, float(h))
            if h_counts[idx] >= 60 and h != ""
            else None
        )
        m = (
            percentrank_inc(sorted_f, float(f))
            if f_counts[idx] >= 60 and f != ""
            else None
        )
        o = (
            percentrank_inc(sorted_g, float(g))
            if g_counts[idx] >= 60 and g != ""
            else None
        )
        q = (
            percentrank_inc(sorted_i, float(i_ch))
            if i_counts[idx] >= 60 and i_ch != ""
            else None
        )
        l = _score_percent_rank(k)
        n = _score_percent_rank(m)
        p = _score_percent_rank(o)
        r = _score_percent_rank(q)
        s = _industrial_recovery_score(h, i_ch, j_vals[idx])
        t = _industrial_warning_raw(h, i_ch, j_vals[idx])
        zs = [af_vals[idx], ag_vals[idx], ah_vals[idx], ai_vals[idx]]
        u = _industrial_outlier_score(zs)
        v = (
            round(clamp(0.45 * l + 0.25 * n + 0.2 * p + 0.1 * r), 2)
            if all(x != "" for x in (l, n, p, r))
            else ""
        )
        w = (
            round(clamp(0.1 * l + 0.25 * n + 0.15 * p + 0.45 * r + 0.05 * s), 2)
            if all(x != "" for x in (l, n, p, r, s))
            else ""
        )
        x = (
            round(clamp(0.3 * s + 0.5 * t + 0.2 * u), 2)
            if all(z != "" for z in (s, t, u))
            else ""
        )
        d = d_vals[idx]
        out.update(
            {
                "3M Moving Average": c_vals[idx],
                "Smoothed Observation Count": d,
                "1M Smoothed Growth": e_vals[idx],
                "3M Annualised Smoothed Growth": f,
                "6M Annualised Smoothed Growth": g,
                "12M Smoothed Growth": h,
                "3M Change in 12M Growth": i_ch,
                "6M Change in 12M Growth": j_vals[idx],
                "12M Growth PercentRank": k if k is not None else "",
                "12M Growth Score": l,
                "3M Annualised Growth PercentRank": m if m is not None else "",
                "3M Annualised Growth Score": n,
                "6M Annualised Growth PercentRank": o if o is not None else "",
                "6M Annualised Growth Score": p,
                "3M Change in 12M Growth PercentRank": q if q is not None else "",
                "3M Change in 12M Growth Score": r,
                "Consumer Spending Recovery / Momentum Score": s,
                "Consumer Spending Warning Score Raw": t,
                "Consumer Spending Outlier Score": u,
                "Consumer Spending Leading Score": v,
                "Consumer Spending Warning Composite Score": w,
                "Consumer Spending Final Warning Score": x,
                "Consumer Spending Regime": (
                    "" if h == "" else ("Expansion" if h >= 0 else "Contraction")
                ),
                "Consumer Spending Regime Momentum Label": _consumer_regime_momentum_label(
                    h, r
                ),
                "Consumer Spending Signal Interpretation": _consumer_signal_interpretation(
                    w, x
                ),
                "Reliability": (
                    ""
                    if b[idx] is None
                    else (
                        "Insufficient history"
                        if d < 60
                        else ("Medium reliability" if d < 120 else "High reliability")
                    )
                ),
                "Data Status": (
                    "Missing Data"
                    if b[idx] is None
                    else (
                        "Low Sample"
                        if d < 60
                        else (
                            "Incomplete Score"
                            if any(z == "" for z in (v, w, x))
                            else "Valid"
                        )
                    )
                ),
                "Consumer Spending Warning Risk Label": _consumer_warning_label(x),
                "Consumer Spending Signal Label": _consumer_signal_label(h, r, x),
                "12M Growth Z-Score": af_vals[idx],
                "3M Annualised Growth Z-Score": ag_vals[idx],
                "6M Annualised Growth Z-Score": ah_vals[idx],
                "3M Change in 12M Growth Z-Score": ai_vals[idx],
                "Consumer Spending Outlier Label": _industrial_outlier_label(zs),
            }
        )
        rows.append(out)
    return make_dataframe(rows, CONSUMER_SPENDING_OUTPUT_COLUMNS)


def _median_from_sorted(values: Sequence[float]) -> float:
    n = len(values)
    mid = n // 2
    return values[mid] if n % 2 else (values[mid - 1] + values[mid]) / 2


def _sentiment_recovery_score(distance: Any, three_month: Any, six_month: Any) -> Any:
    if any(is_blank(x) for x in (distance, three_month, six_month)):
        return ""
    if distance < 0 and three_month > 0 and six_month > 0:
        return 6
    if distance < 0 and three_month < 0 and six_month < 0:
        return -6
    if distance > 0 and three_month < 0 and six_month < 0:
        return -5
    if distance > 0 and three_month > 0 and six_month > 0:
        return 4
    return 0


def _sentiment_turn_score(
    b: Any, level_rank: Any, three_month: Any, six_month: Any
) -> Any:
    if any(is_blank(x) for x in (b, level_rank, three_month, six_month)):
        return ""
    if level_rank <= 0.2 and three_month > 0 and six_month > 0:
        return 5
    if level_rank <= 0.1 and three_month > 0:
        return 4
    if level_rank >= 0.8 and three_month < 0 and six_month < 0:
        return -4
    if level_rank >= 0.9 and three_month < 0:
        return -3
    return 0


def _sentiment_warning_raw(
    distance: Any,
    three_month: Any,
    six_month: Any,
    level_score: Any,
    momentum_score: Any,
) -> Any:
    if any(
        is_blank(x)
        for x in (distance, three_month, six_month, level_score, momentum_score)
    ):
        return ""
    if level_score <= -7 and momentum_score <= -2:
        return -8
    if level_score <= -3 and momentum_score <= -2:
        return -6
    if -3 < level_score < 3 and momentum_score <= -5:
        return -4
    if level_score >= 3 and momentum_score <= -2:
        return -3
    if level_score <= -3 and momentum_score >= 2:
        return 4
    return 0


def _sentiment_outlier_score(zs: Sequence[Any]) -> Any:
    if any(is_blank(z) for z in zs):
        return ""
    if any(z <= -3 for z in zs):
        return -6
    if any(z <= -2 for z in zs):
        return -4
    if any(z >= 3 for z in zs):
        return 3
    if any(z >= 2 for z in zs):
        return 2
    return 0


def _sentiment_outlier_label(zs: Sequence[Any]) -> str:
    if not zs or is_blank(zs[0]):
        return ""
    numeric = [z for z in zs if not is_blank(z)]
    if any(z >= 3 for z in numeric):
        return "Extreme positive outlier"
    if any(z <= -3 for z in numeric):
        return "Extreme negative outlier"
    if any(z >= 2 for z in numeric):
        return "Strong positive outlier"
    if any(z <= -2 for z in numeric):
        return "Strong negative outlier"
    return "Normal range"


def _sentiment_regime(level_score: Any) -> str:
    if is_blank(level_score):
        return ""
    if level_score >= 3:
        return "Strong sentiment"
    if level_score <= -3:
        return "Weak sentiment"
    return "Neutral sentiment"


def _sentiment_momentum_label(level_score: Any, momentum_score: Any) -> str:
    if any(is_blank(x) for x in (level_score, momentum_score)):
        return ""
    if level_score >= 3 and momentum_score >= 2:
        return "Strong sentiment, improving"
    if level_score >= 3 and momentum_score <= -2:
        return "Strong sentiment, weakening"
    if level_score >= 3 and -2 < momentum_score < 2:
        return "Strong sentiment, stable"
    if level_score <= -3 and momentum_score >= 2:
        return "Weak sentiment, improving"
    if level_score <= -3 and momentum_score <= -2:
        return "Weak sentiment, deteriorating"
    if level_score <= -3 and -2 < momentum_score < 2:
        return "Weak sentiment, stable"
    if -3 < level_score < 3 and momentum_score >= 2:
        return "Neutral sentiment, improving"
    if -3 < level_score < 3 and momentum_score <= -2:
        return "Neutral sentiment, weakening"
    return "Neutral sentiment, stable"


def _sentiment_signal_interpretation(leading_score: Any, warning_score: Any) -> str:
    if any(is_blank(x) for x in (leading_score, warning_score)):
        return ""
    if leading_score >= 6 and warning_score >= 0:
        return "Strong positive consumer sentiment leading signal with supportive warning profile"
    if leading_score >= 6 and warning_score < 0:
        return "Strong positive consumer sentiment leading signal, but warning risk is negative"
    if leading_score >= 2 and warning_score >= 0:
        return "Moderately positive consumer sentiment leading signal"
    if leading_score >= 2 and warning_score < 0:
        return "Positive consumer sentiment leading signal, but fragile"
    if leading_score > -2 and warning_score > -3 and warning_score < 3:
        return "Neutral/mixed consumer sentiment signal"
    if leading_score <= -6 and warning_score <= 0:
        return "Strong negative consumer sentiment leading signal with downside warning confirmation"
    if leading_score <= -6 and warning_score > 0:
        return "Strong negative consumer sentiment leading signal, but warning profile is improving"
    if leading_score <= -2 and warning_score <= 0:
        return "Moderately negative consumer sentiment leading signal"
    if leading_score <= -2 and warning_score > 0:
        return "Negative consumer sentiment leading signal, but stabilisation risk is present"
    return "Mixed/transition consumer sentiment signal"


def _sentiment_warning_label(warning_score: Any) -> str:
    if is_blank(warning_score):
        return ""
    if warning_score <= -6:
        return "High consumer sentiment warning risk"
    if warning_score <= -3:
        return "Moderate consumer sentiment warning risk"
    if warning_score < 3:
        return "Neutral consumer sentiment warning profile"
    if warning_score < 6:
        return "Constructive consumer sentiment warning profile"
    return "Strong positive consumer sentiment turn / warning cleared"


def _sentiment_signal_label(level_score: Any, momentum_score: Any) -> str:
    if any(is_blank(x) for x in (level_score, momentum_score)):
        return ""
    if level_score <= -7 and momentum_score <= -2:
        return "Severe consumer confidence stress"
    if level_score <= -3 and momentum_score <= -2:
        return "Consumer confidence deteriorating"
    if level_score <= -3 and momentum_score >= 2:
        return "Weak sentiment but improving"
    if -3 < level_score < 3 and momentum_score <= -5:
        return "Neutral sentiment deteriorating sharply"
    if -3 < level_score < 3 and momentum_score >= 5:
        return "Neutral sentiment improving sharply"
    if level_score >= 3 and momentum_score <= -2:
        return "Strong sentiment losing momentum"
    if level_score >= 3 and momentum_score >= 2:
        return "Consumer confidence strengthening"
    return "Neutral consumer sentiment signal"


def calculate_consumer_sentiment_legacy_outputs(raw_df: Any) -> Any:
    records = df_records(raw_df)
    b_values = [
        to_float_or_none(r.get("Raw Value", r.get("B", r.get("Value", ""))))
        for r in records
    ]
    c_vals: list[Any] = []
    d_vals: list[Any] = []
    e_vals: list[Any] = []
    f_vals: list[Any] = []
    g_vals: list[Any] = []
    sorted_b: list[float] = []
    numeric_b_count = 0
    for idx, b in enumerate(b_values):
        if b is None:
            c_vals.append("")
            d_vals.append("")
            e_vals.append("")
            f_vals.append("")
            g_vals.append("")
            continue
        numeric_b_count += 1
        bisect.insort(sorted_b, b)
        c = numeric_b_count
        c_vals.append(c)
        d_vals.append(b - _median_from_sorted(sorted_b) if c >= 60 else "")
        e_vals.append(
            b - b_values[idx - 1]
            if c >= 2 and idx >= 1 and b_values[idx - 1] is not None
            else ""
        )
        f_vals.append(
            b - b_values[idx - 3]
            if c >= 4 and idx >= 3 and b_values[idx - 3] is not None
            else ""
        )
        g_vals.append(
            b - b_values[idx - 6]
            if c >= 7 and idx >= 6 and b_values[idx - 6] is not None
            else ""
        )

    ab_vals = expanding_zscore_sample(
        b_values, [c if c != "" else 0 for c in c_vals], 60
    )
    ac_vals = expanding_zscore_sample(f_vals, [c if c != "" else 0 for c in c_vals], 60)
    ad_vals = expanding_zscore_sample(g_vals, [c if c != "" else 0 for c in c_vals], 60)
    f_counts = _metric_counts(f_vals)
    g_counts = _metric_counts(g_vals)
    sorted_level: list[float] = []
    sorted_f: list[float] = []
    sorted_g: list[float] = []
    rows: list[dict[str, Any]] = []
    for idx, b in enumerate(b_values):
        out = {col: "" for col in CONSUMER_SENTIMENT_LEGACY_OUTPUT_COLUMNS}
        if b is None:
            out["Data Status"] = "Missing Data"
            rows.append(out)
            continue
        bisect.insort(sorted_level, b)
        if f_vals[idx] != "":
            bisect.insort(sorted_f, float(f_vals[idx]))
        if g_vals[idx] != "":
            bisect.insort(sorted_g, float(g_vals[idx]))
        c = c_vals[idx]
        h = percentrank_inc(sorted_level, b) if c >= 60 else None
        j = (
            percentrank_inc(sorted_f, float(f_vals[idx]))
            if f_counts[idx] >= 60 and f_vals[idx] != ""
            else None
        )
        l = (
            percentrank_inc(sorted_g, float(g_vals[idx]))
            if g_counts[idx] >= 60 and g_vals[idx] != ""
            else None
        )
        i_score = _sentiment_score_percent_rank(h)
        k_score = _sentiment_score_percent_rank(j)
        m_score = _sentiment_score_percent_rank(l)
        n_score = _sentiment_recovery_score(d_vals[idx], f_vals[idx], g_vals[idx])
        o_score = _sentiment_turn_score(
            b, h if h is not None else "", f_vals[idx], g_vals[idx]
        )
        p_score = _sentiment_warning_raw(
            d_vals[idx], f_vals[idx], g_vals[idx], i_score, k_score
        )
        zs = [ab_vals[idx], ac_vals[idx], ad_vals[idx]]
        q_score = _sentiment_outlier_score(zs)
        r_score = (
            round(clamp(0.75 * i_score + 0.25 * clamp(d_vals[idx] / 5)), 2)
            if all(x != "" for x in (i_score, d_vals[idx]))
            else ""
        )
        s_score = (
            round(
                clamp(
                    0.2 * i_score
                    + 0.4 * k_score
                    + 0.25 * m_score
                    + 0.05 * n_score
                    + 0.1 * o_score
                ),
                2,
            )
            if all(x != "" for x in (i_score, k_score, m_score, n_score, o_score))
            else ""
        )
        t_score = (
            round(
                clamp(
                    0.25 * n_score + 0.25 * o_score + 0.35 * p_score + 0.15 * q_score
                ),
                2,
            )
            if all(x != "" for x in (n_score, o_score, p_score, q_score))
            else ""
        )
        out.update(
            {
                "Observation Count": c,
                "Distance From Rolling Median": d_vals[idx],
                "1M Change": e_vals[idx],
                "3M Change": f_vals[idx],
                "6M Change": g_vals[idx],
                "Level PercentRank": h if h is not None else "",
                "Sentiment Level Score": i_score,
                "3M Change PercentRank": j if j is not None else "",
                "3M Momentum Score": k_score,
                "6M Change PercentRank": l if l is not None else "",
                "6M Momentum Score": m_score,
                "Consumer Sentiment Recovery / Momentum Score": n_score,
                "Consumer Sentiment Low/High Turn Score": o_score,
                "Consumer Sentiment Warning Score Raw": p_score,
                "Consumer Sentiment Outlier Score": q_score,
                "Consumer Sentiment Level Composite Score": r_score,
                "Consumer Sentiment Leading Score": s_score,
                "Consumer Sentiment Final Warning Score": t_score,
                "Consumer Sentiment Regime": _sentiment_regime(i_score),
                "Consumer Sentiment Momentum Label": _sentiment_momentum_label(
                    i_score, k_score
                ),
                "Consumer Sentiment Signal Interpretation": _sentiment_signal_interpretation(
                    s_score, t_score
                ),
                "Reliability": (
                    "Insufficient history"
                    if c < 60
                    else ("Medium reliability" if c < 120 else "High reliability")
                ),
                "Data Status": (
                    "Low Sample"
                    if c < 60
                    else (
                        "Incomplete Score"
                        if any(x == "" for x in (r_score, s_score, t_score))
                        else "Valid"
                    )
                ),
                "Consumer Sentiment Warning Risk Label": _sentiment_warning_label(
                    t_score
                ),
                "Consumer Sentiment Signal Label": _sentiment_signal_label(
                    i_score, k_score
                ),
                "Level Z-Score": ab_vals[idx],
                "3M Change Z-Score": ac_vals[idx],
                "6M Change Z-Score": ad_vals[idx],
                "Consumer Sentiment Outlier Label": _sentiment_outlier_label(zs),
            }
        )
        rows.append(out)
    return make_dataframe(rows, CONSUMER_SENTIMENT_LEGACY_OUTPUT_COLUMNS)


def _sentiment_sheets_round(value: Any, places: int = 2) -> Any:
    if is_blank(value):
        return ""
    number = to_float_or_none(value)
    if number is None:
        return ""
    try:
        quantized = Decimal(str(round(number, 12))).quantize(
            Decimal("1").scaleb(-places), rounding=ROUND_HALF_UP
        )
    except Exception:
        return ""
    return float(quantized)


def _sentiment_percent_rank_rounded_3(history: Sequence[float], current: Any) -> Any:
    current_float = to_float_or_none(current)
    if current_float is None or len(history) < 60:
        return ""
    rank = percentrank_inc(history, current_float)
    return _sentiment_sheets_round(rank, 3)


def _sentiment_score_percent_rank(rank: Any) -> Any:
    if is_blank(rank):
        return ""
    return _sentiment_sheets_round(rank * 20 - 10, 2)


def _sentiment_percent_display(value: Any) -> Any:
    number = to_float_or_none(value)
    if number is None:
        return ""
    return f"{number * 100:.2f}%"


