def calculate_core_ppi_outputs(raw_df: Any) -> Any:
    base_rows = df_records(calculate_core_inflation_outputs(raw_df))
    rows = []
    for base in base_rows:
        k = base["12M Core Inflation Score"]
        m = base["3M Annualised Core Inflation Score"]
        o = base["6M Annualised Core Inflation Score"]
        q = base["3M Change in 12M Core Inflation Score"]
        r = base["Distance From 2 Percent Target"]
        u = base["Core Inflation Recovery / Cooling Score"]
        v = base["Core Inflation Target Pressure Score"]
        w = base["Core Inflation Outlier Score"]
        t = (
            round(clamp(0.45 * m + 0.35 * o + 0.2 * q, -10, 10), 2)
            if all(x != "" for x in (m, o, q))
            else ""
        )
        target_gap_component = clamp(r * 500, -10, 10) if r != "" else ""
        x = (
            round(
                clamp(
                    0.35 * k
                    + 0.25 * m
                    + 0.2 * o
                    + 0.1 * q
                    + 0.1 * target_gap_component,
                    -10,
                    10,
                ),
                2,
            )
            if all(z != "" for z in (k, m, o, q, target_gap_component))
            else ""
        )
        y = (
            round(
                clamp(
                    0.1 * k + 0.35 * m + 0.25 * o + 0.2 * q + 0.05 * t + 0.05 * u,
                    -10,
                    10,
                ),
                2,
            )
            if all(z != "" for z in (k, m, o, q, t, u))
            else ""
        )
        z = (
            round(clamp(0.35 * u + 0.45 * v + 0.2 * w, -10, 10), 2)
            if all(val != "" for val in (u, v, w))
            else ""
        )
        c = base["Observation Count"]
        g = base["12M Inflation"]
        e = base["3M Annualised Inflation"]
        data_status = base["Data Status"]
        if data_status != "Missing Data":
            data_status = (
                "Low Sample"
                if c < 60
                else (
                    "Incomplete Score"
                    if any(val == "" for val in (x, y, z))
                    else "Valid"
                )
            )
        zs = [
            base["12M Core Inflation Z-Score"],
            base["3M Annualised Core Inflation Z-Score"],
            base["6M Annualised Core Inflation Z-Score"],
            base["3M Change in 12M Core Inflation Z-Score"],
        ]
        rows.append(
            {
                "Observation Count": c,
                "1M Annualised Inflation": base["1M Annualised Inflation"],
                "3M Annualised Inflation": e,
                "6M Annualised Inflation": base["6M Annualised Inflation"],
                "12M Inflation": g,
                "3M Change in 12M Inflation": base["3M Change in 12M Inflation"],
                "6M Change in 12M Inflation": base["6M Change in 12M Inflation"],
                "12M Core PPI PercentRank": base["12M Core Inflation PercentRank"],
                "12M Core PPI Score": k,
                "3M Annualised Core PPI PercentRank": base[
                    "3M Annualised Core Inflation PercentRank"
                ],
                "3M Annualised Core PPI Score": m,
                "6M Annualised Core PPI PercentRank": base[
                    "6M Annualised Core Inflation PercentRank"
                ],
                "6M Annualised Core PPI Score": o,
                "3M Change in 12M Core PPI PercentRank": base[
                    "3M Change in 12M Core Inflation PercentRank"
                ],
                "3M Change in 12M Core PPI Score": q,
                "Distance From 2 Percent Target": r,
                "Core PPI Target Status": base["Core Inflation Target Status"],
                "Core PPI Momentum Composite Score": t,
                "Core PPI Recovery / Cooling Score": u,
                "Core PPI Target Pressure Score": v,
                "Core PPI Outlier Score": w,
                "Core PPI Leading Score": x,
                "Core PPI Warning Composite Score": y,
                "Core PPI Final Warning Score": z,
                "Core PPI Pressure Regime": _core_ppi_regime(x),
                "Core PPI Momentum Label": _core_ppi_momentum_label(x, y),
                "Core PPI Signal Interpretation": _core_ppi_signal_interpretation(y, z),
                "Reliability": base["Reliability"],
                "Data Status": data_status,
                "Core PPI Warning Risk Label": _core_ppi_warning_label(z),
                "Core PPI Policy Signal Label": _core_ppi_policy_signal_label(z, g, e),
                "12M Core PPI Z-Score": zs[0],
                "3M Annualised Core PPI Z-Score": zs[1],
                "6M Annualised Core PPI Z-Score": zs[2],
                "3M Change in 12M Core PPI Z-Score": zs[3],
                "Core PPI Outlier Label": _core_ppi_outlier_label(zs),
            }
        )
    return make_dataframe(rows, CORE_PPI_OUTPUT_COLUMNS)


