def calculate_yield_curve_outputs(raw_df: Any) -> Any:
    records = df_records(raw_df)
    raw_values = [
        to_float_or_none(r.get("Raw Value", r.get("B", r.get("Value", ""))))
        for r in records
    ]
    raw_counts = _metric_counts(raw_values)
    moving_averages: list[Any] = []
    smoothed_count = 0
    smoothed_counts_so_far: list[int] = []
    one_period_changes: list[Any] = []
    three_period_changes: list[Any] = []
    six_period_changes: list[Any] = []
    twelve_period_changes: list[Any] = []

    for idx, current in enumerate(raw_values):
        if raw_counts[idx] < 3:
            moving_averages.append("")
        else:
            window = [v for v in raw_values[max(0, idx - 2) : idx + 1] if v is not None]
            moving_averages.append(
                "" if not window else _yield_curve_mean_sheets(window)
            )

        c = moving_averages[idx]
        if not is_blank(c):
            smoothed_count += 1
        smoothed_counts_so_far.append(smoothed_count)
        if (
            smoothed_count < 2
            or is_blank(c)
            or idx < 1
            or is_blank(moving_averages[idx - 1])
        ):
            one_period_changes.append("")
        else:
            one_period_changes.append(c - moving_averages[idx - 1])
        for lag, min_count, target in (
            (3, 4, three_period_changes),
            (6, 7, six_period_changes),
            (12, 13, twelve_period_changes),
        ):
            if (
                smoothed_count < min_count
                or is_blank(c)
                or idx < lag
                or is_blank(moving_averages[idx - lag])
            ):
                target.append("")
            else:
                target.append(c - moving_averages[idx - lag])

    smoothed_counts = smoothed_counts_so_far
    f_counts = _metric_counts(three_period_changes)
    g_counts = _metric_counts(six_period_changes)
    h_counts = _metric_counts(twelve_period_changes)
    # A26 intentionally gates all four ranks from Sample Count D.
    c_ranks = _yield_curve_metric_ranks_sheets(moving_averages, smoothed_counts)
    f_ranks = _yield_curve_metric_ranks_sheets(three_period_changes, smoothed_counts)
    g_ranks = _yield_curve_metric_ranks_sheets(six_period_changes, smoothed_counts)
    h_ranks = _yield_curve_metric_ranks_sheets(twelve_period_changes, smoothed_counts)
    c_zscores = _rounded_expanding_zscores(moving_averages, smoothed_counts, 60)
    f_zscores = _rounded_expanding_zscores(three_period_changes, f_counts, 60)
    g_zscores = _rounded_expanding_zscores(six_period_changes, g_counts, 60)
    h_zscores = _rounded_expanding_zscores(twelve_period_changes, h_counts, 60)

    rows: list[dict[str, Any]] = []
    for idx, current in enumerate(raw_values):
        c = moving_averages[idx]
        d = smoothed_counts[idx]
        e = one_period_changes[idx]
        f = three_period_changes[idx]
        g = six_period_changes[idx]
        h = twelve_period_changes[idx]
        i = c_ranks[idx]
        j = _yield_curve_score_percentile(i)
        k = f_ranks[idx]
        l = _yield_curve_score_percentile(k)
        m = g_ranks[idx]
        n = _yield_curve_score_percentile(m)
        o = h_ranks[idx]
        p = _yield_curve_score_percentile(o)
        t = (
            _yield_curve_sheets_round(
                clamp(
                    _yield_curve_weighted_sum(
                        (0.05, j), (0.45, l), (0.35, n), (0.15, p)
                    ),
                    -10,
                    10,
                ),
                2,
            )
            if all(not is_blank(x) for x in (j, l, n, p))
            else ""
        )
        u = _yield_curve_flattening_stress_score(c, f, g)
        v = _yield_curve_shock_score(e)
        w = _yield_curve_inversion_restriction_score(c, f, g)
        ah = c_zscores[idx]
        ai = f_zscores[idx]
        aj = g_zscores[idx]
        ak = h_zscores[idx]
        x = _yield_curve_outlier_score([ah, ai, aj, ak])
        y = (
            _yield_curve_sheets_round(
                clamp(
                    _yield_curve_weighted_sum(
                        (0.45, j), (0.30, l), (0.15, n), (0.10, p)
                    ),
                    -10,
                    10,
                ),
                2,
            )
            if all(not is_blank(val) for val in (j, l, n, p))
            else ""
        )
        z = (
            _yield_curve_sheets_round(
                clamp(
                    _yield_curve_weighted_sum(
                        (0.20, j), (0.30, l), (0.25, n), (0.10, p), (0.10, t), (0.05, u)
                    ),
                    -10,
                    10,
                ),
                2,
            )
            if all(not is_blank(val) for val in (j, l, n, p, t, u))
            else ""
        )
        aa = (
            _yield_curve_sheets_round(
                clamp(
                    _yield_curve_weighted_sum(
                        (0.30, u), (0.25, v), (0.30, w), (0.15, x)
                    ),
                    -10,
                    10,
                ),
                2,
            )
            if all(not is_blank(val) for val in (u, v, w, x))
            else ""
        )
        reliability = (
            "Insufficient history"
            if d < 60
            else ("Medium reliability" if d < 120 else "High reliability")
        )
        data_status = (
            "Missing Data"
            if current is None
            else (
                "Low Sample"
                if d < 60
                else (
                    "Incomplete Score"
                    if any(is_blank(val) for val in (y, z, aa))
                    else "Valid"
                )
            )
        )
        rows.append(
            {
                "3M MA Curve Spread": c,
                "Sample Count": d,
                "1M Curve Change": e,
                "3M Curve Change": f,
                "6M Curve Change": g,
                "12M Curve Change": h,
                "Curve Level Percentile": _yield_curve_percent_display(i),
                "Curve Stress Level Score": j,
                "3M Change Percentile": _yield_curve_percent_display(k),
                "3M Change Stress Score": l,
                "6M Change Percentile": _yield_curve_percent_display(m),
                "6M Change Stress Score": n,
                "12M Change Percentile": _yield_curve_percent_display(o),
                "12M Change Stress Score": p,
                "Curve Regime": _yield_curve_regime(c, f),
                "Recession Risk Bias": _yield_curve_recession_risk_label(c, f, aa),
                "Curve Shock Flag": _yield_curve_shock_label(e),
                "Curve Impulse Score": t,
                "Curve Cycle Turning Point Score": u,
                "Curve Shock Score": v,
                "Recession Risk Pressure Score": w,
                "Curve Extreme Score": x,
                "Coincident Score": y,
                "Leading Score": z,
                "Warning Score": aa,
                "State": _yield_curve_stress_regime(y),
                "Regime": _yield_curve_stress_momentum_label(y, z),
                "Signal Comment": _yield_curve_signal_interpretation(z, aa),
                "Reliability": reliability,
                "Signal Validity": data_status,
                "Warning Flag": _yield_curve_warning_label(aa),
                "Level Z-Score": ah,
                "3M Change Z-Score": ai,
                "6M Change Z-Score": aj,
                "12M Change Z-Score": ak,
                "Extreme Flag": _yield_curve_outlier_label([ah, ai, aj, ak]),
            }
        )
    return make_dataframe(rows, YIELD_CURVE_OUTPUT_COLUMNS)


def _term_premium_level_regime(c: Any, f: Any) -> str:
    if is_blank(c):
        return ""
    if not is_blank(f) and c >= 2 and f > 0:
        return "High and rising term-premium regime"
    if not is_blank(f) and c >= 2 and f <= 0:
        return "High but cooling term-premium regime"
    if not is_blank(f) and c >= 1 and f > 0:
        return "Elevated and rising term-premium regime"
    if not is_blank(f) and c >= 1 and f <= 0:
        return "Elevated but easing term-premium regime"
    if not is_blank(f) and c >= 0 and f > 0:
        return "Positive term premium and rising"
    if not is_blank(f) and c >= 0 and f <= 0:
        return "Positive term premium but easing"
    if not is_blank(f) and c < 0 and f > 0:
        return "Negative term premium but rising"
    if not is_blank(f) and c < 0 and f <= 0:
        return "Negative and easing term-premium regime"
    return "Mixed term-premium regime"


def _term_premium_asset_bias_label(y: Any) -> str:
    if is_blank(y):
        return ""
    if y >= 6:
        return "Strong bearish duration / rising term-premium risk"
    if y >= 2:
        return "Mild bearish duration / higher term-premium pressure"
    if y <= -6:
        return "Strong bullish duration / falling term-premium support"
    if y <= -2:
        return "Mild bullish duration / lower term-premium pressure"
    return "Neutral term-premium asset bias"


def _term_premium_shock_label(e: Any) -> str:
    if is_blank(e):
        return ""
    if e >= 0.3:
        return "1M term-premium upside shock"
    if e <= -0.3:
        return "1M term-premium downside shock"
    return "No 1M term-premium shock"


def _term_premium_recovery_tightening_score(c: Any, f: Any, g: Any) -> Any:
    if any(is_blank(x) for x in (c, f, g)):
        return ""
    if c < 0 and f > 0 and g > 0:
        return 5
    if c >= 1 and f > 0 and g > 0:
        return 6
    if c >= 1 and f < 0 and g < 0:
        return -5
    if c < 0 and f < 0 and g < 0:
        return -6
    if f > 0 and g > 0:
        return 4
    if f < 0 and g < 0:
        return -4
    return 0


def _term_premium_shock_score(e: Any) -> Any:
    if is_blank(e):
        return ""
    if e >= 0.3:
        return 6
    if e >= 0.2:
        return 4
    if e <= -0.3:
        return -6
    if e <= -0.2:
        return -4
    return 0


def _term_premium_restriction_score(c: Any, f: Any, g: Any) -> Any:
    if any(is_blank(x) for x in (c, f, g)):
        return ""
    if c >= 2 and f > 0 and g > 0:
        return 6
    if c >= 1 and f > 0 and g > 0:
        return 4
    if c <= 0 and f < 0 and g < 0:
        return -6
    if c <= 0.5 and f < 0 and g < 0:
        return -4
    return 0


def _term_premium_outlier_score(zs: Sequence[Any]) -> Any:
    if any(is_blank(z) for z in zs):
        return ""
    if any(z >= 3 for z in zs):
        return 6
    if any(z >= 2 for z in zs):
        return 4
    if any(z <= -3 for z in zs):
        return -6
    if any(z <= -2 for z in zs):
        return -4
    return 0


def _term_premium_pressure_regime(y: Any) -> str:
    if is_blank(y):
        return ""
    if y >= 2:
        return "Term-premium pressure rising"
    if y <= -2:
        return "Term-premium pressure easing"
    return "Neutral term-premium pressure"


def _term_premium_momentum_label(y: Any, z: Any) -> str:
    if any(is_blank(v) for v in (y, z)):
        return ""
    if y >= 2 and z >= 2:
        return "Term-premium pressure rising"
    if y >= 2 and z <= -2:
        return "Term premium elevated but easing"
    if y >= 2 and -2 < z < 2:
        return "Term-premium pressure elevated / stable"
    if y <= -2 and z >= 2:
        return "Term premium low but rising"
    if y <= -2 and z <= -2:
        return "Term-premium pressure easing"
    if y <= -2 and -2 < z < 2:
        return "Term-premium pressure low / stable"
    if -2 < y < 2 and z >= 2:
        return "Term-premium trend rising"
    if -2 < y < 2 and z <= -2:
        return "Term-premium trend easing"
    return "Term premium broadly neutral"


def _term_premium_signal_interpretation(z: Any, aa: Any) -> str:
    if any(is_blank(v) for v in (z, aa)):
        return ""
    if z >= 6 and aa >= 0:
        return "Strong upside term-premium signal with supportive risk-premium pressure profile"
    if z >= 6 and aa < 0:
        return "Strong upside term-premium signal, but risk-premium warning profile is easing"
    if z >= 2 and aa >= 0:
        return "Moderately positive term-premium pressure signal"
    if z >= 2 and aa < 0:
        return "Term-premium rising signal, but risk-premium pressure is easing"
    if z > -2 and aa > -3 and aa < 3:
        return "Neutral/mixed term-premium signal"
    if z <= -6 and aa <= 0:
        return "Strong term-premium easing signal with downside confirmation"
    if z <= -6 and aa > 0:
        return "Strong term-premium easing signal, but risk-premium pressure remains elevated"
    if z <= -2 and aa <= 0:
        return "Moderately negative term-premium/easing signal"
    if z <= -2 and aa > 0:
        return "Term-premium easing signal, but risk-premium pressure remains elevated"
    return "Mixed/transition term-premium signal"


def _term_premium_warning_label(aa: Any) -> str:
    if is_blank(aa):
        return ""
    if aa >= 6:
        return "High upside term-premium risk warning"
    if aa >= 3:
        return "Moderate upside term-premium risk warning"
    if aa > -3:
        return "Neutral term-premium warning profile"
    if aa > -6:
        return "Moderate term-premium easing warning"
    return "High term-premium easing signal"


def _term_premium_outlier_label(zs: Sequence[Any]) -> str:
    if any(is_blank(z) for z in zs):
        return ""
    if any(z >= 3 for z in zs):
        return "Extreme upside term-premium pressure"
    if any(z >= 2 for z in zs):
        return "Strong upside term-premium pressure"
    if any(z <= -3 for z in zs):
        return "Extreme downside term-premium pressure"
    if any(z <= -2 for z in zs):
        return "Strong downside term-premium pressure"
    return "Normal range"


def calculate_term_premium_outputs(raw_df: Any) -> Any:
    records = df_records(raw_df)
    raw_values = [
        to_float_or_none(r.get("Raw Value", r.get("B", r.get("Value", ""))))
        for r in records
    ]
    raw_counts = _metric_counts(raw_values)
    moving_averages: list[Any] = []
    smoothed_count = 0
    smoothed_counts_so_far: list[int] = []
    one_period_changes: list[Any] = []
    three_period_changes: list[Any] = []
    six_period_changes: list[Any] = []
    twelve_period_changes: list[Any] = []

    for idx, current in enumerate(raw_values):
        if raw_counts[idx] < 3:
            moving_averages.append("")
        else:
            window = [v for v in raw_values[max(0, idx - 2) : idx + 1] if v is not None]
            moving_averages.append("" if not window else sum(window) / len(window))

        c = moving_averages[idx]
        if not is_blank(c):
            smoothed_count += 1
        smoothed_counts_so_far.append(smoothed_count)
        if (
            smoothed_count < 2
            or is_blank(c)
            or idx < 1
            or is_blank(moving_averages[idx - 1])
        ):
            one_period_changes.append("")
        else:
            one_period_changes.append(c - moving_averages[idx - 1])
        for lag, min_count, target in (
            (3, 4, three_period_changes),
            (6, 7, six_period_changes),
            (12, 13, twelve_period_changes),
        ):
            if (
                smoothed_count < min_count
                or is_blank(c)
                or idx < lag
                or is_blank(moving_averages[idx - lag])
            ):
                target.append("")
            else:
                target.append(c - moving_averages[idx - lag])

    smoothed_counts = smoothed_counts_so_far
    f_counts = _metric_counts(three_period_changes)
    g_counts = _metric_counts(six_period_changes)
    h_counts = _metric_counts(twelve_period_changes)
    c_ranks = _expectations_metric_ranks(moving_averages)
    f_ranks = _expectations_metric_ranks(three_period_changes)
    g_ranks = _expectations_metric_ranks(six_period_changes)
    h_ranks = _expectations_metric_ranks(twelve_period_changes)
    c_zscores = _rounded_expanding_zscores(moving_averages, smoothed_counts, 60)
    f_zscores = _rounded_expanding_zscores(three_period_changes, f_counts, 60)
    g_zscores = _rounded_expanding_zscores(six_period_changes, g_counts, 60)
    h_zscores = _rounded_expanding_zscores(twelve_period_changes, h_counts, 60)

    rows: list[dict[str, Any]] = []
    for idx, current in enumerate(raw_values):
        c = moving_averages[idx]
        d = smoothed_counts[idx]
        e = one_period_changes[idx]
        f = three_period_changes[idx]
        g = six_period_changes[idx]
        h = twelve_period_changes[idx]
        i = c_ranks[idx]
        j = _score_percent_rank(i)
        k = f_ranks[idx]
        l = _score_percent_rank(k)
        m = g_ranks[idx]
        n = _score_percent_rank(m)
        o = h_ranks[idx]
        p = _score_percent_rank(o)
        t = (
            round(clamp(0.45 * l + 0.35 * n + 0.15 * p + 0.05 * j, -10, 10), 2)
            if all(not is_blank(x) for x in (l, n, p, j))
            else ""
        )
        u = _term_premium_recovery_tightening_score(c, f, g)
        v = _term_premium_shock_score(e)
        w = _term_premium_restriction_score(c, f, g)
        ah = c_zscores[idx]
        ai = f_zscores[idx]
        aj = g_zscores[idx]
        ak = h_zscores[idx]
        x = _term_premium_outlier_score([ah, ai, aj, ak])
        y = (
            round(clamp(0.45 * j + 0.3 * l + 0.15 * n + 0.1 * p, -10, 10), 2)
            if all(not is_blank(val) for val in (j, l, n, p))
            else ""
        )
        z = (
            round(
                clamp(
                    0.15 * j + 0.3 * l + 0.25 * n + 0.15 * p + 0.1 * t + 0.05 * u,
                    -10,
                    10,
                ),
                2,
            )
            if all(not is_blank(val) for val in (j, l, n, p, t, u))
            else ""
        )
        aa = (
            round(clamp(0.3 * u + 0.25 * v + 0.3 * w + 0.15 * x, -10, 10), 2)
            if all(not is_blank(val) for val in (u, v, w, x))
            else ""
        )
        reliability = (
            ""
            if current is None
            else (
                "Insufficient history"
                if d < 60
                else ("Medium reliability" if d < 120 else "High reliability")
            )
        )
        data_status = (
            "Missing Data"
            if current is None
            else (
                "Low Sample"
                if d < 60
                else (
                    "Incomplete Score"
                    if any(is_blank(val) for val in (y, z, aa))
                    else "Valid"
                )
            )
        )
        rows.append(
            {
                "3-Period Moving Average": c,
                "Smoothed Observation Count": d,
                "1-Period Change": e,
                "3-Period Change": f,
                "6-Period Change": g,
                "12-Period Change": h,
                "Term Premium Level PercentRank": i,
                "Term Premium Level Score": j,
                "3-Period Term Premium Change PercentRank": k,
                "3-Period Term Premium Change Score": l,
                "6-Period Term Premium Change PercentRank": m,
                "6-Period Term Premium Change Score": n,
                "12-Period Term Premium Change PercentRank": o,
                "12-Period Term Premium Change Score": p,
                "Term Premium Level Regime": _term_premium_level_regime(c, f),
                "Term Premium Asset Bias Label": _term_premium_asset_bias_label(y),
                "1-Period Term Premium Shock Label": _term_premium_shock_label(e),
                "Term Premium Momentum Composite Score": t,
                "Term Premium Recovery / Tightening Score": u,
                "Term Premium Shock Score": v,
                "Term Premium Restriction Score": w,
                "Term Premium Outlier Score": x,
                "Term Premium Leading Score": y,
                "Term Premium Warning Composite Score": z,
                "Term Premium Final Warning Score": aa,
                "Term Premium Pressure Regime": _term_premium_pressure_regime(y),
                "Term Premium Momentum Label": _term_premium_momentum_label(y, z),
                "Term Premium Signal Interpretation": _term_premium_signal_interpretation(
                    z, aa
                ),
                "Reliability": reliability,
                "Data Status": data_status,
                "Term Premium Warning Risk Label": _term_premium_warning_label(aa),
                "Term Premium Level Z-Score": ah,
                "3-Period Term Premium Change Z-Score": ai,
                "6-Period Term Premium Change Z-Score": aj,
                "12-Period Term Premium Change Z-Score": ak,
                "Term Premium Outlier Label": _term_premium_outlier_label(
                    [ah, ai, aj, ak]
                ),
            }
        )
    return make_dataframe(rows, TERM_PREMIUM_OUTPUT_COLUMNS)


def _interbank_rate_sheets_round(value: Any, places: int = 2) -> Any:
    """A28-only Google Sheets ROUND semantics."""
    return _real_yield_sheets_round(value, places)


def _interbank_rate_mean_sheets(values: Sequence[Any]) -> Any:
    """A28-only spreadsheet-order mean using full numeric source precision."""
    return _real_yield_mean_sheets(values)


def _interbank_rate_percentrank_inc_sheets(
    values: Sequence[float], current: Any
) -> Any:
    """A28-only Google Sheets PERCENTRANK.INC semantics."""
    return _real_yield_percentrank_inc_sheets(values, current)


def _interbank_rate_metric_ranks_sheets(
    values: Sequence[Any], min_count: int = 60
) -> list[Any]:
    """Use each A28 metric's own numeric 60-observation history gate."""
    history: list[float] = []
    ranks: list[Any] = []
    for value in values:
        numeric = to_float_or_none(value)
        if numeric is not None:
            bisect.insort(history, numeric)
        if numeric is None or len(history) < min_count:
            ranks.append("")
            continue
        rank = _interbank_rate_percentrank_inc_sheets(history, numeric)
        ranks.append("" if rank == "" else _interbank_rate_sheets_round(rank, 3))
    return ranks


def _interbank_rate_score_percentile(rank: Any) -> Any:
    return (
        ""
        if is_blank(rank)
        else _interbank_rate_sheets_round((float(rank) * 20) - 10, 2)
    )


def _interbank_rate_percent_display(value: Any, decimals: int = 2) -> Any:
    numeric = to_float_or_none(value)
    if numeric is None:
        return ""
    displayed = _interbank_rate_sheets_round(numeric * 100, decimals)
    if displayed == 0:
        displayed = 0.0
    return f"{displayed:.{decimals}f}%"


def _interbank_rate_weighted_sum(*terms: tuple[float, Any]) -> float:
    """Evaluate A28 formulas from rounded visible decimal operands."""
    total = Decimal("0")
    for weight, value in terms:
        total += Decimal(str(weight)) * Decimal(str(value))
    return float(total)


def _interbank_rate_threshold_value(value: Any) -> Any:
    numeric = to_float_or_none(value)
    if numeric is None:
        return ""
    for boundary in (0.30, 0.20, -0.20, -0.30):
        if math.isclose(numeric, boundary, rel_tol=0.0, abs_tol=1e-12):
            return boundary
    return numeric


def _interbank_rate_level_regime(c: Any, f: Any) -> str:
    if is_blank(c):
        return ""
    f_for_regime = 0.0 if is_blank(f) else f
    if c >= 3 and f_for_regime >= 0:
        return "Elevated and rising interbank-rate regime"
    if c >= 3 and f_for_regime < 0:
        return "Elevated but easing interbank-rate regime"
    if c >= 1 and f_for_regime >= 0:
        return "Moderate interbank rate and rising"
    if c >= 1 and f_for_regime < 0:
        return "Moderate interbank rate but easing"
    if c < 1 and f_for_regime >= 0:
        return "Low interbank rate but rising"
    if c < 1 and f_for_regime < 0:
        return "Low and easing interbank-rate regime"
    return "Mixed interbank-rate regime"


def _interbank_rate_policy_bias_label(y: Any) -> str:
    if is_blank(y):
        return ""
    if y >= 6:
        return "Strong hawkish policy-rate / money-market tightening bias"
    if y >= 2:
        return "Mild hawkish policy-rate / tighter money-market bias"
    if y <= -6:
        return "Strong dovish policy-rate / money-market easing bias"
    if y <= -2:
        return "Mild dovish policy-rate / easier money-market bias"
    return "Neutral interbank-rate policy bias"


def _interbank_rate_shock_label(e: Any) -> str:
    if is_blank(e):
        return ""
    threshold_value = _interbank_rate_threshold_value(e)
    if threshold_value >= 0.3:
        return "1M interbank-rate upside shock"
    if threshold_value <= -0.3:
        return "1M interbank-rate downside shock"
    return "No 1M interbank-rate shock"


def _interbank_rate_recovery_tightening_score(c: Any, f: Any, g: Any) -> Any:
    if any(is_blank(x) for x in (c, f, g)):
        return ""
    if c < 1 and f > 0 and g > 0:
        return 5
    if c >= 3 and f > 0 and g > 0:
        return 6
    if c >= 3 and f < 0 and g < 0:
        return -5
    if c < 1 and f < 0 and g < 0:
        return -6
    if f > 0 and g > 0:
        return 4
    if f < 0 and g < 0:
        return -4
    return 0


def _interbank_rate_shock_score(e: Any) -> Any:
    if is_blank(e):
        return ""
    threshold_value = _interbank_rate_threshold_value(e)
    if threshold_value >= 0.3:
        return 6
    if threshold_value >= 0.2:
        return 4
    if threshold_value <= -0.3:
        return -6
    if threshold_value <= -0.2:
        return -4
    return 0


def _interbank_rate_restriction_score(c: Any, f: Any, g: Any) -> Any:
    if any(is_blank(x) for x in (c, f, g)):
        return ""
    if c >= 5 and f > 0 and g > 0:
        return 6
    if c >= 3 and f > 0 and g > 0:
        return 4
