def _central_bank_liquidity_metric_ranks_sheets(
    values: Sequence[Any], min_count: int = 60
) -> list[Any]:
    """Rank each A29 metric against its own expanding numeric history."""
    history: list[float] = []
    ranks: list[Any] = []
    for value in values:
        numeric = to_float_or_none(value)
        if numeric is not None:
            bisect.insort(history, numeric)
        if numeric is None or len(history) < min_count:
            ranks.append("")
            continue
        rank = _central_bank_liquidity_percentrank_inc_sheets(history, numeric)
        ranks.append(
            "" if rank == "" else _central_bank_liquidity_sheets_round(rank, 3)
        )
    return ranks


