def _liquidity_growth(current: Any, lagged: Any, min_count_ok: bool) -> Any:
    if not min_count_ok or is_blank(current) or is_blank(lagged) or lagged == 0:
        return ""
    return current / lagged - 1


def _mtd_average_liquidity(dates: list[Any], net_values: list[Any]) -> list[Any]:
    month_groups: dict[tuple[int, int], list[tuple[date, float]]] = {}
    for dt, net in zip(dates, net_values):
        numeric = to_float_or_none(net)
        if dt is None or numeric is None:
            continue
        month_groups.setdefault((dt.year, dt.month), []).append((dt, numeric))
    prepared: dict[tuple[int, int], tuple[list[date], list[float]]] = {}
    for key, pairs in month_groups.items():
        pairs.sort(key=lambda item: item[0])
        group_dates: list[date] = []
        prefix: list[float] = [0.0]
        for dt, value in pairs:
            group_dates.append(dt)
            prefix.append(prefix[-1] + value)
        prepared[key] = (group_dates, prefix)
    out: list[Any] = []
    for dt in dates:
        if dt is None:
            out.append("")
            continue
        group_dates, prefix = prepared.get((dt.year, dt.month), ([], [0.0]))
        count = bisect.bisect_right(group_dates, dt)
        out.append("" if count == 0 else prefix[count] / count)
    return out


