def _broad_money_expansion_support_score(
    ak: Any, al: Any, am: Any, i: Any, j: Any
) -> Any:
    if any(is_blank(x) for x in (ak, al, am, i, j)):
        return ""
    if al > 1.5 and am > 1.5 and i > 0.10 and j > 0.08:
        return 6
    if al > 1 and am > 1 and i > 0.08:
        return 4
    if ak > 1.5 and al > 1 and i > 0.08:
        return 3
    return 0


def _broad_money_contraction_risk_score(
    ak: Any, al: Any, am: Any, i: Any, j: Any
) -> Any:
    if any(is_blank(x) for x in (ak, al, am, i, j)):
        return ""
    if al < -1.5 and am < -1.5 and i < 0.02 and j < 0.03:
        return -6
    if al < -1 and am < -1 and i < 0.04:
        return -4
    if al > 0 and am > 0 and i > 0.05 and j > 0.05:
        return 3
    return 0


