def _gov_revenue_sum_sheets(values: Sequence[Any]) -> Any:
    clean = [
        number
        for number in (to_float_or_none(value) for value in values)
        if number is not None
    ]
    if not clean:
        return ""
    total = clean[0]
    for number in clean[1:]:
        total += number
    return total


