def _gov_revenue_positive_or_blank(value: Any) -> bool:
    return value == "" or value > 0


def _gov_revenue_growth_regime(c: Any, f: Any, g: Any, h: Any) -> str:
    if is_blank(c):
        return ""
    if (
        c > 0
        and _gov_revenue_positive_or_blank(f)
        and _gov_revenue_positive_or_blank(g)
        and _gov_revenue_positive_or_blank(h)
    ):
        return "Government revenue expansion regime"
    if not any(is_blank(x) for x in (f, g, h)) and f < 0 and g < 0 and h < 0:
        return "Government revenue contraction regime"
    if not any(is_blank(x) for x in (f, g, h)) and f > 0 and g > 0 and h < 0:
        return "Early revenue recovery"
    if (
        not any(is_blank(x) for x in (f, g))
        and f < 0
        and g < 0
        and _gov_revenue_positive_or_blank(h)
    ):
        return "Revenue deterioration from high base"
    if not any(is_blank(x) for x in (f, g)) and f > 0 and g < 0:
        return "Short-term revenue recovery / mixed impulse"
    if not any(is_blank(x) for x in (f, g)) and f < 0 and g > 0:
        return "Short-term revenue deterioration / mixed impulse"
    return "Neutral/mixed revenue-growth regime"


