def calculate_government_revenue_outputs(raw_df: Any) -> Any:
    records = df_records(raw_df)
    raw_values = [
        to_float_or_none(r.get("Raw Value", r.get("B", r.get("Value", ""))))
        for r in records
    ]
    source_values = [
        r.get("Raw Value", r.get("B", r.get("Value", ""))) for r in records
    ]
    trailing_totals: list[Any] = []
    raw_count = 0
    for idx, current in enumerate(raw_values):
        if current is not None:
            raw_count += 1
        if raw_count < 12:
            trailing_totals.append("")
        else:
            window = [
                v for v in raw_values[max(0, idx - 11) : idx + 1] if v is not None
            ]
            trailing_totals.append(_gov_revenue_sum_sheets(window))

    observation_counts = _metric_counts(trailing_totals)
    one_growth: list[Any] = []
    three_growth: list[Any] = []
    six_growth: list[Any] = []
    twelve_growth: list[Any] = []
    three_annual: list[Any] = []
    six_annual: list[Any] = []
    for idx, c in enumerate(trailing_totals):
        d = observation_counts[idx]
        c1 = trailing_totals[idx - 1] if idx >= 1 else ""
        c3 = trailing_totals[idx - 3] if idx >= 3 else ""
        c6 = trailing_totals[idx - 6] if idx >= 6 else ""
        c12 = trailing_totals[idx - 12] if idx >= 12 else ""
        e = _gov_revenue_growth(c, c1, d >= 2)
        f = _gov_revenue_growth(c, c3, d >= 4)
        g = _gov_revenue_growth(c, c6, d >= 7)
        h = _gov_revenue_growth(c, c12, d >= 13)
        one_growth.append(e)
        three_growth.append(f)
        six_growth.append(g)
        twelve_growth.append(h)
        three_annual.append(_gov_revenue_annualized_growth(f, 4))
        six_annual.append(_gov_revenue_annualized_growth(g, 2))

    f_counts = _metric_counts(three_growth)
    g_counts = _metric_counts(six_growth)
    h_counts = _metric_counts(twelve_growth)
    i_counts = _metric_counts(three_annual)
    f_ranks = _gov_revenue_metric_ranks_sheets(three_growth)
    g_ranks = _gov_revenue_metric_ranks_sheets(six_growth)
    h_ranks = _gov_revenue_metric_ranks_sheets(twelve_growth)
    i_ranks = _gov_revenue_metric_ranks_sheets(three_annual)
    f_z = _gov_revenue_rounded_expanding_zscores(three_growth, f_counts)
    g_z = _gov_revenue_rounded_expanding_zscores(six_growth, g_counts)
    h_z = _gov_revenue_rounded_expanding_zscores(twelve_growth, h_counts)
    i_z = _gov_revenue_rounded_expanding_zscores(three_annual, i_counts)

    momentum_scores: list[Any] = []
    rows = []
    for idx, raw_source in enumerate(source_values):
        c = trailing_totals[idx]
        d = observation_counts[idx]
        e = one_growth[idx]
        f = three_growth[idx]
        g = six_growth[idx]
        h = twelve_growth[idx]
        i = three_annual[idx]
        j = six_annual[idx]
        k = f_ranks[idx]
        l = _gov_revenue_score_percentile(k)
        m = g_ranks[idx]
        n = _gov_revenue_score_percentile(m)
        o = h_ranks[idx]
        p_score = _gov_revenue_score_percentile(o)
        q = i_ranks[idx]
        r = _gov_revenue_score_percentile(q)
        v = (
            _gov_revenue_sheets_round(
                clamp(
                    _gov_revenue_weighted_sum(
                        (0.30, l), (0.35, n), (0.20, p_score), (0.15, r)
                    ),
                    -10,
                    10,
                ),
                2,
            )
            if all(not is_blank(value) for value in (l, n, p_score, r))
            else ""
        )
        momentum_scores.append(v)
        prev_v = momentum_scores[idx - 1] if idx >= 1 else ""
        w = (
            _gov_revenue_sheets_round(
                clamp(_gov_revenue_weighted_sum((2.0, v), (-2.0, prev_v)), -10, 10),
                2,
            )
            if not is_blank(v) and not is_blank(prev_v)
            else ""
        )
        x = _gov_revenue_recovery_score(f, g)
        y = _gov_revenue_shock_score(i)
        al = f_z[idx]
        am = g_z[idx]
        an = h_z[idx]
        ao = i_z[idx]
        z = _gov_revenue_deterioration_risk(al, am, an, ao)
        aa = _gov_revenue_windfall_score(al, am, ao, i)
        ab = _gov_revenue_outlier_score([al, am, an, ao])
        ac = v
        ad = (
            _gov_revenue_sheets_round(
                clamp(
                    _gov_revenue_weighted_sum((0.50, v), (0.30, w), (0.20, x)), -10, 10
                ),
                2,
            )
            if all(not is_blank(value) for value in (v, w, x))
            else ""
        )
        ae = _gov_revenue_warning_score(w, x, y, z, aa, ab)
        reliability = _gov_revenue_reliability(raw_source, d)
        data_status = (
            "Missing Data"
            if is_blank(raw_source)
            else (
                "Low Sample"
                if d < 40
                else (
                    "Incomplete Score"
                    if any(is_blank(value) for value in (ac, ad, ae))
                    else "Valid"
                )
            )
        )
        rows.append(
            {
                "12M rolling Government Revenue": c,
                "Sample Count": d,
                "1M Revenue Growth": _gov_revenue_percent_display(e),
                "3M Revenue Growth": _gov_revenue_percent_display(f),
                "6M Revenue Growth": _gov_revenue_percent_display(g),
                "12M YoY Revenue Growth": _gov_revenue_percent_display(h),
                "3M Annualised Revenue Growth": _gov_revenue_percent_display(i),
                "6M Annualised Revneue Growth": _gov_revenue_percent_display(j),
                "3M Growth Percentile": _gov_revenue_percent_display(k),
                "3M Growth Score": l,
                "6M Growth Percentile": _gov_revenue_percent_display(m),
                "6M Growth Score": n,
                "12M YoY Growth Percentile": _gov_revenue_percent_display(o),
                "12M YoY Growth Score": p_score,
                "3M Annualised Growth Percentile": _gov_revenue_percent_display(q),
                "3M Annualised Growth Score": r,
                "Revenue Growth Regime": _gov_revenue_growth_regime(c, f, g, h),
                "Fiscal Revenue Bias": _gov_revenue_asset_bias_label(ac),
                "Government Revenue Shock Flag": _gov_revenue_shock_label(i),
                "Government Revenue Impulse Score": v,
                "Government Revenue Acceleration Score": w,
                "Government Revenue Cycle Turning Point Score": x,
                "Government Revenue Shock Score": y,
                "Revenue Weakness Risk Score": z,
                "Revenue Overheating Score": aa,
                "Government Revenue Extreme Score": ab,
                "Coincident Score": ac,
                "Leading Score": ad,
                "Warning Score": ae,
                "State": _gov_revenue_conditions_regime(ac),
                "Regime": _gov_revenue_momentum_label(ac, ad),
                "Signal Comment": _gov_revenue_signal_interpretation(ad, ae),
                "Reliability": reliability,
                "Signal Validity": data_status,
                "Warning Flag": _gov_revenue_warning_label(ae),
                "3M Growth Z-Score": al,
                "6M Growth Z-Score": am,
                "12M Growth Z-Score": an,
                "3M Annualised Growth Z-Score": ao,
                "Extreme Flag": _gov_revenue_outlier_label([al, am, an, ao]),
            }
        )
    return make_dataframe(rows, GOVERNMENT_REVENUE_OUTPUT_COLUMNS)


def _score_percent_rank_inverted(rank: Any) -> Any:
    return "" if is_blank(rank) else round(10 - rank * 20, 2)


def _public_debt_regime(c: Any, g: Any) -> str:
    if is_blank(c):
        return ""
    if not is_blank(g) and c < 40 and g <= 0:
        return "Low debt and improving"
    if not is_blank(g) and c < 40 and g > 0:
        return "Low debt but rising"
    if not is_blank(g) and 40 <= c < 70 and g <= 0:
        return "Moderate debt and improving"
    if not is_blank(g) and 40 <= c < 70 and g > 0:
        return "Moderate debt and rising"
    if not is_blank(g) and 70 <= c < 100 and g <= 0:
        return "High debt but improving"
    if not is_blank(g) and 70 <= c < 100 and g > 0:
        return "High debt and rising"
    if not is_blank(g) and c >= 100 and g <= 0:
        return "Very high debt but improving"
    if not is_blank(g) and c >= 100 and g > 0:
        return "Very high debt and rising"
    return "Mixed public-debt regime"


def _public_debt_bias_label(aa: Any) -> str:
    if is_blank(aa):
        return ""
    if aa >= 6:
        return "Strong fiscal-sustainability support"
    if aa >= 2:
        return "Mild fiscal-sustainability support"
    if aa <= -6:
        return "Strong fiscal-sustainability headwind"
    if aa <= -2:
        return "Mild fiscal-sustainability headwind"
    return "Neutral fiscal-sustainability bias"


def _public_debt_shock_label(h: Any) -> str:
    if is_blank(h):
        return ""
    if h >= 8:
        return "Large debt-ratio deterioration shock"
    if h >= 4:
        return "Moderate debt-ratio deterioration"
    if h <= -8:
        return "Large debt-ratio improvement shock"
    if h <= -4:
        return "Moderate debt-ratio improvement"
    return "No major debt-ratio shock"


def _public_debt_vulnerability_score(c: Any, aj: Any, ak: Any, al: Any, am: Any) -> Any:
    if any(is_blank(x) for x in (c, aj, ak, al, am)):
        return ""
    if c >= 100 and ak > 0 and al > 0:
        return -7
    if c >= 70 and ak > 0 and al > 0:
        return -5
    if aj > 1.5 and ak > 0 and al > 0:
        return -4
    if c < 40 and ak < 0 and al < 0:
        return 4
    return 0


def _public_debt_recovery_score(e: Any, f: Any) -> Any:
    if any(is_blank(x) for x in (e, f)):
        return ""
    if e < 0 and f < 0:
        return 5
    if e > 0 and f > 0:
        return -5
    if e < 0 and f > 0:
        return 3
    if e > 0 and f < 0:
        return -3
    return 0


def _public_debt_shock_score(h: Any) -> Any:
    if is_blank(h):
        return ""
    if h >= 8:
        return -6
    if h >= 4:
        return -4
    if h <= -8:
        return 6
    if h <= -4:
        return 4
    return 0


def _public_debt_outlier_score(zs: Sequence[Any]) -> Any:
    if any(is_blank(z) for z in zs):
        return ""
    if any(z >= 3 for z in zs):
        return -6
    if any(z >= 2 for z in zs):
        return -4
    if any(z <= -3 for z in zs):
        return 6
    if any(z <= -2 for z in zs):
        return 4
    return 0


def _public_debt_conditions_regime(aa: Any) -> str:
    if is_blank(aa):
        return ""
    if aa >= 2:
        return "Public debt conditions improving"
    if aa <= -2:
        return "Public debt pressure building"
    return "Neutral public debt conditions"


def _public_debt_momentum_label(aa: Any, ab: Any) -> str:
    if any(is_blank(x) for x in (aa, ab)):
        return ""
    if aa >= 2 and ab >= 2:
        return "Public debt conditions improving"
    if aa >= 2 and ab <= -2:
        return "Debt conditions good but deteriorating"
    if aa >= 2 and -2 < ab < 2:
        return "Debt conditions supportive / stable"
    if aa <= -2 and ab >= 2:
        return "Debt pressure easing"
    if aa <= -2 and ab <= -2:
        return "Public debt pressure building"
    if aa <= -2 and -2 < ab < 2:
        return "Debt pressure elevated / stable"
    if -2 < aa < 2 and ab >= 2:
        return "Debt dynamics improving"
    if -2 < aa < 2 and ab <= -2:
        return "Debt dynamics deteriorating"
    return "Public debt broadly neutral"


def _public_debt_signal_interpretation(ab: Any, ac: Any) -> str:
    if any(is_blank(x) for x in (ab, ac)):
        return ""
    if ab >= 6 and ac >= 0:
        return "Strong public-debt sustainability improvement with supportive fiscal-space profile"
    if ab >= 6 and ac < 0:
        return "Strong debt-dynamics improvement, but vulnerability risk remains mixed"
    if ab >= 2 and ac >= 0:
        return "Moderately positive public-debt sustainability signal"
    if ab >= 2 and ac < 0:
        return "Debt dynamics improving, but high-debt vulnerability remains"
    if ab > -2 and ac > -3 and ac < 3:
        return "Neutral/mixed public-debt signal"
    if ab <= -6 and ac <= 0:
        return "Severe public-debt pressure building with downside confirmation"
    if ab <= -6 and ac > 0:
        return "Severe debt-pressure signal, but fiscal-space support remains partly intact"
    if ab <= -2 and ac <= 0:
        return "Moderate public-debt pressure building"
    if ab <= -2 and ac > 0:
        return "Debt pressure building, but vulnerability profile remains mixed"
    return "Mixed/transition public-debt signal"


def _public_debt_warning_label(ac: Any, u: Any, w: Any, y: Any, z: Any) -> str:
    if any(is_blank(x) for x in (ac, u, w, y, z)):
        return ""
    if z <= -6:
        return "High public-debt vulnerability warning"
    if z <= -4:
        return "Moderate public-debt vulnerability warning"
    if y <= -6:
        return "High debt-ratio shock warning"
    if y <= -4:
        return "Moderate debt-ratio shock warning"
    if w <= -6:
        return "High debt vulnerability warning"
    if w <= -4:
        return "Moderate high-debt vulnerability warning"
    if u <= -8:
        return "High public-debt pressure warning"
    if u <= -6:
        return "Moderate public-debt pressure warning"
    if ac >= 6:
        return "High debt-sustainability improvement signal"
    if ac >= 3:
        return "Moderate debt-sustainability improvement signal"
    if ac > -3:
        return "Neutral public-debt warning profile"
    if ac > -6:
        return "Moderate public-debt vulnerability warning"
    return "High public-debt vulnerability warning"


def _public_debt_outlier_label(zs: Sequence[Any]) -> str:
    if any(is_blank(z) for z in zs):
        return ""
    if any(z >= 3 for z in zs):
        return "Extreme public-debt stress"
    if any(z >= 2 for z in zs):
        return "Strong public-debt stress"
    if any(z <= -3 for z in zs):
        return "Extreme debt-sustainability improvement"
    if any(z <= -2 for z in zs):
        return "Strong debt-sustainability improvement"
    return "Normal range"


def calculate_public_debt_outputs(raw_df: Any) -> Any:
    records = df_records(raw_df)
    raw_values = [
        to_float_or_none(r.get("Raw Value", r.get("B", r.get("Value", ""))))
        for r in records
    ]
    source_values = [
        r.get("Raw Value", r.get("B", r.get("Value", ""))) for r in records
    ]
    ma_values = []
    raw_count = 0
    for idx, current in enumerate(raw_values):
        if current is not None:
            raw_count += 1
        if raw_count < 2:
            ma_values.append("")
        else:
            window = [v for v in raw_values[max(0, idx - 1) : idx + 1] if v is not None]
            ma_values.append(sum(window) / len(window) if window else "")
    observation_counts = _metric_counts(ma_values)
    one_changes = []
    two_changes = []
    four_changes = []
    one_annual = []
    two_annual = []
    for idx, c in enumerate(ma_values):
        d = observation_counts[idx]
        c1 = ma_values[idx - 1] if idx >= 1 else ""
        c2 = ma_values[idx - 2] if idx >= 2 else ""
        c4 = ma_values[idx - 4] if idx >= 4 else ""
        e = (c - c1) if d >= 2 and not is_blank(c) and not is_blank(c1) else ""
        f = (c - c2) if d >= 3 and not is_blank(c) and not is_blank(c2) else ""
        g = (c - c4) if d >= 5 and not is_blank(c) and not is_blank(c4) else ""
        one_changes.append(e)
        two_changes.append(f)
        four_changes.append(g)
        one_annual.append(e * 4 if not is_blank(e) else "")
        two_annual.append(f * 2 if not is_blank(f) else "")
    c_counts = _metric_counts(ma_values)
    e_counts = _metric_counts(one_changes)
    f_counts = _metric_counts(two_changes)
    g_counts = _metric_counts(four_changes)
    c_ranks = _expectations_metric_ranks(ma_values, 40)
    e_ranks = _expectations_metric_ranks(one_changes, 40)
    f_ranks = _expectations_metric_ranks(two_changes, 40)
    g_ranks = _expectations_metric_ranks(four_changes, 40)
    c_z = _rounded_expanding_zscores(ma_values, c_counts, 40)
    e_z = _rounded_expanding_zscores(one_changes, e_counts, 40)
    f_z = _rounded_expanding_zscores(two_changes, f_counts, 40)
    g_z = _rounded_expanding_zscores(four_changes, g_counts, 40)
    momentum_scores = []
    rows = []
    for idx, raw_source in enumerate(source_values):
        c = ma_values[idx]
        d = observation_counts[idx]
        e = one_changes[idx]
        f = two_changes[idx]
        g = four_changes[idx]
        h = one_annual[idx]
        i = two_annual[idx]
        j = c_ranks[idx]
        k = _score_percent_rank_inverted(j)
        l = e_ranks[idx]
        m = _score_percent_rank_inverted(l)
        n = f_ranks[idx]
        o = _score_percent_rank_inverted(n)
        p = g_ranks[idx]
        q = _score_percent_rank_inverted(p)
        u = (
            round(clamp(0.35 * k + 0.25 * m + 0.25 * o + 0.15 * q, -10, 10), 2)
            if all(not is_blank(x) for x in (k, m, o, q))
            else ""
        )
        momentum_scores.append(u)
        prev_u = momentum_scores[idx - 1] if idx >= 1 else ""
        v = (
            round(clamp((u - prev_u) * 2, -10, 10), 2)
            if not is_blank(u) and not is_blank(prev_u)
            else ""
        )
        aj = c_z[idx]
        ak = e_z[idx]
        al = f_z[idx]
        am = g_z[idx]
        w = _public_debt_vulnerability_score(c, aj, ak, al, am)
        x = _public_debt_recovery_score(e, f)
        y = _public_debt_shock_score(h)
        z = _public_debt_outlier_score([aj, ak, al, am])
        aa = (
            round(clamp(0.40 * k + 0.25 * m + 0.20 * o + 0.15 * q, -10, 10), 2)
            if all(not is_blank(val) for val in (k, m, o, q))
            else ""
        )
        ab = (
            round(clamp(0.40 * u + 0.25 * v + 0.25 * w + 0.10 * x, -10, 10), 2)
            if all(not is_blank(val) for val in (u, v, w, x))
            else ""
        )
        ac = (
            round(
                clamp(0.20 * v + 0.35 * w + 0.15 * x + 0.20 * y + 0.10 * z, -10, 10), 2
            )
            if all(not is_blank(val) for val in (v, w, x, y, z))
            else ""
        )
        reliability = (
            ""
            if is_blank(raw_source)
            else (
                "Insufficient history"
                if d < 40
                else ("Medium reliability" if d < 80 else "High reliability")
            )
        )
        data_status = (
            "Missing Data"
            if is_blank(raw_source)
            else (
                "Low Sample"
                if d < 40
                else (
                    "Incomplete Score"
                    if any(is_blank(val) for val in (aa, ab, ac))
                    else "Valid"
                )
            )
        )
        rows.append(
            {
                "2-Period Moving Average Public Debt": c,
                "Public Debt Observation Count": d,
                "1-Period Public Debt Change": e,
                "2-Period Public Debt Change": f,
                "4-Period Public Debt Change": g,
                "1-Period Annualised Public Debt Change": h,
                "2-Period Annualised Public Debt Change": i,
                "Public Debt Level PercentRank": j,
                "Public Debt Level Score": k,
                "1-Period Public Debt Change PercentRank": l,
                "1-Period Public Debt Change Score": m,
                "2-Period Public Debt Change PercentRank": n,
                "2-Period Public Debt Change Score": o,
                "4-Period Public Debt Change PercentRank": p,
                "4-Period Public Debt Change Score": q,
                "Public Debt Regime": _public_debt_regime(c, g),
                "Public Debt Fiscal-Sustainability Bias Label": _public_debt_bias_label(
                    aa
                ),
                "Public Debt Shock Label": _public_debt_shock_label(h),
                "Public Debt Momentum Composite Score": u,
                "Public Debt Momentum Turn Score": v,
                "Public Debt Level / Vulnerability Score": w,
                "Public Debt Recovery / Deterioration Score": x,
                "Public Debt Shock Score": y,
                "Public Debt Outlier Score": z,
                "Public Debt Leading Score": aa,
                "Public Debt Warning Composite Score": ab,
                "Public Debt Final Warning Score": ac,
                "Public Debt Conditions Regime": _public_debt_conditions_regime(aa),
                "Public Debt Momentum Label": _public_debt_momentum_label(aa, ab),
                "Public Debt Signal Interpretation": _public_debt_signal_interpretation(
                    ab, ac
                ),
                "Reliability": reliability,
                "Data Status": data_status,
                "Public Debt Warning Risk Label": _public_debt_warning_label(
                    ac, u, w, y, z
                ),
                "Public Debt Level Z-Score": aj,
                "1-Period Public Debt Change Z-Score": ak,
                "2-Period Public Debt Change Z-Score": al,
                "4-Period Public Debt Change Z-Score": am,
                "Public Debt Outlier Label": _public_debt_outlier_label(
                    [aj, ak, al, am]
                ),
            }
        )
    return make_dataframe(rows, PUBLIC_DEBT_OUTPUT_COLUMNS)


def _interest_coverage_regime(e: Any, h: Any) -> str:
    if is_blank(e):
        return ""
    if not is_blank(h) and e >= 8 and h > 0:
        return "Very strong coverage and improving"
    if not is_blank(h) and e >= 8 and h <= 0:
        return "Very strong coverage but weakening"
    if not is_blank(h) and 4 <= e < 8 and h > 0:
        return "Healthy coverage and improving"
    if not is_blank(h) and 4 <= e < 8 and h <= 0:
        return "Healthy coverage but weakening"
    if not is_blank(h) and 2 <= e < 4 and h > 0:
        return "Thin coverage but improving"
    if not is_blank(h) and 2 <= e < 4 and h <= 0:
        return "Thin coverage and weakening"
    if not is_blank(h) and e < 2 and h > 0:
        return "Severe interest burden but improving"
    if not is_blank(h) and e < 2 and h <= 0:
        return "Severe interest burden and worsening"
    return "Mixed interest-coverage regime"


def _interest_coverage_bias_label(aa: Any) -> str:
    if is_blank(aa):
        return ""
    if aa >= 6:
        return "Strong fiscal-stress relief / strong debt-servicing capacity"
    if aa >= 2:
        return "Mild fiscal-stress relief"
    if aa <= -6:
        return "Strong fiscal-stress pressure from interest burden"
    if aa <= -2:
        return "Mild fiscal-stress pressure from interest burden"
    return "Neutral fiscal-stress bias"


def _interest_coverage_shock_label(g: Any) -> str:
    if is_blank(g):
        return ""
    if g >= 2:
        return "Large improvement in interest coverage"
    if g >= 1:
        return "Moderate improvement in interest coverage"
    if g <= -2:
        return "Large deterioration in interest coverage"
    if g <= -1:
        return "Moderate deterioration in interest coverage"
    return "No major interest-coverage shock"


def _interest_coverage_vulnerability_score(
    e: Any, aj: Any, ak: Any, al: Any, am: Any
) -> Any:
    if any(is_blank(x) for x in (e, aj, ak, al, am)):
        return ""
    if e < 2 and ak < 0 and al < 0:
        return -7
    if e < 4 and ak < 0 and al < 0:
        return -5
    if aj < -1.5 and ak < 0 and al < 0:
        return -4
    if e >= 8 and ak > 0 and al > 0:
        return 4
    return 0


def _interest_coverage_recovery_score(g: Any, h: Any) -> Any:
    if any(is_blank(x) for x in (g, h)):
        return ""
    if g > 0 and h > 0:
        return 5
    if g < 0 and h < 0:
        return -5
    if g > 0 and h < 0:
        return 3
    if g < 0 and h > 0:
        return -3
    return 0


def _interest_coverage_shock_score(g: Any) -> Any:
    if is_blank(g):
        return ""
    if g >= 2:
        return 6
    if g >= 1:
        return 4
    if g <= -2:
        return -6
    if g <= -1:
        return -4
    return 0


def _interest_coverage_outlier_score(zs: Sequence[Any]) -> Any:
    if any(is_blank(z) for z in zs):
        return ""
    if any(z >= 3 for z in zs):
        return 6
    if any(z >= 2 for z in zs):
        return 4
    if any(z <= -3 for z in zs):
        return -6
    if any(z <= -2 for z in zs):
        return -4
    return 0


def _interest_coverage_conditions_regime(aa: Any) -> str:
    if is_blank(aa):
        return ""
    if aa >= 2:
        return "Interest coverage improving"
    if aa <= -2:
        return "Interest coverage stress building"
    return "Neutral interest coverage conditions"


def _interest_coverage_momentum_label(aa: Any, ab: Any) -> str:
    if any(is_blank(x) for x in (aa, ab)):
        return ""
    if aa >= 2 and ab >= 2:
        return "Interest coverage improving"
    if aa >= 2 and ab <= -2:
        return "Coverage conditions good but deteriorating"
    if aa >= 2 and -2 < ab < 2:
        return "Coverage conditions supportive / stable"
    if aa <= -2 and ab >= 2:
        return "Interest-coverage stress easing"
    if aa <= -2 and ab <= -2:
        return "Interest-coverage stress building"
    if aa <= -2 and -2 < ab < 2:
        return "Coverage stress elevated / stable"
    if -2 < aa < 2 and ab >= 2:
        return "Coverage dynamics improving"
    if -2 < aa < 2 and ab <= -2:
        return "Coverage dynamics deteriorating"
    return "Interest coverage broadly neutral"


def _interest_coverage_signal_interpretation(ab: Any, ac: Any) -> str:
    if any(is_blank(x) for x in (ab, ac)):
        return ""
    if ab >= 6 and ac >= 0:
        return "Strong debt-servicing capacity improvement with supportive fiscal-stress profile"
    if ab >= 6 and ac < 0:
        return (
            "Strong coverage improvement, but low-coverage vulnerability remains mixed"
        )
    if ab >= 2 and ac >= 0:
        return "Moderately positive interest-coverage sustainability signal"
    if ab >= 2 and ac < 0:
        return "Coverage dynamics improving, but vulnerability remains"
    if ab > -2 and ac > -3 and ac < 3:
        return "Neutral/mixed interest-coverage signal"
    if ab <= -6 and ac <= 0:
        return "Severe interest-coverage stress building with downside confirmation"
    if ab <= -6 and ac > 0:
        return "Severe coverage-stress signal, but fiscal-stress relief remains partly intact"
    if ab <= -2 and ac <= 0:
        return "Moderate interest-coverage stress building"
    if ab <= -2 and ac > 0:
        return "Coverage stress building, but vulnerability profile remains mixed"
    return "Mixed/transition interest-coverage signal"


def _interest_coverage_warning_label(ac: Any, u: Any, w: Any, y: Any, z: Any) -> str:
    if any(is_blank(x) for x in (ac, u, w, y, z)):
        return ""
    if z <= -6:
        return "High interest-coverage stress warning"
    if z <= -4:
        return "Moderate interest-coverage stress warning"
    if y <= -6:
        return "High interest-coverage deterioration shock"
    if y <= -4:
        return "Moderate interest-coverage deterioration shock"
    if w <= -6:
        return "High low-coverage vulnerability warning"
    if w <= -4:
        return "Moderate low-coverage vulnerability warning"
    if u <= -8:
        return "High interest-coverage pressure warning"
    if u <= -6:
        return "Moderate interest-coverage pressure warning"
    if ac >= 6:
        return "High interest-coverage improvement signal"
    if ac >= 3:
        return "Moderate interest-coverage improvement signal"
    if ac > -3:
        return "Neutral interest-coverage warning profile"
    if ac > -6:
        return "Moderate interest-coverage vulnerability warning"
    return "High interest-coverage vulnerability warning"


def _interest_coverage_outlier_label(zs: Sequence[Any]) -> str:
    if any(is_blank(z) for z in zs):
        return ""
    if any(z >= 3 for z in zs):
        return "Extreme interest-coverage strength"
    if any(z >= 2 for z in zs):
        return "Strong interest-coverage strength"
    if any(z <= -3 for z in zs):
        return "Extreme interest-coverage stress"
    if any(z <= -2 for z in zs):
        return "Strong interest-coverage stress"
    return "Normal range"


def calculate_interest_coverage_outputs(raw_df: Any) -> Any:
    records = df_records(raw_df)
    b_values = [
        to_float_or_none(r.get("Raw Value", r.get("B", r.get("Revenue", ""))))
        for r in records
    ]
    c_values = [
        to_float_or_none(
            r.get(
                "Source C", r.get("C", r.get("Interest Expense", r.get("Interest", "")))
            )
        )
        for r in records
    ]
    source_b = [r.get("Raw Value", r.get("B", r.get("Revenue", ""))) for r in records]
    ratios = []
    for b, c in zip(b_values, c_values):
        ratios.append("" if c is None or c == 0 or b is None else b / c)
    smoothed = []
    ratio_count = 0
    for idx, d in enumerate(ratios):
        if to_float_or_none(d) is not None:
            ratio_count += 1
        if ratio_count < 3:
            smoothed.append("")
        else:
            window = [to_float_or_none(v) for v in ratios[max(0, idx - 2) : idx + 1]]
            nums = [v for v in window if v is not None]
            smoothed.append(sum(nums) / len(nums) if nums else "")
    observation_counts = _metric_counts(smoothed)
    one_changes = []
    three_changes = []
    five_changes = []
    for idx, e in enumerate(smoothed):
        f_count = observation_counts[idx]
        e1 = smoothed[idx - 1] if idx >= 1 else ""
        e3 = smoothed[idx - 3] if idx >= 3 else ""
        e5 = smoothed[idx - 5] if idx >= 5 else ""
        g = (e - e1) if f_count >= 2 and not is_blank(e) and not is_blank(e1) else ""
        h = (e - e3) if f_count >= 4 and not is_blank(e) and not is_blank(e3) else ""
        i = (e - e5) if f_count >= 6 and not is_blank(e) and not is_blank(e5) else ""
        one_changes.append(g)
        three_changes.append(h)
        five_changes.append(i)
    e_counts = _metric_counts(smoothed)
    g_counts = _metric_counts(one_changes)
    h_counts = _metric_counts(three_changes)
    i_counts = _metric_counts(five_changes)
    e_ranks = _expectations_metric_ranks(smoothed, 20)
    g_ranks = _expectations_metric_ranks(one_changes, 20)
    h_ranks = _expectations_metric_ranks(three_changes, 20)
    i_ranks = _expectations_metric_ranks(five_changes, 20)
    e_z = _rounded_expanding_zscores(smoothed, e_counts, 20)
    g_z = _rounded_expanding_zscores(one_changes, g_counts, 20)
    h_z = _rounded_expanding_zscores(three_changes, h_counts, 20)
    i_z = _rounded_expanding_zscores(five_changes, i_counts, 20)
    momentum_scores = []
    rows = []
    for idx, raw_b in enumerate(source_b):
        d = ratios[idx]
        e = smoothed[idx]
        f_count = observation_counts[idx]
        g = one_changes[idx]
        h = three_changes[idx]
        i = five_changes[idx]
        j = e_ranks[idx]
        k = _score_percent_rank(j)
        l = g_ranks[idx]
        m = _score_percent_rank(l)
        n = h_ranks[idx]
        o = _score_percent_rank(n)
        p = i_ranks[idx]
        q = _score_percent_rank(p)
        u = (
            round(clamp(0.35 * k + 0.25 * m + 0.25 * o + 0.15 * q, -10, 10), 2)
            if all(not is_blank(x) for x in (k, m, o, q))
            else ""
        )
        momentum_scores.append(u)
        prev_u = momentum_scores[idx - 1] if idx >= 1 else ""
        v = (
            round(clamp((u - prev_u) * 2, -10, 10), 2)
            if not is_blank(u) and not is_blank(prev_u)
            else ""
        )
        aj = e_z[idx]
        ak = g_z[idx]
        al = h_z[idx]
        am = i_z[idx]
        w = _interest_coverage_vulnerability_score(e, aj, ak, al, am)
        x = _interest_coverage_recovery_score(g, h)
        y = _interest_coverage_shock_score(g)
        z = _interest_coverage_outlier_score([aj, ak, al, am])
        aa = (
            round(clamp(0.40 * k + 0.25 * m + 0.20 * o + 0.15 * q, -10, 10), 2)
            if all(not is_blank(val) for val in (k, m, o, q))
            else ""
        )
        ab = (
            round(clamp(0.40 * u + 0.25 * v + 0.25 * w + 0.10 * x, -10, 10), 2)
            if all(not is_blank(val) for val in (u, v, w, x))
            else ""
        )
        ac = (
            round(
                clamp(0.20 * v + 0.35 * w + 0.15 * x + 0.20 * y + 0.10 * z, -10, 10), 2
            )
            if all(not is_blank(val) for val in (v, w, x, y, z))
            else ""
        )
        reliability = (
            ""
            if is_blank(raw_b)
            else (
                "Insufficient history"
                if f_count < 20
                else ("Medium reliability" if f_count < 40 else "High reliability")
            )
        )
        data_status = (
            "Missing Data"
            if is_blank(raw_b)
            else (
                "Low Sample"
                if f_count < 20
                else (
                    "Incomplete Score"
                    if any(is_blank(val) for val in (aa, ab, ac))
                    else "Valid"
                )
            )
        )
        rows.append(
            {
                "Raw Interest Coverage Ratio": d,
                "3-Period Moving Average Interest Coverage": e,
                "Interest Coverage Observation Count": f_count,
                "1-Period Interest Coverage Change": g,
                "3-Period Interest Coverage Change": h,
                "5-Period Interest Coverage Change": i,
                "Interest Coverage Level PercentRank": j,
                "Interest Coverage Level Score": k,
                "1-Period Interest Coverage Change PercentRank": l,
                "1-Period Interest Coverage Change Score": m,
                "3-Period Interest Coverage Change PercentRank": n,
                "3-Period Interest Coverage Change Score": o,
                "5-Period Interest Coverage Change PercentRank": p,
                "5-Period Interest Coverage Change Score": q,
                "Interest Coverage Regime": _interest_coverage_regime(e, h),
                "Interest Coverage Fiscal-Stress Bias Label": _interest_coverage_bias_label(
                    aa
                ),
                "Interest Coverage Shock Label": _interest_coverage_shock_label(g),
                "Interest Coverage Momentum Composite Score": u,
                "Interest Coverage Momentum Turn Score": v,
                "Interest Coverage Level / Vulnerability Score": w,
                "Interest Coverage Recovery / Deterioration Score": x,
                "Interest Coverage Shock Score": y,
                "Interest Coverage Outlier Score": z,
                "Interest Coverage Leading Score": aa,
                "Interest Coverage Warning Composite Score": ab,
                "Interest Coverage Final Warning Score": ac,
                "Interest Coverage Conditions Regime": _interest_coverage_conditions_regime(
                    aa
                ),
                "Interest Coverage Momentum Label": _interest_coverage_momentum_label(
                    aa, ab
                ),
                "Interest Coverage Signal Interpretation": _interest_coverage_signal_interpretation(
                    ab, ac
                ),
                "Reliability": reliability,
                "Data Status": data_status,
                "Interest Coverage Warning Risk Label": _interest_coverage_warning_label(
                    ac, u, w, y, z
                ),
                "Interest Coverage Level Z-Score": aj,
                "1-Period Interest Coverage Change Z-Score": ak,
                "3-Period Interest Coverage Change Z-Score": al,
                "5-Period Interest Coverage Change Z-Score": am,
                "Interest Coverage Outlier Label": _interest_coverage_outlier_label(
                    [aj, ak, al, am]
                ),
            }
        )
    return make_dataframe(rows, INTEREST_COVERAGE_OUTPUT_COLUMNS)


def _financial_conditions_sheets_round(value: Any, places: int = 2) -> Any:
    """A37-only Google Sheets ROUND semantics."""
    return _real_yield_sheets_round(value, places)


def _financial_conditions_mean_sheets(values: Sequence[Any]) -> Any:
    """A37-only spreadsheet-order average over numeric cells."""
    return _real_yield_mean_sheets(values)


def _financial_conditions_percentrank_inc_sheets(
    values: Sequence[float], current: Any
) -> Any:
    """A37-only Google Sheets PERCENTRANK.INC semantics."""
    return _real_yield_percentrank_inc_sheets(values, current)


def _financial_conditions_metric_ranks_sheets(
    values: Sequence[Any], min_count: int = 60
) -> list[Any]:
    """Rank an A37 metric once its own numeric history reaches min_count."""
    history: list[float] = []
    ranks: list[Any] = []
    for value in values:
        numeric = to_float_or_none(value)
        if numeric is not None:
            bisect.insort(history, numeric)
        if numeric is None or len(history) < min_count:
            ranks.append("")
            continue
        rank = _financial_conditions_percentrank_inc_sheets(history, numeric)
        ranks.append("" if rank == "" else _financial_conditions_sheets_round(rank, 3))
    return ranks


def _financial_conditions_score_percentile(rank: Any) -> Any:
    if is_blank(rank):
        return ""
    return _financial_conditions_sheets_round(10 - (float(rank) * 20), 2)


def _financial_conditions_percent_display(value: Any, decimals: int = 2) -> Any:
    numeric = to_float_or_none(value)
    if numeric is None:
        return ""
    displayed = _financial_conditions_sheets_round(numeric * 100, decimals)
    if displayed == 0:
        displayed = 0.0
    return f"{displayed:.{decimals}f}%"


def _financial_conditions_weighted_sum(*terms: tuple[float, Any]) -> float:
    """Evaluate A37 composites from their rounded visible score operands."""
    total = Decimal("0")
    for weight, value in terms:
        total += Decimal(str(weight)) * Decimal(str(value))
    return float(total)


def _financial_conditions_rounded_expanding_zscores(
    values: list[object], counts: list[int], min_count: int = 60
) -> list[object]:
    return [
        "" if is_blank(z) else _financial_conditions_sheets_round(float(z), 2)
        for z in expanding_zscore_sample(values, counts, min_count)
    ]


def _financial_conditions_to_date_or_none(value: Any) -> date | None:
    """Parse A37 dates, including its live sheet's day-first display format."""
    text = str(value).strip()
    if "/" in text:
        for fmt in ("%d/%m/%Y", "%d/%m/%y"):
            try:
                return datetime.strptime(text, fmt).date()
            except ValueError:
                pass
    return to_date_or_none(value)


def _financial_conditions_month_to_date_averages(
    records: Sequence[dict[str, Any]],
) -> list[Any]:
    parsed_dates = [
        _financial_conditions_to_date_or_none(r.get("Date", "")) for r in records
    ]
    raw_values = [to_float_or_none(r.get("Raw Value", r.get("B", ""))) for r in records]
    by_month: dict[tuple[int, int], list[tuple[date, float]]] = {}
    for current_date, value in zip(parsed_dates, raw_values):
        if current_date is None or value is None:
            continue
        by_month.setdefault((current_date.year, current_date.month), []).append(
            (current_date, value)
        )
    month_dates: dict[tuple[int, int], list[date]] = {}
    month_prefix: dict[tuple[int, int], list[float]] = {}
    for key, pairs in by_month.items():
        pairs.sort(key=lambda item: item[0])
        dates = [item[0] for item in pairs]
        prefix = [0.0]
        for _, value in pairs:
            prefix.append(prefix[-1] + value)
        month_dates[key] = dates
        month_prefix[key] = prefix
    averages: list[Any] = []
    for current_date in parsed_dates:
        if current_date is None:
            averages.append("")
            continue
        key = (current_date.year, current_date.month)
        dates = month_dates.get(key, [])
        count = bisect.bisect_right(dates, current_date)
        averages.append(month_prefix[key][count] / count if count else "")
    return averages


def _financial_conditions_regime(e: Any, g: Any) -> str:
    if is_blank(e):
        return ""
    if not is_blank(g) and e < 0 and g < 0:
        return "Easy and easing financial conditions"
    if not is_blank(g) and e < 0 and g >= 0:
        return "Easy but tightening financial conditions"
    if not is_blank(g) and e >= 0 and g < 0:
        return "Tight but easing financial conditions"
    if not is_blank(g) and e >= 0 and g >= 0:
        return "Tight and tightening financial conditions"
    return "Mixed financial conditions regime"


def _financial_conditions_asset_bias_label(z: Any) -> str:
    if is_blank(z):
        return ""
    if z >= 6:
        return "Strongly supportive for risk assets / credit / equities"
    if z >= 2:
        return "Mildly supportive for risk assets"
    if z <= -6:
        return "Strong headwind for risk assets / credit / equities"
    if z <= -2:
        return "Mild headwind for risk assets"
    return "Neutral risk-asset bias"


def _financial_conditions_shock_label(f: Any) -> str:
    if is_blank(f):
        return ""
    if f >= 0.75:
        return "Large financial-conditions tightening shock"
    if f >= 0.40:
        return "Moderate financial-conditions tightening shock"
    if f <= -0.75:
        return "Large financial-conditions easing shock"
    if f <= -0.40:
        return "Moderate financial-conditions easing shock"
    return "No major financial-conditions shock"


def _financial_conditions_stress_easing_score(
    ai: Any, aj: Any, ak: Any, e: Any, g: Any, h: Any
) -> Any:
    if any(is_blank(x) for x in (ai, aj, ak, e, g, h)):
        return ""
    if ai > 1.5 and aj > 0 and ak > 0 and g > 0 and h > 0:
        return -7
    if ai > 1 and aj > 0 and g > 0:
        return -5
    if ai < -1 and aj < 0 and ak < 0 and g < 0 and h < 0:
        return 5
    if aj < -1 and ak < -1 and g < 0 and h < 0:
        return 4
    return 0


def _financial_conditions_shock_score(f: Any) -> Any:
    if is_blank(f):
        return ""
    if f >= 0.75:
        return -6
    if f >= 0.40:
        return -4
    if f <= -0.75:
        return 6
    if f <= -0.40:
        return 4
    return 0


def _financial_conditions_recovery_score(g: Any, h: Any) -> Any:
    if any(is_blank(x) for x in (g, h)):
        return ""
    if g < 0 and h < 0:
        return 5
    if g > 0 and h > 0:
        return -5
    if g < 0 and h > 0:
        return 3
    if g > 0 and h < 0:
        return -3
    return 0


def _financial_conditions_outlier_score(zs: Sequence[Any]) -> Any:
    if any(is_blank(z) for z in zs):
        return ""
    if any(z >= 3 for z in zs):
        return -6
    if any(z >= 2 for z in zs):
        return -4
    if any(z <= -3 for z in zs):
        return 6
    if any(z <= -2 for z in zs):
        return 4
    return 0


def _financial_conditions_regime_signal(z: Any) -> str:
    if is_blank(z):
        return ""
    if z >= 2:
        return "Financial conditions easing / supportive"
    if z <= -2:
        return "Financial conditions tightening / restrictive"
    return "Neutral financial conditions"


def _financial_conditions_momentum_label(z: Any, aa: Any) -> str:
    if any(is_blank(x) for x in (z, aa)):
        return ""
    if z >= 2 and aa >= 2:
        return "Financial conditions easing / supportive"
    if z >= 2 and aa <= -2:
        return "Financial conditions easy but tightening"
    if z >= 2 and -2 < aa < 2:
        return "Financial conditions supportive / stable"
    if z <= -2 and aa >= 2:
        return "Financial stress easing"
    if z <= -2 and aa <= -2:
        return "Financial conditions tightening / restrictive"
    if z <= -2 and -2 < aa < 2:
        return "Financial conditions tight / stable"
    if -2 < z < 2 and aa >= 2:
        return "Financial conditions impulse easing"
    if -2 < z < 2 and aa <= -2:
        return "Financial conditions impulse tightening"
    return "Financial conditions broadly neutral"


def _financial_conditions_signal_interpretation(aa: Any, ab: Any) -> str:
    if any(is_blank(x) for x in (aa, ab)):
        return ""
    if aa >= 6 and ab >= 0:
        return "Strong financial-conditions easing signal with supportive risk-asset profile"
    if aa >= 6 and ab < 0:
        return "Strong financial-conditions easing signal, but stress-risk profile remains mixed"
    if aa >= 2 and ab >= 0:
        return "Moderately positive financial-conditions easing signal"
    if aa >= 2 and ab < 0:
        return "Financial conditions easing, but stress risk remains fragile"
    if aa > -2 and ab > -3 and ab < 3:
        return "Neutral/mixed financial-conditions signal"
    if aa <= -6 and ab <= 0:
        return (
            "Severe financial-conditions tightening signal with downside confirmation"
        )
    if aa <= -6 and ab > 0:
        return (
            "Severe financial-stress signal, but easing support remains partly intact"
        )
    if aa <= -2 and ab <= 0:
        return "Moderately negative financial-conditions tightening signal"
    if aa <= -2 and ab > 0:
        return "Financial conditions tightening, but stress profile remains mixed"
    return "Mixed/transition financial-conditions signal"


def _financial_conditions_warning_label(ab: Any, v: Any, w: Any, y: Any) -> str:
    if any(is_blank(x) for x in (ab, v, w, y)):
        return ""
    if y <= -6:
        return "High financial-stress extreme warning"
    if y <= -4:
        return "Moderate financial-stress extreme warning"
    if w <= -6:
        return "High financial-conditions tightening shock"
    if w <= -4:
        return "Moderate financial-conditions tightening shock"
    if v <= -6:
        return "High financial-stress warning"
    if v <= -4:
        return "Moderate financial-stress warning"
    if ab >= 6:
        return "High financial-conditions easing signal"
    if ab >= 3:
        return "Moderate financial-conditions easing signal"
    if ab > -3:
        return "Neutral financial-conditions warning profile"
    if ab > -6:
        return "Moderate financial-conditions tightening warning"
    return "High financial-conditions tightening warning"


def _financial_conditions_outlier_label(zs: Sequence[Any]) -> str:
    if any(is_blank(z) for z in zs):
        return ""
    if any(z >= 3 for z in zs):
        return "Extreme financial-stress tightening"
    if any(z >= 2 for z in zs):
        return "Strong financial-stress tightening"
    if any(z <= -3 for z in zs):
        return "Extreme financial-conditions easing"
    if any(z <= -2 for z in zs):
        return "Strong financial-conditions easing"
    return "Normal range"


def calculate_financial_conditions_outputs(raw_df: Any) -> Any:
    records = df_records(raw_df)
    source_values = [r.get("Raw Value", r.get("B", "")) for r in records]
    c_values = _financial_conditions_month_to_date_averages(records)
    c_counts = _metric_counts(c_values)
    smoothed: list[Any] = []
    for idx, _ in enumerate(c_values):
        if c_counts[idx] < 3:
            smoothed.append("")
        else:
            smoothed.append(
                _financial_conditions_mean_sheets(c_values[max(0, idx - 2) : idx + 1])
            )
    observation_counts = _metric_counts(smoothed)
    one_changes: list[Any] = []
    three_changes: list[Any] = []
    six_changes: list[Any] = []
    twelve_changes: list[Any] = []
    for idx, e in enumerate(smoothed):
        d = observation_counts[idx]
        e1 = smoothed[idx - 1] if idx >= 1 else ""
        e3 = smoothed[idx - 3] if idx >= 3 else ""
        e6 = smoothed[idx - 6] if idx >= 6 else ""
        e12 = smoothed[idx - 12] if idx >= 12 else ""
        one_changes.append(
            e - e1 if d >= 2 and not is_blank(e) and not is_blank(e1) else ""
        )
        three_changes.append(
            e - e3 if d >= 4 and not is_blank(e) and not is_blank(e3) else ""
        )
        six_changes.append(
            e - e6 if d >= 7 and not is_blank(e) and not is_blank(e6) else ""
        )
        twelve_changes.append(
            e - e12 if d >= 13 and not is_blank(e) and not is_blank(e12) else ""
        )
    e_counts = _metric_counts(smoothed)
    g_counts = _metric_counts(three_changes)
    h_counts = _metric_counts(six_changes)
    i_counts = _metric_counts(twelve_changes)
    e_ranks = _financial_conditions_metric_ranks_sheets(smoothed)
    g_ranks = _financial_conditions_metric_ranks_sheets(three_changes)
    h_ranks = _financial_conditions_metric_ranks_sheets(six_changes)
    i_ranks = _financial_conditions_metric_ranks_sheets(twelve_changes)
    e_z = _financial_conditions_rounded_expanding_zscores(smoothed, e_counts)
    g_z = _financial_conditions_rounded_expanding_zscores(three_changes, g_counts)
    h_z = _financial_conditions_rounded_expanding_zscores(six_changes, h_counts)
    i_z = _financial_conditions_rounded_expanding_zscores(twelve_changes, i_counts)
    rows: list[dict[str, Any]] = []
    for idx, raw_source in enumerate(source_values):
        c = c_values[idx]
        d = observation_counts[idx]
        e = smoothed[idx]
        f = one_changes[idx]
        g = three_changes[idx]
        h = six_changes[idx]
        i = twelve_changes[idx]
        j_internal = e_ranks[idx]
        k = _financial_conditions_score_percentile(j_internal)
        l_internal = g_ranks[idx]
        m = _financial_conditions_score_percentile(l_internal)
        n_internal = h_ranks[idx]
        o = _financial_conditions_score_percentile(n_internal)
        p_internal = i_ranks[idx]
        q = _financial_conditions_score_percentile(p_internal)
        u = ""
        if all(not is_blank(value) for value in (m, o, q, k)):
            u = _financial_conditions_sheets_round(
                clamp(
                    _financial_conditions_weighted_sum(
                        (0.45, m), (0.30, o), (0.15, q), (0.10, k)
                    ),
                    -10,
                    10,
                ),
                2,
            )
        ai = e_z[idx]
        aj = g_z[idx]
        ak = h_z[idx]
        al = i_z[idx]
        v = _financial_conditions_stress_easing_score(ai, aj, ak, e, g, h)
        w = _financial_conditions_shock_score(f)
        x = _financial_conditions_recovery_score(g, h)
        y = _financial_conditions_outlier_score([ai, aj, ak, al])
        z = ""
        if all(not is_blank(value) for value in (k, m, o, q)):
            z = _financial_conditions_sheets_round(
                clamp(
                    _financial_conditions_weighted_sum(
                        (0.40, k), (0.30, m), (0.20, o), (0.10, q)
                    ),
                    -10,
                    10,
                ),
                2,
            )
        aa = ""
        if all(not is_blank(value) for value in (u, v, x)):
            aa = _financial_conditions_sheets_round(
                clamp(
                    _financial_conditions_weighted_sum((0.50, u), (0.30, v), (0.20, x)),
                    -10,
                    10,
                ),
                2,
            )
        ab = ""
        if all(not is_blank(value) for value in (v, w, x, y)):
            ab = _financial_conditions_sheets_round(
                clamp(
                    _financial_conditions_weighted_sum(
                        (0.35, v), (0.25, w), (0.20, x), (0.20, y)
                    ),
                    -10,
                    10,
                ),
                2,
            )
        reliability = (
            ""
            if is_blank(raw_source)
            else (
                "Insufficient history"
                if d < 60
                else ("Medium reliability" if d < 120 else "High reliability")
            )
        )
        data_status = (
            "Missing Data"
            if is_blank(raw_source)
            else (
                "Low Sample"
                if d < 60
                else (
                    "Incomplete Score"
                    if any(is_blank(value) for value in (z, aa, ab))
                    else "Valid"
                )
            )
        )
        rows.append(
            {
                "Monthly Average Financial Conditions": c,
                "Sample Count": d,
                "3M MA Financial Conditions": e,
                "1M Financial Conditions Change": f,
                "3M Financial Conditions Change": g,
                "6M Financial Conditions Change": h,
                "12M Financial Conditions Change": i,
                "Financial Conditions Level Percentile": _financial_conditions_percent_display(
                    j_internal
                ),
                "Financial Conditions Level Stress Score": k,
                "3M Change Percentile": _financial_conditions_percent_display(
                    l_internal
                ),
                "3M Change Stress Score": m,
                "6M Change Percentile": _financial_conditions_percent_display(
                    n_internal
                ),
                "6M Change Stress Score": o,
                "12M Change Percentile": _financial_conditions_percent_display(
                    p_internal
                ),
                "12M Change Stress Score": q,
                "Financial Conditions Regime": _financial_conditions_regime(e, g),
                "Risk Asset Bias": _financial_conditions_asset_bias_label(z),
                "Financial Conditions Shock Flag": _financial_conditions_shock_label(f),
                "Financial Conditions Impulse Score": u,
                "Financial Stress Risk Score": v,
                "Financial Conditions Shock Score": w,
                "Financial Conditions Cycle Turning Point Score": x,
                "Financial Conditions Extreme Score": y,
                "Coincident Score": z,
                "Leading Score": aa,
                "Warning Score": ab,
                "State": _financial_conditions_regime_signal(z),
                "Regime": _financial_conditions_momentum_label(z, aa),
                "Signal Comment": _financial_conditions_signal_interpretation(aa, ab),
                "Reliability": reliability,
                "Signal Validity": data_status,
                "Warning Flag": _financial_conditions_warning_label(ab, v, w, y),
                "Level Z-Score": ai,
                "3M Change Z-Score": aj,
                "6M Change Z-Score": ak,
                "12M Change Z-Score": al,
                "Extreme Flag": _financial_conditions_outlier_label([ai, aj, ak, al]),
            }
        )
    return make_dataframe(rows, FINANCIAL_CONDITIONS_OUTPUT_COLUMNS)


def _bank_credit_sheets_round(value: Any, places: int = 2) -> Any:
    """A38-only Google Sheets ROUND semantics."""
    return _real_yield_sheets_round(value, places)


def _bank_credit_mean_sheets(values: Sequence[Any]) -> Any:
    """A38-only spreadsheet-order average over numeric cells."""
    return _real_yield_mean_sheets(values)


def _bank_credit_percentrank_inc_sheets(values: Sequence[float], current: Any) -> Any:
    """A38-only Google Sheets PERCENTRANK.INC semantics."""
    return _real_yield_percentrank_inc_sheets(values, current)


def _bank_credit_metric_ranks_sheets(
    values: Sequence[Any], min_count: int = 60
) -> list[Any]:
    history: list[float] = []
    ranks: list[Any] = []
    for value in values:
        numeric = to_float_or_none(value)
        if numeric is not None:
            bisect.insort(history, numeric)
        if numeric is None or len(history) < min_count:
            ranks.append("")
            continue
        rank = _bank_credit_percentrank_inc_sheets(history, numeric)
        ranks.append("" if rank == "" else _bank_credit_sheets_round(rank, 3))
    return ranks


def _bank_credit_score_percentile(rank: Any) -> Any:
    return (
        "" if is_blank(rank) else _bank_credit_sheets_round((float(rank) * 20) - 10, 2)
    )


def _bank_credit_percent_display(value: Any, decimals: int = 2) -> Any:
    numeric = to_float_or_none(value)
    if numeric is None:
        return ""
    displayed = _bank_credit_sheets_round(numeric * 100, decimals)
    if displayed == 0:
        displayed = 0.0
    return f"{displayed:.{decimals}f}%"


def _bank_credit_weighted_sum(*terms: tuple[float, Any]) -> float:
    """Evaluate A38 composites from their rounded visible operands."""
    total = Decimal("0")
    for weight, value in terms:
        total += Decimal(str(weight)) * Decimal(str(value))
    return float(total)


def _bank_credit_impulse_score(l: Any, n: Any, p: Any, r: Any) -> Any:
    if any(is_blank(value) for value in (l, n, p, r)):
        return ""
    return _bank_credit_sheets_round(
        clamp(
            _bank_credit_weighted_sum((0.05, l), (0.50, n), (0.30, p), (0.15, r)),
            -10,
            10,
        ),
        2,
    )


def _bank_credit_acceleration_score(v: Any, previous_v: Any) -> Any:
    if any(is_blank(value) for value in (v, previous_v)):
        return ""
    return _bank_credit_sheets_round(
        clamp(_bank_credit_weighted_sum((2.0, v), (-2.0, previous_v)), -10, 10), 2
    )


def _bank_credit_coincident_score(l: Any, n: Any, p: Any, r: Any) -> Any:
    if any(is_blank(value) for value in (l, n, p, r)):
        return ""
    return _bank_credit_sheets_round(
        clamp(
            _bank_credit_weighted_sum((0.20, l), (0.45, n), (0.25, p), (0.10, r)),
            -10,
            10,
        ),
        2,
    )


def _bank_credit_leading_score(v: Any, w: Any, x: Any, z: Any) -> Any:
    if any(is_blank(value) for value in (v, w, x, z)):
        return ""
    return _bank_credit_sheets_round(
        clamp(
            _bank_credit_weighted_sum((0.45, v), (0.25, w), (0.20, x), (0.10, z)),
            -10,
            10,
        ),
        2,
    )


def _bank_credit_warning_score(w: Any, x: Any, y: Any, z: Any, aa: Any, ab: Any) -> Any:
    if any(is_blank(value) for value in (w, x, y, z, aa, ab)):
        return ""
    return _bank_credit_sheets_round(
        clamp(
            _bank_credit_weighted_sum(
                (0.15, w), (0.15, x), (0.20, y), (0.30, z), (0.10, aa), (0.10, ab)
            ),
            -10,
            10,
        ),
        2,
    )


def _bank_credit_positive_or_blank(value: Any) -> bool:
    return value == "" or value > 0


def _bank_credit_growth_regime(c: Any, f: Any, g: Any, h: Any) -> str:
    if is_blank(c):
        return ""
    if (
        _bank_credit_positive_or_blank(h)
        and _bank_credit_positive_or_blank(f)
        and _bank_credit_positive_or_blank(g)
    ):
        return "Bank-credit expansion regime"
    if not any(is_blank(x) for x in (h, f, g)) and h > 0 and f < 0 and g < 0:
        return "Bank-credit deterioration from high base"
    if not any(is_blank(x) for x in (h, f, g)) and h <= 0 and f > 0 and g > 0:
        return "Early bank-credit recovery"
    if not any(is_blank(x) for x in (h, f, g)) and h <= 0 and f < 0 and g < 0:
        return "Bank-credit contraction regime"
    if not any(is_blank(x) for x in (f, g)) and f > 0 and g < 0:
        return "Short-term bank-credit recovery / mixed impulse"
    if not any(is_blank(x) for x in (f, g)) and f < 0 and g > 0:
        return "Short-term bank-credit deterioration / mixed impulse"
    return "Neutral/mixed bank-credit regime"


def _bank_credit_asset_bias_label(ac: Any) -> str:
    if is_blank(ac):
        return ""
    if ac >= 6:
        return "Strongly supportive for credit-sensitive growth and risk assets"
    if ac >= 2:
        return "Mildly supportive for credit-sensitive growth and risk assets"
    if ac <= -6:
        return "Strong credit-growth headwind for risk assets and domestic demand"
    if ac <= -2:
        return "Mild credit-growth headwind for risk assets and domestic demand"
    return "Neutral bank-credit bias"


def _bank_credit_shock_label(i: Any) -> str:
    if is_blank(i):
        return ""
    if i >= 0.15:
        return "Extreme 3M annualised bank-credit growth surge"
    if i >= 0.10:
        return "Strong 3M annualised bank-credit growth surge"
    if i <= -0.05:
        return "Sharp 3M annualised bank-credit contraction"
    if i <= 0:
        return "Negative 3M annualised bank-credit growth"
    if i <= 0.03:
        return "Very weak 3M annualised bank-credit growth"
    return "No major bank-credit growth shock"


def _bank_credit_recovery_score(f: Any, g: Any) -> Any:
    if any(is_blank(x) for x in (f, g)):
        return ""
    if f > 0 and g > 0:
        return 5
    if f < 0 and g < 0:
        return -5
    if f > 0 and g < 0:
        return 3
    if f < 0 and g > 0:
        return -3
    return 0


def _bank_credit_shock_score(i: Any) -> Any:
    if is_blank(i):
        return ""
    if i >= 0.15:
        return 6
    if i >= 0.10:
        return 4
    if i <= -0.05:
        return -6
    if i <= 0:
        return -4
    if i <= 0.03:
        return -2
    return 0


def _bank_credit_contraction_risk(
    am: Any, an: Any, ao: Any, f: Any, g: Any, h: Any, i: Any
) -> Any:
    if any(is_blank(x) for x in (am, an, ao, f, g, h, i)):
        return ""
    if am < -1.5 and an < -1.5 and f < 0 and g < 0:
        return -7
    if am < -1 and an < -1 and f < 0:
        return -5
    if i < 0:
        return -4
    if i < 0.02 and am < 0 and an < 0:
        return -3
    if am > 0 and an > 0 and f > 0 and g > 0:
        return 3
    return 0


def _bank_credit_overheating_score(am: Any, an: Any, i: Any, j: Any) -> Any:
    if any(is_blank(x) for x in (am, an, i, j)):
        return ""
    if am > 1.5 and an > 1.5 and i > 0.15 and j > 0.10:
        return 5
    if am > 1 and an > 1 and i > 0.10:
        return 3
    if am < -1 and an < -1 and i < 0:
        return -3
    return 0


def _bank_credit_growth_outlier_score(zs: Sequence[Any]) -> Any:
    if any(is_blank(z) for z in zs):
        return ""
    if any(z >= 3 for z in zs):
        return 6
    if any(z >= 2 for z in zs):
        return 4
    if any(z <= -3 for z in zs):
        return -6
    if any(z <= -2 for z in zs):
        return -4
    return 0


def _bank_credit_conditions_regime(ac: Any) -> str:
    if is_blank(ac):
        return ""
    if ac >= 2:
        return "Bank credit growth improving"
    if ac <= -2:
        return "Bank credit growth deteriorating"
    return "Neutral bank credit growth"


def _bank_credit_momentum_label(ac: Any, ad: Any) -> str:
    if any(is_blank(x) for x in (ac, ad)):
        return ""
    if ac >= 2 and ad >= 2:
        return "Bank credit growth improving"
    if ac >= 2 and ad <= -2:
        return "Credit growth positive but deteriorating"
    if ac >= 2 and -2 < ad < 2:
        return "Bank credit growth supportive / stable"
    if ac <= -2 and ad >= 2:
        return "Bank credit weak but improving"
    if ac <= -2 and ad <= -2:
        return "Bank credit growth deteriorating"
    if ac <= -2 and -2 < ad < 2:
        return "Bank credit growth weak / stable"
    if -2 < ac < 2 and ad >= 2:
        return "Bank credit impulse improving"
    if -2 < ac < 2 and ad <= -2:
        return "Bank credit impulse deteriorating"
    return "Bank credit growth broadly neutral"


def _bank_credit_signal_interpretation(ad: Any, ae: Any) -> str:
    if any(is_blank(x) for x in (ad, ae)):
        return ""
    if ad >= 6 and ae >= 0:
        return (
            "Strong positive bank-credit impulse with supportive private-credit profile"
        )
    if ad >= 6 and ae < 0:
        return (
            "Strong positive bank-credit impulse, but credit-risk profile remains mixed"
        )
    if ad >= 2 and ae >= 0:
        return "Moderately positive bank-credit impulse signal"
    if ad >= 2 and ae < 0:
        return "Bank-credit impulse improving, but credit-risk profile remains fragile"
    if ad > -2 and ae > -3 and ae < 3:
        return "Neutral/mixed bank-credit signal"
    if ad <= -6 and ae <= 0:
        return "Strong bank-credit deterioration signal with downside confirmation"
    if ad <= -6 and ae > 0:
        return "Strong bank-credit deterioration signal, but credit support remains partly intact"
    if ad <= -2 and ae <= 0:
        return "Moderately negative bank-credit impulse signal"
    if ad <= -2 and ae > 0:
        return "Bank-credit impulse deteriorating, but credit conditions remain mixed"
    return "Mixed/transition bank-credit signal"


def _bank_credit_warning_label(ae: Any, y: Any, z: Any, aa: Any, ab: Any) -> str:
    if any(is_blank(x) for x in (ae, y, z, aa, ab)):
        return ""
    if z <= -6:
        return "High bank-credit contraction warning"
    if z <= -4:
        return "Moderate bank-credit contraction warning"
    if y <= -6:
        return "High bank-credit contraction shock warning"
    if y <= -4:
        return "Moderate bank-credit contraction shock warning"
    if ab <= -6:
        return "Extreme bank-credit contraction warning"
    if ab <= -4:
        return "Strong bank-credit contraction warning"
    if aa >= 5:
        return "High credit-overheating / credit-boom warning"
    if aa >= 3:
        return "Moderate credit-overheating warning"
    if ae >= 6:
        return "High bank-credit expansion signal"
    if ae >= 3:
        return "Moderate bank-credit expansion signal"
    if ae > -3:
        return "Neutral bank-credit warning profile"
    if ae > -6:
        return "Moderate bank-credit deterioration warning"
    return "High bank-credit deterioration warning"


def _bank_credit_growth_outlier_label(zs: Sequence[Any]) -> str:
    if any(is_blank(z) for z in zs):
        return ""
    if any(z >= 3 for z in zs):
        return "Extreme bank-credit expansion"
    if any(z >= 2 for z in zs):
        return "Strong bank-credit expansion"
    if any(z <= -3 for z in zs):
        return "Extreme bank-credit contraction"
    if any(z <= -2 for z in zs):
        return "Strong bank-credit contraction"
    return "Normal range"


def _bank_credit_safe_growth(current: Any, prior: Any) -> Any:
    if is_blank(current) or is_blank(prior) or prior == 0:
        return ""
    return current / prior - 1


def calculate_bank_credit_outputs(raw_df: Any) -> Any:
    records = df_records(raw_df)
    source_values = [r.get("Raw Value", r.get("B", "")) for r in records]
    raw_values = [to_float_or_none(v) for v in source_values]
    ma_values = []
    raw_count = 0
    for idx, current in enumerate(raw_values):
        if current is not None:
            raw_count += 1
        if raw_count < 3:
            ma_values.append("")
        else:
            ma_values.append(
                _bank_credit_mean_sheets(raw_values[max(0, idx - 2) : idx + 1])
            )
    c_counts = _metric_counts(ma_values)
    observation_counts = [max(0, count - 2) for count in c_counts]
    one_growth = []
    three_growth = []
    six_growth = []
    twelve_growth = []
    three_annual = []
    six_annual = []
    for idx, c in enumerate(ma_values):
        d = observation_counts[idx]
        c1 = ma_values[idx - 1] if idx >= 1 else ""
        c3 = ma_values[idx - 3] if idx >= 3 else ""
        c6 = ma_values[idx - 6] if idx >= 6 else ""
        c12 = ma_values[idx - 12] if idx >= 12 else ""
        e = _bank_credit_safe_growth(c, c1) if d >= 2 else ""
        f = _bank_credit_safe_growth(c, c3) if d >= 4 else ""
        g = _bank_credit_safe_growth(c, c6) if d >= 7 else ""
        h = _bank_credit_safe_growth(c, c12) if d >= 13 else ""
        one_growth.append(e)
        three_growth.append(f)
        six_growth.append(g)
        twelve_growth.append(h)
        try:
            three_annual.append((1 + f) ** 4 - 1 if not is_blank(f) else "")
        except Exception:
            three_annual.append("")
        try:
            six_annual.append((1 + g) ** 2 - 1 if not is_blank(g) else "")
        except Exception:
            six_annual.append("")
    f_counts = _metric_counts(three_growth)
    g_counts = _metric_counts(six_growth)
    h_counts = _metric_counts(twelve_growth)
    c_ranks = _bank_credit_metric_ranks_sheets(ma_values, 60)
    f_ranks = _bank_credit_metric_ranks_sheets(three_growth, 60)
    g_ranks = _bank_credit_metric_ranks_sheets(six_growth, 60)
    h_ranks = _bank_credit_metric_ranks_sheets(twelve_growth, 60)
    c_z = _rounded_expanding_zscores(ma_values, c_counts, 60)
    f_z = _rounded_expanding_zscores(three_growth, f_counts, 60)
    g_z = _rounded_expanding_zscores(six_growth, g_counts, 60)
    h_z = _rounded_expanding_zscores(twelve_growth, h_counts, 60)
    momentum_scores = []
    rows = []
    for idx, raw_source in enumerate(source_values):
        c = ma_values[idx]
        d = observation_counts[idx]
        e = one_growth[idx]
        f = three_growth[idx]
        g = six_growth[idx]
        h = twelve_growth[idx]
        i = three_annual[idx]
        j = six_annual[idx]
        k = c_ranks[idx]
        l = _bank_credit_score_percentile(k)
        m = f_ranks[idx]
        n = _bank_credit_score_percentile(m)
        o = g_ranks[idx]
        p = _bank_credit_score_percentile(o)
        q = h_ranks[idx]
        r = _bank_credit_score_percentile(q)
        v = _bank_credit_impulse_score(l, n, p, r)
        momentum_scores.append(v)
        prev_v = momentum_scores[idx - 1] if idx >= 1 else ""
        w = _bank_credit_acceleration_score(v, prev_v)
        al = c_z[idx]
        am = f_z[idx]
        an = g_z[idx]
        ao = h_z[idx]
        x = _bank_credit_recovery_score(f, g)
        y = _bank_credit_shock_score(i)
        z = _bank_credit_contraction_risk(am, an, ao, f, g, h, i)
        aa = _bank_credit_overheating_score(am, an, i, j)
        ab = _bank_credit_growth_outlier_score([am, an, ao])
        ac = _bank_credit_coincident_score(l, n, p, r)
        ad = _bank_credit_leading_score(v, w, x, z)
        ae = _bank_credit_warning_score(w, x, y, z, aa, ab)
        reliability = (
            ""
            if is_blank(raw_source)
            else (
                "Insufficient history"
                if d < 60
                else ("Medium reliability" if d < 120 else "High reliability")
            )
        )
        data_status = (
            "Missing Data"
            if is_blank(raw_source)
            else (
                "Low Sample"
                if d < 60
                else (
                    "Incomplete Score"
                    if any(is_blank(val) for val in (ac, ad, ae))
                    else "Valid"
                )
            )
        )
        rows.append(
            {
                "3M MA Bank Credit": c,
                "Sample Count": d,
                "1M Bank Credit Growth": e,
                "3M Bank Credit Growth": f,
                "6M Bank Credit Growth": g,
                "12M Bank Credit Growth": h,
                "3M Annualised Bank Credit Growth": i,
                "6M Annualised Bank Credit Growth": j,
                "Bank Credit Level Percentile": _bank_credit_percent_display(k),
                "Bank Credit Level Score": l,
                "3M Growth Percentile": _bank_credit_percent_display(m),
                "3M Growth Score": n,
                "6M Growth Percentile": _bank_credit_percent_display(o),
                "6M Growth Score": p,
                "12M Growth Percentile": _bank_credit_percent_display(q),
                "12M Growth Score": r,
                "Bank Credit Regime": _bank_credit_growth_regime(c, f, g, h),
                "Risk Asset Bias": _bank_credit_asset_bias_label(ac),
                "Bank Credit Growth Shock Flag": _bank_credit_shock_label(i),
                "Bank Credit Impulse Score": v,
                "Bank Credit Acceleration Score": w,
                "Bank Credit Cycle Turning Point Score": x,
                "Bank Credit Shock Score": y,
                "Credit Contraction Risk Score": z,
                "Credit Overheating Risk Score": aa,
                "Bank Credit Extreme Score": ab,
                "Coincident Score": ac,
                "Leading Score": ad,
                "Warning Score": ae,
                "State": _bank_credit_conditions_regime(ac),
                "Regime": _bank_credit_momentum_label(ac, ad),
                "Signal Comment": _bank_credit_signal_interpretation(ad, ae),
                "Reliability": reliability,
                "Signal Validity": data_status,
                "Warning Flag": _bank_credit_warning_label(ae, y, z, aa, ab),
                "Level Z-Score": al,
                "3M Growth Z-Score": am,
                "6M Growth Z-Score": an,
                "12M Growth Z-Score": ao,
                "Extreme Flag": _bank_credit_growth_outlier_label([am, an, ao]),
            }
        )
    return make_dataframe(rows, BANK_CREDIT_OUTPUT_COLUMNS)


def _corporate_spread_sheets_round(value: Any, places: int = 2) -> Any:
    """A39-only Google Sheets ROUND semantics."""
    return _real_yield_sheets_round(value, places)


def _corporate_spread_mean_sheets(values: Sequence[Any]) -> Any:
    """A39-only spreadsheet-order average that preserves last-bit rank ordering."""
    return _real_yield_mean_sheets(values)


def _corporate_spread_percentrank_inc_sheets(
    values: Sequence[float], current: Any
) -> Any:
    """A39-only Google Sheets PERCENTRANK.INC over full-precision metrics."""
    current_float = to_float_or_none(current)
    vals = sorted(
        number
        for number in (to_float_or_none(value) for value in values)
        if number is not None
    )
    n = len(vals)
    if n == 0 or current_float is None:
        return ""
    if n == 1:
        return 0.0 if vals[0] == current_float else ""
    if current_float < vals[0] or current_float > vals[-1]:
        return ""
    lo = bisect.bisect_left(vals, current_float)
    hi = bisect.bisect_right(vals, current_float)
    if lo < hi:
        return lo / (n - 1)
    lower_index = lo - 1
    upper_index = lo
    lower_value = vals[lower_index]
    upper_value = vals[upper_index]
    if upper_value == lower_value:
        return lower_index / (n - 1)
    fraction = (current_float - lower_value) / (upper_value - lower_value)
    return (lower_index + fraction) / (n - 1)


def _corporate_spread_metric_ranks_sheets(
    values: Sequence[Any], min_count: int = 60
) -> list[Any]:
    history: list[float] = []
    ranks: list[Any] = []
    for value in values:
        numeric = to_float_or_none(value)
        if numeric is not None:
            bisect.insort(history, numeric)
        if numeric is None or len(history) < min_count:
            ranks.append("")
            continue
        rank = _corporate_spread_percentrank_inc_sheets(history, numeric)
        ranks.append("" if rank == "" else _corporate_spread_sheets_round(rank, 3))
    return ranks


def _corporate_spread_inverted_score(rank: Any) -> Any:
    return (
        ""
        if is_blank(rank)
        else _corporate_spread_sheets_round(10 - (float(rank) * 20), 2)
    )


def _corporate_spread_percent_display(value: Any, decimals: int = 2) -> Any:
    numeric = to_float_or_none(value)
    if numeric is None:
        return ""
    displayed = _corporate_spread_sheets_round(numeric * 100, decimals)
    if displayed == 0:
        displayed = 0.0
    return f"{displayed:.{decimals}f}%"


def _corporate_spread_weighted_sum(*terms: tuple[float, Any]) -> float:
    total = Decimal("0")
    for weight, value in terms:
        total += Decimal(str(weight)) * Decimal(str(value))
    return float(total)


def _corporate_spread_credit_stress_score_raw(j: Any, l: Any, n: Any, p: Any) -> Any:
    if any(is_blank(value) for value in (j, l, n, p)):
        return ""
    return clamp(
        _corporate_spread_weighted_sum((0.40, j), (0.30, l), (0.20, n), (0.10, p)),
        -10,
        10,
    )


def _corporate_spread_impulse_score_raw(j: Any, l: Any, n: Any, p: Any) -> Any:
    if any(is_blank(value) for value in (j, l, n, p)):
        return ""
    return clamp(
        _corporate_spread_weighted_sum((0.50, l), (0.30, n), (0.15, p), (0.05, j)),
        -10,
        10,
    )


def _corporate_spread_leading_score_raw(
    credit_stress_score_raw: Any,
    credit_spread_impulse_score_raw: Any,
    turning_point_score: Any,
) -> Any:
    if any(
        is_blank(value)
        for value in (
            credit_stress_score_raw,
            credit_spread_impulse_score_raw,
            turning_point_score,
        )
    ):
        return ""
    return clamp(
        _corporate_spread_weighted_sum(
            (0.45, credit_stress_score_raw),
            (0.35, credit_spread_impulse_score_raw),
            (0.20, turning_point_score),
        ),
        -10,
        10,
    )


def _corporate_spread_warning_score_raw(
    credit_stress_score_raw: Any,
    turning_point_score: Any,
    shock_score: Any,
    extreme_score: Any,
) -> Any:
    if any(
        is_blank(value)
        for value in (
            credit_stress_score_raw,
            turning_point_score,
            shock_score,
            extreme_score,
        )
    ):
        return ""
    return clamp(
        _corporate_spread_weighted_sum(
            (0.35, credit_stress_score_raw),
            (0.20, turning_point_score),
            (0.25, shock_score),
            (0.20, extreme_score),
        ),
        -10,
        10,
    )


def _corporate_spread_at_or_above_sheets_boundary(
    value: Any, boundary: float, places: int = 2
) -> bool:
    if is_blank(value):
        return False
    return _corporate_spread_sheets_round(value, places) >= boundary


CORPORATE_SPREAD_EPS = 1e-9


def _corporate_spread_ge(value: Any, threshold: float) -> bool:
    return not is_blank(value) and float(value) >= threshold - CORPORATE_SPREAD_EPS


def _corporate_spread_le(value: Any, threshold: float) -> bool:
    return not is_blank(value) and float(value) <= threshold + CORPORATE_SPREAD_EPS


def _corporate_spread_gt(value: Any, threshold: float) -> bool:
    return not is_blank(value) and float(value) > threshold + CORPORATE_SPREAD_EPS


def _corporate_spread_lt(value: Any, threshold: float) -> bool:
    return not is_blank(value) and float(value) < threshold - CORPORATE_SPREAD_EPS


def _corporate_spread_regime(c: Any, e: Any, f: Any) -> str:
    if is_blank(c):
        return ""
    direction = e if is_blank(f) else f
    if c >= 4.0 and (is_blank(direction) or direction >= 0):
        return "Stress-level corporate spreads and widening"
    if c >= 4.0 and direction < 0:
        return "Stress-level corporate spreads but narrowing"
    if c >= 2.5 and (is_blank(direction) or direction >= 0):
        return "Elevated corporate spreads and widening"
    if c >= 2.5 and direction < 0:
        return "Elevated corporate spreads but narrowing"
    if c < 1.5 and (is_blank(direction) or direction < 0):
        return "Very tight corporate spreads and still narrowing"
    if c < 1.5 and direction >= 0:
        return "Very tight corporate spreads but widening"
    if is_blank(direction) or direction >= 0:
        return "Normal corporate spreads but widening"
    return "Normal corporate spreads and narrowing"


def _corporate_spread_asset_bias_label(credit_stress_score_raw: Any) -> str:
    if is_blank(credit_stress_score_raw):
        return ""
    if _corporate_spread_ge(credit_stress_score_raw, 6):
        return "Strongly supportive for risk assets / credit / equities"
    if _corporate_spread_ge(credit_stress_score_raw, 2):
        return "Mildly supportive for risk assets"
    if _corporate_spread_le(credit_stress_score_raw, -6):
        return "Strong headwind for risk assets / credit / equities"
    if _corporate_spread_le(credit_stress_score_raw, -2):
        return "Mild headwind for risk assets"
    return "Neutral corporate credit-spread risk bias"


def _corporate_spread_shock_label(f: Any) -> str:
    if is_blank(f):
        return ""
    if f >= 0.75:
        return "Large corporate spread widening shock"
    if f >= 0.40:
        return "Moderate corporate spread widening"
    if f <= -0.75:
        return "Large corporate spread narrowing"
    if f <= -0.40:
        return "Moderate corporate spread narrowing"
    return "No major corporate spread shock"


def _corporate_spread_recovery_score(f: Any, g: Any) -> Any:
    if any(is_blank(x) for x in (f, g)):
        return ""
    if f < 0 and g < 0:
        return 5
    if f > 0 and g > 0:
        return -5
    if f < 0 and g > 0:
        return 3
    if f > 0 and g < 0:
        return -3
    return 0


def _corporate_spread_shock_score(f: Any) -> Any:
    if is_blank(f):
        return ""
    if f >= 0.75:
        return -6
    if f >= 0.40:
        return -4
    if f <= -0.75:
        return 6
    if f <= -0.40:
        return 4
    return 0


def _corporate_spread_outlier_score(zs: Sequence[Any]) -> Any:
    if any(is_blank(z) for z in zs):
        return ""
    if any(z >= 3 for z in zs):
        return -6
    if any(z >= 2 for z in zs):
        return -4
    if any(z <= -3 for z in zs):
        return 6
    if any(z <= -2 for z in zs):
        return 4
    return 0


def _corporate_spread_conditions_regime(credit_stress_score_raw: Any) -> str:
    if is_blank(credit_stress_score_raw):
        return ""
    if _corporate_spread_ge(credit_stress_score_raw, 2):
        return "Credit conditions easing / supportive"
    if _corporate_spread_le(credit_stress_score_raw, -2):
        return "Credit conditions tightening / stressful"
    return "Neutral credit conditions"


def _corporate_spread_momentum_label(
    credit_stress_score_raw: Any, leading_score_raw: Any
) -> str:
    if any(is_blank(x) for x in (credit_stress_score_raw, leading_score_raw)):
        return ""
    if _corporate_spread_ge(credit_stress_score_raw, 2) and _corporate_spread_ge(
        leading_score_raw, 2
    ):
        return "Corporate credit conditions easing"
    if _corporate_spread_ge(credit_stress_score_raw, 2) and _corporate_spread_le(
        leading_score_raw, -2
    ):
        return "Credit spreads tight but widening risk"
    if (
        _corporate_spread_ge(credit_stress_score_raw, 2)
        and _corporate_spread_gt(leading_score_raw, -2)
        and _corporate_spread_lt(leading_score_raw, 2)
    ):
        return "Credit conditions supportive / stable"
    if _corporate_spread_le(credit_stress_score_raw, -2) and _corporate_spread_ge(
        leading_score_raw, 2
    ):
        return "Credit stress easing"
    if _corporate_spread_le(credit_stress_score_raw, -2) and _corporate_spread_le(
        leading_score_raw, -2
    ):
        return "Corporate credit stress building"
    if (
        _corporate_spread_le(credit_stress_score_raw, -2)
        and _corporate_spread_gt(leading_score_raw, -2)
        and _corporate_spread_lt(leading_score_raw, 2)
    ):
        return "Credit stress elevated / stable"
    if (
        _corporate_spread_gt(credit_stress_score_raw, -2)
        and _corporate_spread_lt(credit_stress_score_raw, 2)
        and _corporate_spread_ge(leading_score_raw, 2)
    ):
        return "Credit-spread impulse easing"
    if (
        _corporate_spread_gt(credit_stress_score_raw, -2)
        and _corporate_spread_lt(credit_stress_score_raw, 2)
        and _corporate_spread_le(leading_score_raw, -2)
    ):
        return "Credit-spread impulse tightening"
    return "Corporate credit spreads broadly neutral"


def _corporate_spread_signal_interpretation(leading_score_raw: Any, aa: Any) -> str:
    if any(is_blank(x) for x in (leading_score_raw, aa)):
        return ""
    strong_easing = _corporate_spread_ge(
        leading_score_raw, 6
    ) or _corporate_spread_at_or_above_sheets_boundary(leading_score_raw, 6, 2)
    if strong_easing and _corporate_spread_ge(aa, 0):
        return (
            "Strong corporate-credit easing signal with supportive risk-asset profile"
        )
    if strong_easing and _corporate_spread_lt(aa, 0):
        return "Strong corporate-credit easing signal, but stress-risk profile remains mixed"
    if _corporate_spread_ge(leading_score_raw, 2) and _corporate_spread_ge(aa, 0):
        return "Moderately positive corporate-credit easing signal"
    if _corporate_spread_ge(leading_score_raw, 2) and _corporate_spread_lt(aa, 0):
        return "Corporate credit conditions easing, but stress risk remains fragile"
    if (
        _corporate_spread_gt(leading_score_raw, -2)
        and _corporate_spread_gt(aa, -3)
        and _corporate_spread_lt(aa, 3)
    ):
        return "Neutral/mixed corporate credit-spread signal"
    if _corporate_spread_le(leading_score_raw, -6) and _corporate_spread_le(aa, 0):
        return "Severe corporate-credit stress signal with downside confirmation"
    if _corporate_spread_le(leading_score_raw, -6) and _corporate_spread_gt(aa, 0):
        return "Severe corporate-credit stress signal, but easing support remains partly intact"
    if _corporate_spread_le(leading_score_raw, -2) and _corporate_spread_le(aa, 0):
        return "Moderately negative corporate-credit stress signal"
    if _corporate_spread_le(leading_score_raw, -2) and _corporate_spread_gt(aa, 0):
        return "Corporate-credit stress building, but risk-asset support remains mixed"
    return "Mixed/transition corporate credit-spread signal"


def _corporate_spread_warning_label(
    aa: Any, credit_stress_score_raw: Any, w: Any, x: Any
) -> str:
    if any(is_blank(v) for v in (aa, credit_stress_score_raw, w, x)):
        return ""
    if _corporate_spread_le(x, -6):
        return "High corporate-credit extreme stress warning"
    if _corporate_spread_le(x, -4):
        return "Moderate corporate-credit extreme stress warning"
    if _corporate_spread_le(w, -6):
        return "High corporate-spread widening shock"
    if _corporate_spread_le(w, -4):
        return "Moderate corporate-spread widening shock"
    if _corporate_spread_le(credit_stress_score_raw, -6):
        return "High corporate-credit stress warning"
    if _corporate_spread_le(credit_stress_score_raw, -4):
        return "Moderate corporate-credit stress warning"
    if _corporate_spread_ge(aa, 6):
        return "High corporate-credit easing signal"
    if _corporate_spread_ge(aa, 3):
        return "Moderate corporate-credit easing signal"
    return "Neutral corporate-credit warning profile"


def _corporate_spread_outlier_label(zs: Sequence[Any]) -> str:
    if any(is_blank(z) for z in zs):
        return ""
    if any(z >= 3 for z in zs):
        return "Extreme corporate credit stress"
    if any(z >= 2 for z in zs):
        return "Strong corporate credit stress"
    if any(z <= -3 for z in zs):
        return "Extreme corporate spread easing"
    if any(z <= -2 for z in zs):
        return "Strong corporate spread easing"
    return "Normal range"


def calculate_corporate_credit_spreads_outputs(raw_df: Any) -> Any:
    records = df_records(raw_df)
    source_values = [r.get("Raw Value", r.get("B", "")) for r in records]
    raw_values = [to_float_or_none(v) for v in source_values]
    ma_values = []
    raw_count = 0
    for idx, current in enumerate(raw_values):
        if current is not None:
            raw_count += 1
        if raw_count < 3:
            ma_values.append("")
        else:
            window = [v for v in raw_values[max(0, idx - 2) : idx + 1] if v is not None]
            ma_values.append(_corporate_spread_mean_sheets(window) if window else "")
    c_counts = _metric_counts(ma_values)
    observation_counts = c_counts
    one_change = []
    three_change = []
    six_change = []
    twelve_change = []
    for idx, c in enumerate(ma_values):
        d = observation_counts[idx]
        c1 = ma_values[idx - 1] if idx >= 1 else ""
        c3 = ma_values[idx - 3] if idx >= 3 else ""
        c6 = ma_values[idx - 6] if idx >= 6 else ""
        c12 = ma_values[idx - 12] if idx >= 12 else ""
        one_change.append(
            c - c1 if d >= 2 and not is_blank(c) and not is_blank(c1) else ""
        )
        three_change.append(
            c - c3 if d >= 4 and not is_blank(c) and not is_blank(c3) else ""
        )
        six_change.append(
            c - c6 if d >= 7 and not is_blank(c) and not is_blank(c6) else ""
        )
        twelve_change.append(
            c - c12 if d >= 13 and not is_blank(c) and not is_blank(c12) else ""
        )
    f_counts = _metric_counts(three_change)
    g_counts = _metric_counts(six_change)
    h_counts = _metric_counts(twelve_change)
    c_ranks = _corporate_spread_metric_ranks_sheets(ma_values, 60)
    f_ranks = _corporate_spread_metric_ranks_sheets(three_change, 60)
    g_ranks = _corporate_spread_metric_ranks_sheets(six_change, 60)
    h_ranks = _corporate_spread_metric_ranks_sheets(twelve_change, 60)
    c_z = _rounded_expanding_zscores(ma_values, c_counts, 60)
    f_z = _rounded_expanding_zscores(three_change, f_counts, 60)
    g_z = _rounded_expanding_zscores(six_change, g_counts, 60)
    h_z = _rounded_expanding_zscores(twelve_change, h_counts, 60)
    rows = []
    for idx, raw_source in enumerate(source_values):
        c = ma_values[idx]
        d = observation_counts[idx]
        e = one_change[idx]
        f = three_change[idx]
        g = six_change[idx]
        h = twelve_change[idx]
        i = c_ranks[idx]
        j = _corporate_spread_inverted_score(i)
        k = f_ranks[idx]
        l = _corporate_spread_inverted_score(k)
        m = g_ranks[idx]
        n = _corporate_spread_inverted_score(m)
        o = h_ranks[idx]
        p = _corporate_spread_inverted_score(o)
        credit_stress_score_raw = _corporate_spread_credit_stress_score_raw(j, l, n, p)
        t = (
            ""
            if is_blank(credit_stress_score_raw)
            else _corporate_spread_sheets_round(credit_stress_score_raw, 2)
        )
        credit_spread_impulse_score_raw = _corporate_spread_impulse_score_raw(
            j, l, n, p
        )
        u = (
            ""
            if is_blank(credit_spread_impulse_score_raw)
            else _corporate_spread_sheets_round(credit_spread_impulse_score_raw, 2)
        )
        v = _corporate_spread_recovery_score(f, g)
        w = _corporate_spread_shock_score(f)
        ah = c_z[idx]
        ai = f_z[idx]
        aj = g_z[idx]
        ak = h_z[idx]
        x = _corporate_spread_outlier_score([ah, ai, aj, ak])
        y = t
        leading_score_raw = _corporate_spread_leading_score_raw(
            credit_stress_score_raw, credit_spread_impulse_score_raw, v
        )
        leading_score_output_raw = (
            clamp(0.45 * t + 0.35 * u + 0.20 * v, -10, 10)
            if all(not is_blank(value) for value in (t, u, v))
            else ""
        )
        z = (
            ""
            if is_blank(leading_score_output_raw)
            else _corporate_spread_sheets_round(leading_score_output_raw, 2)
        )
        warning_score_raw = _corporate_spread_warning_score_raw(
            credit_stress_score_raw, v, w, x
        )
        warning_score_output_raw = _corporate_spread_warning_score_raw(t, v, w, x)
        aa = (
            ""
            if is_blank(warning_score_output_raw)
            else _corporate_spread_sheets_round(warning_score_output_raw, 2)
        )
        reliability = (
            ""
            if is_blank(raw_source)
            else (
                "Insufficient history"
                if d < 60
                else ("Medium reliability" if d < 120 else "High reliability")
            )
        )
        data_status = (
            "Missing Data"
            if is_blank(raw_source)
            else (
                "Low Sample"
                if d < 60
                else (
                    "Incomplete Score"
                    if any(is_blank(val) for val in (y, z, aa))
                    else "Valid"
                )
            )
        )
        rows.append(
            {
                "3-Period Moving Average Corporate Credit Spread": c,
                "Corporate Credit Spread Observation Count": d,
                "1-Period Corporate Credit Spread Change": e,
                "3-Period Corporate Credit Spread Change": f,
                "6-Period Corporate Credit Spread Change": g,
                "12-Period Corporate Credit Spread Change": h,
                "Corporate Credit Spread Level PercentRank": _corporate_spread_percent_display(
                    i
                ),
                "Corporate Credit Spread Level Score": j,
                "3-Period Corporate Credit Spread Change PercentRank": _corporate_spread_percent_display(
                    k
                ),
                "3-Period Corporate Credit Spread Change Score": l,
                "6-Period Corporate Credit Spread Change PercentRank": _corporate_spread_percent_display(
                    m
                ),
                "6-Period Corporate Credit Spread Change Score": n,
                "12-Period Corporate Credit Spread Change PercentRank": _corporate_spread_percent_display(
                    o
                ),
                "12-Period Corporate Credit Spread Change Score": p,
                "Corporate Credit Spread Regime": _corporate_spread_regime(c, e, f),
                "Corporate Credit Spread Asset Bias Label": _corporate_spread_asset_bias_label(
                    credit_stress_score_raw
                ),
                "Corporate Credit Spread Shock Label": _corporate_spread_shock_label(f),
                "Corporate Credit Spread Leading Composite Score": t,
                "Corporate Credit Spread Momentum Composite Score": u,
                "Corporate Credit Spread Recovery / Deterioration Score": v,
                "Corporate Credit Spread Shock Score": w,
                "Corporate Credit Spread Outlier Score": x,
                "Corporate Credit Spread Leading Score": y,
                "Corporate Credit Spread Warning Composite Score": z,
                "Corporate Credit Spread Final Warning Score": aa,
                "Corporate Credit Spread Conditions Regime": _corporate_spread_conditions_regime(
                    credit_stress_score_raw
                ),
                "Corporate Credit Spread Momentum Label": _corporate_spread_momentum_label(
                    credit_stress_score_raw, leading_score_raw
                ),
                "Corporate Credit Spread Signal Interpretation": _corporate_spread_signal_interpretation(
                    leading_score_raw, warning_score_raw
                ),
                "Reliability": reliability,
                "Data Status": data_status,
                "Corporate Credit Spread Warning Risk Label": _corporate_spread_warning_label(
                    warning_score_raw, credit_stress_score_raw, w, x
                ),
                "Corporate Credit Spread Level Z-Score": ah,
                "3-Period Corporate Credit Spread Change Z-Score": ai,
                "6-Period Corporate Credit Spread Change Z-Score": aj,
                "12-Period Corporate Credit Spread Change Z-Score": ak,
                "Corporate Credit Spread Outlier Label": _corporate_spread_outlier_label(
                    [ah, ai, aj, ak]
                ),
            }
        )
    return make_dataframe(rows, CORPORATE_CREDIT_SPREADS_OUTPUT_COLUMNS)


def _real_gov_spending_regime(c: Any, e: Any, f: Any, g: Any) -> str:
    if is_blank(c):
        return ""
    if not any(is_blank(x) for x in (e, f, g)) and e > 0 and f > 0 and g > 0:
        return "Real government spending expansion regime"
    if not any(is_blank(x) for x in (e, f, g)) and e < 0 and f < 0 and g < 0:
        return "Real government spending contraction regime"
    if not any(is_blank(x) for x in (e, f, g)) and e > 0 and f > 0 and g < 0:
        return "Early government spending recovery"
    if not any(is_blank(x) for x in (e, f, g)) and e < 0 and f < 0 and g > 0:
        return "Government spending deterioration from high base"
    if not any(is_blank(x) for x in (e, f)) and e > 0 and f < 0:
        return "Short-term government spending recovery / mixed impulse"
    if not any(is_blank(x) for x in (e, f)) and e < 0 and f > 0:
        return "Short-term government spending deterioration / mixed impulse"
    return "Neutral/mixed government spending regime"


def _real_gov_asset_bias_label(z: Any) -> str:
    if is_blank(z):
        return ""
    if z >= 6:
        return "Strong fiscal-demand support for GDP growth"
    if z >= 2:
        return "Mild fiscal-demand support for GDP growth"
    if z <= -6:
        return "Strong fiscal-demand drag on GDP growth"
    if z <= -2:
        return "Mild fiscal-demand drag on GDP growth"
    return "Neutral fiscal-demand bias"


def _real_gov_shock_label(h: Any) -> str:
    if is_blank(h):
        return ""
    if h >= 0.10:
        return "Large quarterly government-spending surge"
    if h >= 0.05:
        return "Moderate quarterly government-spending acceleration"
    if h <= -0.10:
        return "Large quarterly government-spending contraction"
    if h <= -0.05:
        return "Moderate quarterly government-spending slowdown"
    return "No major government-spending shock"


def _real_gov_recovery_score(e: Any, f: Any) -> Any:
    if any(is_blank(x) for x in (e, f)):
        return ""
    if e > 0 and f > 0:
        return 5
    if e < 0 and f < 0:
        return -5
    if e > 0 and f < 0:
        return 3
    if e < 0 and f > 0:
        return -3
    return 0


def _real_gov_shock_score(h: Any) -> Any:
    if is_blank(h):
        return ""
    if h >= 0.10:
        return 6
    if h >= 0.05:
        return 4
    if h <= -0.10:
        return -6
    if h <= -0.05:
        return -4
    return 0


def _real_gov_outlier_score(zs: Sequence[Any]) -> Any:
    if any(is_blank(z) for z in zs):
        return ""
    if any(z >= 3 for z in zs):
        return 6
    if any(z >= 2 for z in zs):
        return 4
    if any(z <= -3 for z in zs):
        return -6
    if any(z <= -2 for z in zs):
        return -4
    return 0


def _real_gov_conditions_regime(z: Any) -> str:
    if is_blank(z):
        return ""
    if z >= 2:
        return "Real government spending growth improving"
    if z <= -2:
        return "Real government spending growth deteriorating"
    return "Neutral real government spending growth"


def _real_gov_momentum_label(z: Any, aa: Any) -> str:
    if any(is_blank(x) for x in (z, aa)):
        return ""
    if z >= 2 and aa >= 2:
        return "Real government spending growth improving"
    if z >= 2 and aa <= -2:
        return "Government spending growth supportive but fading"
    if z >= 2 and -2 < aa < 2:
        return "Government spending growth supportive / stable"
    if z <= -2 and aa >= 2:
        return "Government spending drag easing"
    if z <= -2 and aa <= -2:
        return "Real government spending contraction drag"
    if z <= -2 and -2 < aa < 2:
        return "Government spending drag stable"
    if -2 < z < 2 and aa >= 2:
        return "Government spending impulse improving"
    if -2 < z < 2 and aa <= -2:
        return "Government spending impulse deteriorating"
    return "Real government spending broadly neutral"


def _real_gov_signal_interpretation(aa: Any, ab: Any) -> str:
    if any(is_blank(x) for x in (aa, ab)):
        return ""
    if aa >= 6 and ab >= 0:
        return "Strong positive government-spending impulse with supportive fiscal-demand profile"
    if aa >= 6 and ab < 0:
        return "Strong positive government-spending impulse, but shock/turn profile is mixed"
    if aa >= 2 and ab >= 0:
        return "Moderately positive government-spending impulse signal"
    if aa >= 2 and ab < 0:
        return "Government-spending impulse improving, but near-term risk profile is fragile"
    if aa > -2 and ab > -3 and ab < 3:
        return "Neutral/mixed government-spending signal"
    if aa <= -6 and ab <= 0:
        return (
            "Strong government-spending contraction signal with downside confirmation"
        )
    if aa <= -6 and ab > 0:
        return "Strong government-spending contraction signal, but fiscal-demand support remains partly intact"
    if aa <= -2 and ab <= 0:
        return "Moderately negative government-spending impulse signal"
    if aa <= -2 and ab > 0:
        return "Government-spending impulse deteriorating, but support profile remains mixed"
    return "Mixed/transition government-spending signal"


def _real_gov_warning_label(ab: Any) -> str:
    if is_blank(ab):
        return ""
    if ab >= 6:
        return "High government-spending expansion/shock warning"
    if ab >= 3:
        return "Moderate government-spending expansion/shock warning"
    if ab > -3:
        return "Neutral government-spending warning profile"
    if ab > -6:
        return "Moderate government-spending contraction warning"
    return "High government-spending contraction warning"


def _real_gov_outlier_label(zs: Sequence[Any]) -> str:
    if any(is_blank(z) for z in zs):
        return ""
    if any(z >= 3 for z in zs):
        return "Extreme government-spending expansion"
    if any(z >= 2 for z in zs):
        return "Strong government-spending expansion"
    if any(z <= -3 for z in zs):
        return "Extreme government-spending contraction"
    if any(z <= -2 for z in zs):
        return "Strong government-spending contraction"
    return "Normal range"


def calculate_real_government_spending_outputs(raw_df: Any) -> Any:
    records = df_records(raw_df)
    raw_values = [
        to_float_or_none(r.get("Raw Value", r.get("B", r.get("Value", ""))))
        for r in records
    ]
    source_values = [
        r.get("Raw Value", r.get("B", r.get("Value", ""))) for r in records
    ]
    moving_averages: list[Any] = []
    raw_count = 0
    for idx, current in enumerate(raw_values):
        if current is not None:
            raw_count += 1
        if raw_count < 2:
            moving_averages.append("")
        else:
            window = [v for v in raw_values[max(0, idx - 1) : idx + 1] if v is not None]
            moving_averages.append(sum(window) / len(window) if window else "")
    observation_counts = _metric_counts(moving_averages)
    one_growth: list[Any] = []
    two_growth: list[Any] = []
    four_growth: list[Any] = []
    one_annualized: list[Any] = []
    two_annualized: list[Any] = []
    for idx, c in enumerate(moving_averages):
        d = observation_counts[idx]
        c1 = moving_averages[idx - 1] if idx >= 1 else ""
        c2 = moving_averages[idx - 2] if idx >= 2 else ""
        c4 = moving_averages[idx - 4] if idx >= 4 else ""
        e = _broad_money_growth(c, c1, d >= 2)
        f = _broad_money_growth(c, c2, d >= 3)
        g = _broad_money_growth(c, c4, d >= 5)
        one_growth.append(e)
        two_growth.append(f)
        four_growth.append(g)
        one_annualized.append(_broad_money_annualized_growth(e, 4))
        two_annualized.append(_broad_money_annualized_growth(f, 2))
    e_counts = _metric_counts(one_growth)
    f_counts = _metric_counts(two_growth)
    g_counts = _metric_counts(four_growth)
    h_counts = _metric_counts(one_annualized)
    e_ranks = _expectations_metric_ranks(one_growth, 40)
    f_ranks = _expectations_metric_ranks(two_growth, 40)
    g_ranks = _expectations_metric_ranks(four_growth, 40)
    h_ranks = _expectations_metric_ranks(one_annualized, 40)
    e_zscores = _rounded_expanding_zscores(one_growth, e_counts, 40)
    f_zscores = _rounded_expanding_zscores(two_growth, f_counts, 40)
    g_zscores = _rounded_expanding_zscores(four_growth, g_counts, 40)
    h_zscores = _rounded_expanding_zscores(one_annualized, h_counts, 40)
    momentum_scores: list[Any] = []
    provisional: list[dict[str, Any]] = []
    for idx, raw_source in enumerate(source_values):
        c = moving_averages[idx]
        d = observation_counts[idx]
        e = one_growth[idx]
        f = two_growth[idx]
        g = four_growth[idx]
        h = one_annualized[idx]
        i = two_annualized[idx]
        j = e_ranks[idx]
        k = _score_percent_rank(j)
        l = f_ranks[idx]
        m = _score_percent_rank(l)
        n = g_ranks[idx]
        o = _score_percent_rank(n)
        p = h_ranks[idx]
        q = _score_percent_rank(p)
        u = (
            round(clamp(0.25 * k + 0.35 * m + 0.25 * o + 0.15 * q, -10, 10), 2)
            if all(not is_blank(x) for x in (k, m, o, q))
            else ""
        )
        momentum_scores.append(u)
        ai = e_zscores[idx]
        aj = f_zscores[idx]
        ak = g_zscores[idx]
        al = h_zscores[idx]
        y = _real_gov_outlier_score([ai, aj, ak, al])
        z = (
            round(clamp(0.25 * k + 0.35 * m + 0.25 * o + 0.15 * q, -10, 10), 2)
            if all(not is_blank(x) for x in (k, m, o, q))
            else ""
        )
        prev_u = momentum_scores[idx - 1] if idx >= 1 else ""
        v = (
            round(clamp((u - prev_u) * 2, -10, 10), 2)
            if not is_blank(u) and not is_blank(prev_u)
            else ""
        )
        w = _real_gov_recovery_score(e, f)
        x = _real_gov_shock_score(h)
        aa = (
            round(clamp(0.50 * u + 0.30 * v + 0.20 * w, -10, 10), 2)
            if all(not is_blank(val) for val in (u, v, w))
            else ""
        )
        ab = (
            round(clamp(0.25 * v + 0.25 * w + 0.30 * x + 0.20 * y, -10, 10), 2)
            if all(not is_blank(val) for val in (v, w, x, y))
            else ""
        )
        reliability = (
            ""
            if is_blank(raw_source)
            else (
                "Insufficient history"
                if d < 40
                else ("Medium reliability" if d < 80 else "High reliability")
            )
        )
        data_status = (
            "Missing Data"
            if is_blank(raw_source)
            else (
                "Low Sample"
                if d < 40
                else (
                    "Incomplete Score"
                    if any(is_blank(val) for val in (z, aa, ab))
                    else "Valid"
                )
            )
        )
        provisional.append(
            {
                "2-Period Moving Average Real Government Spending": c,
                "Real Government Spending Observation Count": d,
                "1-Period Real Government Spending Growth": e,
                "2-Period Real Government Spending Growth": f,
                "4-Period Real Government Spending Growth": g,
                "1-Period Annualised Real Government Spending Growth": h,
                "2-Period Annualised Real Government Spending Growth": i,
                "1-Period Real Government Spending Growth PercentRank": j,
                "1-Period Real Government Spending Growth Score": k,
                "2-Period Real Government Spending Growth PercentRank": l,
                "2-Period Real Government Spending Growth Score": m,
                "4-Period Real Government Spending Growth PercentRank": n,
                "4-Period Real Government Spending Growth Score": o,
                "Annualised Real Government Spending Growth PercentRank": p,
                "Annualised Real Government Spending Growth Score": q,
                "Real Government Spending Regime": _real_gov_spending_regime(
                    c, e, f, g
                ),
                "Real Government Spending Asset Bias Label": _real_gov_asset_bias_label(
                    z
                ),
                "Real Government Spending Shock Label": _real_gov_shock_label(h),
                "Real Government Spending Momentum Composite Score": u,
                "Real Government Spending Momentum Turn Score": v,
                "Real Government Spending Recovery / Deterioration Score": w,
                "Real Government Spending Shock Score": x,
                "Real Government Spending Outlier Score": y,
                "Real Government Spending Leading Score": z,
                "Real Government Spending Warning Composite Score": aa,
                "Real Government Spending Final Warning Score": ab,
                "Real Government Spending Conditions Regime": _real_gov_conditions_regime(
                    z
                ),
                "Real Government Spending Momentum Label": _real_gov_momentum_label(
                    z, aa
                ),
                "Real Government Spending Signal Interpretation": _real_gov_signal_interpretation(
                    aa, ab
                ),
                "Reliability": reliability,
                "Data Status": data_status,
                "Real Government Spending Warning Risk Label": _real_gov_warning_label(
                    ab
                ),
                "1-Period Real Government Spending Growth Z-Score": ai,
                "2-Period Real Government Spending Growth Z-Score": aj,
                "4-Period Real Government Spending Growth Z-Score": ak,
                "Annualised Real Government Spending Growth Z-Score": al,
                "Real Government Spending Outlier Label": _real_gov_outlier_label(
                    [ai, aj, ak, al]
                ),
            }
        )
    return make_dataframe(provisional, REAL_GOVERNMENT_SPENDING_OUTPUT_COLUMNS)


def _fiscal_balance_regime(c: Any, f: Any) -> str:
    if is_blank(c):
        return ""
    if is_blank(f):
        return "Mixed fiscal balance regime"
    if c >= 0 and f > 0:
        return "Surplus and improving"
    if c >= 0 and f <= 0:
        return "Surplus but weakening"
    if c < 0 and c >= -3 and f > 0:
        return "Moderate deficit but improving"
    if c < 0 and c >= -3 and f <= 0:
        return "Moderate deficit and deteriorating"
    if c < -3 and c >= -6 and f > 0:
        return "Large deficit but improving"
    if c < -3 and c >= -6 and f <= 0:
        return "Large deficit and deteriorating"
    if c < -6 and f > 0:
        return "Severe deficit but improving"
    if c < -6 and f <= 0:
        return "Severe deficit and deteriorating"
    return "Mixed fiscal balance regime"


def _fiscal_impulse_bias_label(q: Any) -> str:
    if is_blank(q):
        return ""
    if q >= 6:
        return "Strong fiscal expansion impulse"
    if q >= 2:
        return "Mild fiscal expansion impulse"
    if q <= -6:
        return "Strong fiscal consolidation impulse"
    if q <= -2:
        return "Mild fiscal consolidation impulse"
    return "Neutral fiscal impulse"


def _fiscal_interaction_score(af: Any, q: Any) -> Any:
    if any(is_blank(x) for x in (af, q)):
        return ""
    if af < -1 and q >= 5:
        return 5
    if af < -0.5 and q >= 3:
        return 3
    if af > 1 and q <= -5:
        return -3
    if af > 0.5 and q <= -3:
        return -2
    return 0


def _fiscal_sustainability_risk_score(c: Any, af: Any, q: Any) -> Any:
    if any(is_blank(x) for x in (c, af, q)):
        return ""
    if c < -8 and q >= 6:
        return -7
    if c < -6 and q >= 5:
        return -5
    if c < -4 and q >= 4:
        return -3
    if af < -1.5 and q >= 5:
        return -3
    return 0


def _fiscal_outlier_score(zs: Sequence[Any]) -> Any:
    if any(is_blank(z) for z in zs):
        return ""
    if any(z <= -3 for z in zs):
        return -6
    if any(z <= -2 for z in zs):
        return -4
    if any(z >= 3 for z in zs):
        return 6
    if any(z >= 2 for z in zs):
        return 4
    return 0


def _fiscal_impulse_regime(w: Any) -> str:
    if is_blank(w):
        return ""
    if w >= 2:
        return "Fiscal impulse expansionary"
    if w <= -2:
        return "Fiscal impulse contractionary"
    return "Neutral fiscal impulse"


def _fiscal_momentum_label(w: Any, x: Any) -> str:
    if any(is_blank(v) for v in (w, x)):
        return ""
    if w >= 2 and x >= 2:
        return "Fiscal impulse expansionary"
    if w >= 2 and x <= -2:
        return "Fiscal impulse supportive but fading"
    if w >= 2 and -2 < x < 2:
        return "Fiscal impulse supportive / stable"
    if w <= -2 and x >= 2:
        return "Fiscal drag easing"
    if w <= -2 and x <= -2:
        return "Fiscal consolidation drag"
    if w <= -2 and -2 < x < 2:
        return "Fiscal drag stable"
    if -2 < w < 2 and x >= 2:
        return "Fiscal impulse improving"
    if -2 < w < 2 and x <= -2:
        return "Fiscal impulse deteriorating"
    return "Fiscal impulse broadly neutral"


def _fiscal_signal_interpretation(x: Any, y: Any, u: Any) -> str:
    if any(is_blank(v) for v in (x, y, u)):
        return ""
    if x >= 6 and u <= -5:
        return "Strong expansionary fiscal impulse, but severe deficit/sustainability risk is rising"
    if x >= 6 and y >= 0:
        return "Strong expansionary fiscal impulse with supportive growth profile"
    if x >= 2 and u <= -3:
        return "Fiscal impulse improving, but deficit/sustainability risk remains"
    if x >= 2 and y >= 0:
        return "Moderately positive fiscal impulse signal"
    if x > -2 and y > -3 and y < 3:
        return "Neutral/mixed fiscal impulse signal"
    if x <= -6 and y <= 0:
        return "Strong fiscal consolidation drag with downside confirmation"
    if x <= -6 and y > 0:
        return "Strong consolidation signal, but fiscal support remains partly intact"
    if x <= -2 and y <= 0:
        return "Moderately negative fiscal impulse / consolidation signal"
    if x <= -2 and y > 0:
        return "Fiscal consolidation signal, but growth support remains mixed"
    return "Mixed/transition fiscal impulse signal"


def _fiscal_warning_label(y: Any, u: Any) -> str:
    if any(is_blank(v) for v in (y, u)):
        return ""
    if u <= -6:
        return "High deficit/sustainability warning"
    if u <= -3:
        return "Moderate deficit/sustainability warning"
    if y >= 6:
        return "High expansionary fiscal-impulse warning"
    if y >= 3:
        return "Moderate expansionary fiscal-impulse warning"
    if y > -3:
        return "Neutral fiscal warning profile"
    if y > -6:
        return "Moderate fiscal-drag warning"
    return "High fiscal-drag warning"


def _fiscal_outlier_label(zs: Sequence[Any]) -> str:
    if any(is_blank(z) for z in zs):
        return ""
    if any(z <= -3 for z in zs):
        return "Extreme fiscal-deficit stress"
    if any(z <= -2 for z in zs):
        return "Strong fiscal-deficit stress"
    if any(z >= 3 for z in zs):
        return "Extreme fiscal-balance strength"
    if any(z >= 2 for z in zs):
        return "Strong fiscal-balance strength"
    return "Normal range"


def calculate_fiscal_balance_outputs(raw_df: Any) -> Any:
    records = df_records(raw_df)
    raw_values = [
        to_float_or_none(r.get("Raw Value", r.get("B", r.get("Value", ""))))
        for r in records
    ]
    source_values = [
        r.get("Raw Value", r.get("B", r.get("Value", ""))) for r in records
    ]

    moving_averages: list[Any] = []
    raw_count = 0
    for idx, current in enumerate(raw_values):
        if current is not None:
            raw_count += 1
        if raw_count < 3:
            moving_averages.append("")
        else:
            window = [
                value
                for value in raw_values[max(0, idx - 2) : idx + 1]
                if value is not None
            ]
            moving_averages.append(_broad_money_mean_sheets(window))

    observation_counts = _metric_counts(moving_averages)
    one_period_changes: list[Any] = []
    three_period_changes: list[Any] = []
    five_period_changes: list[Any] = []
    for idx, c in enumerate(moving_averages):
        d = observation_counts[idx]
        c1 = moving_averages[idx - 1] if idx >= 1 else ""
        c3 = moving_averages[idx - 3] if idx >= 3 else ""
        c5 = moving_averages[idx - 5] if idx >= 5 else ""
        one_period_changes.append(
            c - c1 if d >= 2 and not is_blank(c) and not is_blank(c1) else ""
        )
        three_period_changes.append(
            c - c3 if d >= 4 and not is_blank(c) and not is_blank(c3) else ""
        )
        five_period_changes.append(
            c - c5 if d >= 6 and not is_blank(c) and not is_blank(c5) else ""
        )

    c_counts = _metric_counts(moving_averages)
    e_counts = _metric_counts(one_period_changes)
    f_counts = _metric_counts(three_period_changes)
    g_counts = _metric_counts(five_period_changes)
    c_ranks = _expectations_metric_ranks(moving_averages, 20)
    e_ranks = _expectations_metric_ranks(one_period_changes, 20)
    f_ranks = _expectations_metric_ranks(three_period_changes, 20)
    g_ranks = _expectations_metric_ranks(five_period_changes, 20)
    c_zscores = _rounded_expanding_zscores(moving_averages, c_counts, 20)
    e_zscores = _rounded_expanding_zscores(one_period_changes, e_counts, 20)
    f_zscores = _rounded_expanding_zscores(three_period_changes, f_counts, 20)
    g_zscores = _rounded_expanding_zscores(five_period_changes, g_counts, 20)

    rows = []
    for idx, raw_source in enumerate(source_values):
        c = moving_averages[idx]
        d = observation_counts[idx]
        e = one_period_changes[idx]
        f = three_period_changes[idx]
        g = five_period_changes[idx]
        h = c_ranks[idx]
        i = _score_percent_rank(h)
        j = e_ranks[idx]
        k = _score_percent_rank(j)
        l = f_ranks[idx]
        m = _score_percent_rank(l)
        n = g_ranks[idx]
        o = _score_percent_rank(n)
        q = (
            round(clamp(-0.50 * k - 0.35 * m - 0.15 * o, -10, 10), 2)
            if all(not is_blank(v) for v in (k, m, o))
            else ""
        )
        s = (
            round(clamp(-0.50 * k - 0.30 * m - 0.20 * o, -10, 10), 2)
            if all(not is_blank(v) for v in (k, m, o))
            else ""
        )
        af = c_zscores[idx]
        ag = e_zscores[idx]
        ah = f_zscores[idx]
        ai = g_zscores[idx]
        t = _fiscal_interaction_score(af, q)
        u = _fiscal_sustainability_risk_score(c, af, q)
        v = _fiscal_outlier_score([af, ag, ah, ai])
        w = (
            round(clamp(0.60 * q + 0.25 * s - 0.15 * i, -10, 10), 2)
            if all(not is_blank(val) for val in (i, q, s))
            else ""
        )
        x = (
            round(clamp(0.50 * q + 0.25 * s + 0.15 * t + 0.10 * u, -10, 10), 2)
            if all(not is_blank(val) for val in (q, s, t, u))
            else ""
        )
        y = (
            round(clamp(0.25 * s + 0.20 * t + 0.35 * u + 0.20 * v, -10, 10), 2)
            if all(not is_blank(val) for val in (s, t, u, v))
            else ""
        )
        reliability = (
            ""
            if is_blank(raw_source)
            else (
                "Insufficient history"
                if d < 20
                else ("Medium reliability" if d < 40 else "High reliability")
            )
        )
        data_status = (
            "Missing Data"
            if is_blank(raw_source)
            else (
                "Low Sample"
                if d < 20
                else (
                    "Incomplete Score"
                    if any(is_blank(val) for val in (w, x, y))
                    else "Valid"
                )
            )
        )
        rows.append(
            {
                "3-Period Moving Average Fiscal Balance": c,
                "Fiscal Balance Observation Count": d,
                "1-Period Fiscal Balance Change": e,
                "3-Period Fiscal Balance Change": f,
                "5-Period Fiscal Balance Change": g,
                "Fiscal Balance Level PercentRank": h,
                "Fiscal Balance Level Score": i,
                "1-Period Fiscal Balance Change PercentRank": j,
                "1-Period Fiscal Balance Change Score": k,
                "3-Period Fiscal Balance Change PercentRank": l,
                "3-Period Fiscal Balance Change Score": m,
                "5-Period Fiscal Balance Change PercentRank": n,
                "5-Period Fiscal Balance Change Score": o,
                "Fiscal Balance Regime": _fiscal_balance_regime(c, f),
                "Fiscal Expansion Impulse Composite Score": q,
                "Fiscal Impulse Bias Label": _fiscal_impulse_bias_label(q),
                "Fiscal Impulse Momentum Score": s,
                "Fiscal Balance Interaction Score": t,
                "Fiscal Deficit Sustainability Risk Score": u,
                "Fiscal Balance Outlier Score": v,
                "Fiscal Impulse Leading Score": w,
                "Fiscal Impulse Warning Composite Score": x,
                "Fiscal Impulse Final Warning Score": y,
                "Fiscal Impulse Regime": _fiscal_impulse_regime(w),
                "Fiscal Impulse Momentum Label": _fiscal_momentum_label(w, x),
                "Fiscal Impulse Signal Interpretation": _fiscal_signal_interpretation(
                    x, y, u
                ),
                "Reliability": reliability,
                "Data Status": data_status,
                "Fiscal Warning Risk Label": _fiscal_warning_label(y, u),
                "Fiscal Balance Level Z-Score": af,
                "1-Period Fiscal Balance Change Z-Score": ag,
                "3-Period Fiscal Balance Change Z-Score": ah,
                "5-Period Fiscal Balance Change Z-Score": ai,
                "Fiscal Balance Outlier Label": _fiscal_outlier_label([af, ag, ah, ai]),
            }
        )
    return make_dataframe(rows, FISCAL_BALANCE_OUTPUT_COLUMNS)


def calculate_broad_money_outputs(raw_df: Any) -> Any:
    records = df_records(raw_df)
    raw_values = [
        to_float_or_none(r.get("Raw Value", r.get("B", r.get("Value", ""))))
        for r in records
    ]
    source_values = [
        r.get("Raw Value", r.get("B", r.get("Value", ""))) for r in records
    ]

    moving_averages: list[Any] = []
    raw_count = 0
    for idx, current in enumerate(raw_values):
        if current is not None:
            raw_count += 1
        if raw_count < 3:
            moving_averages.append("")
        else:
            window = [
                value
                for value in raw_values[max(0, idx - 2) : idx + 1]
                if value is not None
            ]
            moving_averages.append(sum(window) / len(window) if window else "")

    observation_counts: list[int] = []
    c_count = 0
    for c in moving_averages:
        if to_float_or_none(c) is not None:
            c_count += 1
        observation_counts.append(max(0, c_count - 2))

    one_period_growth: list[Any] = []
    three_period_growth: list[Any] = []
    six_period_growth: list[Any] = []
    twelve_period_growth: list[Any] = []
    annualized_three: list[Any] = []
    annualized_six: list[Any] = []
    for idx, c in enumerate(moving_averages):
        d = observation_counts[idx]

        def lag(offset: int) -> Any:
            return moving_averages[idx - offset] if idx >= offset else ""

        c1, c3, c6, c12 = lag(1), lag(3), lag(6), lag(12)
        e = _broad_money_growth(c, c1, d >= 2)
        f = _broad_money_growth(c, c3, d >= 4)
        g = _broad_money_growth(c, c6, d >= 7)
        h = _broad_money_growth(c, c12, d >= 13)
        one_period_growth.append(e)
        three_period_growth.append(f)
        six_period_growth.append(g)
        twelve_period_growth.append(h)
        annualized_three.append(_broad_money_annualized_growth(f, 4))
        annualized_six.append(_broad_money_annualized_growth(g, 2))

    c_counts = _metric_counts(moving_averages)
    f_counts = _metric_counts(three_period_growth)
    g_counts = _metric_counts(six_period_growth)
    h_counts = _metric_counts(twelve_period_growth)
    c_ranks = _broad_money_metric_ranks_sheets(moving_averages)
    f_ranks = _broad_money_metric_ranks_sheets(three_period_growth)
    g_ranks = _broad_money_metric_ranks_sheets(six_period_growth)
    h_ranks = _broad_money_metric_ranks_sheets(twelve_period_growth)
    c_zscores = _broad_money_rounded_expanding_zscores(moving_averages, c_counts)
    f_zscores = _broad_money_rounded_expanding_zscores(three_period_growth, f_counts)
    g_zscores = _broad_money_rounded_expanding_zscores(six_period_growth, g_counts)
    h_zscores = _broad_money_rounded_expanding_zscores(twelve_period_growth, h_counts)

    rows = []
    for idx, raw_source in enumerate(source_values):
        c = moving_averages[idx]
        d = observation_counts[idx]
        e = one_period_growth[idx]
        f = three_period_growth[idx]
        g = six_period_growth[idx]
        h = twelve_period_growth[idx]
        i = annualized_three[idx]
        j = annualized_six[idx]
        k = c_ranks[idx]
        l = _broad_money_score_percentile(k)
        m = f_ranks[idx]
        n = _broad_money_score_percentile(m)
        o = g_ranks[idx]
        p_score = _broad_money_score_percentile(o)
        q = h_ranks[idx]
        r = _broad_money_score_percentile(q)
        v = (
            _broad_money_sheets_round(
                clamp(
                    _broad_money_weighted_sum(
                        (0.50, n), (0.30, p_score), (0.15, r), (0.05, l)
                    ),
                    -10,
                    10,
                ),
                2,
            )
            if all(not is_blank(value) for value in (n, p_score, r, l))
            else ""
        )
        w = _broad_money_recovery_score(f, g)
        x = _broad_money_shock_score(i)
        ak = c_zscores[idx]
        al = f_zscores[idx]
        am = g_zscores[idx]
        an = h_zscores[idx]
        y = _broad_money_expansion_support_score(ak, al, am, i, j)
        z = _broad_money_contraction_risk_score(ak, al, am, i, j)
        aa = _broad_money_outlier_score([ak, al, am, an])
        ab = (
            _broad_money_sheets_round(
                clamp(
                    _broad_money_weighted_sum(
                        (0.25, l), (0.40, n), (0.25, p_score), (0.10, r)
                    ),
                    -10,
                    10,
                ),
                2,
            )
            if all(not is_blank(value) for value in (l, n, p_score, r))
            else ""
        )
        ac = (
            _broad_money_sheets_round(
                clamp(
                    _broad_money_weighted_sum((0.60, v), (0.25, w), (0.15, l)), -10, 10
                ),
                2,
            )
            if all(not is_blank(value) for value in (l, v, w))
            else ""
        )
        ad = (
            _broad_money_sheets_round(
                clamp(
                    _broad_money_weighted_sum(
                        (0.20, w), (0.20, x), (0.25, y), (0.25, z), (0.10, aa)
                    ),
                    -10,
                    10,
                ),
                2,
            )
            if all(not is_blank(value) for value in (w, x, y, z, aa))
            else ""
        )
        reliability = (
            ""
            if is_blank(raw_source)
            else (
                "Insufficient history"
                if d < 60
                else ("Medium reliability" if d < 120 else "High reliability")
            )
        )
        data_status = (
            "Missing Data"
            if is_blank(raw_source)
            else (
                "Low Sample"
                if d < 60
                else (
                    "Incomplete Score"
                    if any(is_blank(val) for val in (ab, ac, ad))
                    else "Valid"
                )
            )
        )
        rows.append(
            {
                "3M MA Broad Money": c,
                "Sample Count": d,
                "1M Broad Money Growth": e,
                "3M Broad Money Growth": f,
                "6M Broad Money Growth": g,
                "12M Broad Money Growth": h,
                "3M Annualised Broad Money Growth": i,
                "6M Annualised Broad Money Growth": j,
                "Broad Money Level Percentile": _broad_money_percent_display(k),
                "Broad Money Level Score": l,
                "3M Growth Percentile": _broad_money_percent_display(m),
                "3M Growth Score": n,
                "6M Growth Percentile": _broad_money_percent_display(o),
                "6M Growth Score": p_score,
                "12M Growth Percentile": _broad_money_percent_display(q),
                "12M Growth Score": r,
                "Broad Money Regime": _broad_money_regime(c, f, g, h),
                "Risk Asset Liquidity Bias": _broad_money_asset_bias_label(ab),
                "Money Growth Shock Flag": _broad_money_growth_shock_label(i),
                "Broad Money Impulse Score": v,
                "Broad Money Cycle Turning Point Score": w,
                "Money Growth Shock Score": x,
                "Monetary Overheating Risk Score": y,
                "Monetary Contraction Risk Score": z,
                "Broad Money Extreme Score": aa,
                "Coincident Score": ab,
                "Leading Score": ac,
                "Warning Score": ad,
                "State": _broad_money_conditions_regime(ab),
                "Regime": _broad_money_momentum_label(ab, ac),
                "Signal Comment": _broad_money_signal_interpretation(ac, ad),
                "Reliability": reliability,
                "Signal Validity": data_status,
                "Warning Flag": _broad_money_warning_label(ad),
                "Level Z-Score": ak,
                "3M Growth Z-Score": al,
                "6M Growth Z-Score": am,
                "12M Growth Z-Score": an,
                "Extreme Flag": _broad_money_outlier_label([ak, al, am, an]),
            }
        )
    return make_dataframe(rows, BROAD_MONEY_OUTPUT_COLUMNS)


def calculate_banking_reserves_outputs(raw_df: Any) -> Any:
    records = df_records(raw_df)
    source_dates = [r.get("Date", r.get("A", "")) for r in records]
    parsed_dates = [to_date_or_none(value) for value in source_dates]
    b_sources = [
        r.get(
            "Banking System Reserves",
            r.get("Raw Value", r.get("B", r.get("Value", ""))),
        )
        for r in records
    ]

    mtd_reserves = _mtd_average_liquidity(parsed_dates, b_sources)

    observation_counts: list[int] = []
    c_count = 0
    moving_averages: list[Any] = []
    for idx, c in enumerate(mtd_reserves):
        if to_float_or_none(c) is not None:
            c_count += 1
        d = max(0, c_count - 2)
        observation_counts.append(d)
        if c_count < 3:
            moving_averages.append("")
        else:
            window = [
                to_float_or_none(v) for v in mtd_reserves[max(0, idx - 2) : idx + 1]
            ]
            nums = [v for v in window if v is not None]
            moving_averages.append(_banking_reserves_mean_sheets(nums))

    one_period_changes: list[Any] = []
    three_period_changes: list[Any] = []
    six_period_changes: list[Any] = []
    twelve_period_changes: list[Any] = []
    three_period_growth: list[Any] = []
    six_period_growth: list[Any] = []
    twelve_period_growth: list[Any] = []
    for idx, e in enumerate(moving_averages):
        d = observation_counts[idx]

        def lag(offset: int) -> Any:
            return moving_averages[idx - offset] if idx >= offset else ""

        e1, e3, e6, e12 = lag(1), lag(3), lag(6), lag(12)
        one_period_changes.append(
            e - e1 if d >= 2 and not is_blank(e) and not is_blank(e1) else ""
        )
        three_period_changes.append(
            e - e3 if d >= 4 and not is_blank(e) and not is_blank(e3) else ""
        )
        six_period_changes.append(
            e - e6 if d >= 7 and not is_blank(e) and not is_blank(e6) else ""
        )
        twelve_period_changes.append(
            e - e12 if d >= 13 and not is_blank(e) and not is_blank(e12) else ""
        )
        three_period_growth.append(_liquidity_growth(e, e3, d >= 4))
        six_period_growth.append(_liquidity_growth(e, e6, d >= 7))
        twelve_period_growth.append(_liquidity_growth(e, e12, d >= 13))

    e_counts = _metric_counts(moving_averages)
    g_counts = _metric_counts(three_period_changes)
    h_counts = _metric_counts(six_period_changes)
    i_counts = _metric_counts(twelve_period_changes)
    e_ranks = _banking_reserves_metric_ranks_sheets(moving_averages)
    g_ranks = _banking_reserves_metric_ranks_sheets(three_period_changes)
    h_ranks = _banking_reserves_metric_ranks_sheets(six_period_changes)
    i_ranks = _banking_reserves_metric_ranks_sheets(
        twelve_period_changes, gate_counts=e_counts
    )
    e_zscores = _banking_reserves_rounded_expanding_zscores(moving_averages, e_counts)
    g_zscores = _banking_reserves_rounded_expanding_zscores(
        three_period_changes, g_counts
    )
    h_zscores = _banking_reserves_rounded_expanding_zscores(
        six_period_changes, h_counts
    )
    i_zscores = _banking_reserves_rounded_expanding_zscores(
        twelve_period_changes, i_counts
    )

    rows = []
    for idx, raw_b in enumerate(b_sources):
        c = mtd_reserves[idx]
        d = observation_counts[idx]
        e = moving_averages[idx]
        f = one_period_changes[idx]
        g = three_period_changes[idx]
        h = six_period_changes[idx]
        i = twelve_period_changes[idx]
        j = three_period_growth[idx]
        k = six_period_growth[idx]
        l = twelve_period_growth[idx]
        m = e_ranks[idx]
        n = _banking_reserves_score_percentile(m)
        o = g_ranks[idx]
        p = _banking_reserves_score_percentile(o)
        q = h_ranks[idx]
        r = _banking_reserves_score_percentile(q)
        s = i_ranks[idx]
        t = _banking_reserves_score_percentile(s)
        x = (
            _banking_reserves_sheets_round(
                clamp(
                    _banking_reserves_weighted_sum(
                        (0.05, n), (0.50, p), (0.30, r), (0.15, t)
                    ),
                    -10,
                    10,
                ),
                2,
            )
            if all(not is_blank(v) for v in (n, p, r, t))
            else ""
        )
        y = _banking_reserves_recovery_score(g, h)
        z = _banking_reserves_shock_score(f)
        am = e_zscores[idx]
        an = g_zscores[idx]
        ao = h_zscores[idx]
        ap = i_zscores[idx]
        aa = _banking_reserves_withdrawal_recovery_score(am, an, ao, g, h)
        ab = _banking_reserves_scarcity_stress_score(am, an, ao, g, h)
        ac = _banking_reserves_outlier_score([am, an, ao, ap])
        ad = (
            _banking_reserves_sheets_round(
                clamp(
                    _banking_reserves_weighted_sum(
                        (0.35, n), (0.35, p), (0.20, r), (0.10, t)
                    ),
                    -10,
                    10,
                ),
                2,
            )
            if all(not is_blank(v) for v in (n, p, r, t))
            else ""
        )
        ae = (
            _banking_reserves_sheets_round(
                clamp(
                    _banking_reserves_weighted_sum(
                        (0.15, n), (0.25, p), (0.25, r), (0.20, t), (0.10, x), (0.05, y)
                    ),
                    -10,
                    10,
                ),
                2,
            )
            if all(not is_blank(v) for v in (n, p, r, t, x, y))
            else ""
        )
        af = (
            _banking_reserves_sheets_round(
                clamp(
                    _banking_reserves_weighted_sum(
                        (0.25, y), (0.20, z), (0.25, aa), (0.20, ab), (0.10, ac)
                    ),
                    -10,
                    10,
                ),
                2,
            )
            if all(not is_blank(v) for v in (y, z, aa, ab, ac))
            else ""
        )
        reliability = (
            ""
            if is_blank(raw_b)
            else (
                "Insufficient history"
                if d < 60
                else ("Medium reliability" if d < 120 else "High reliability")
            )
        )
        data_status = (
            "Missing Data"
            if is_blank(raw_b)
            else (
                "Low Sample"
                if d < 60
                else (
                    "Incomplete Score"
                    if any(is_blank(v) for v in (ad, ae, af))
                    else "Valid"
                )
            )
        )
        rows.append(
            {
                "Monthly Average Reserves": c,
                "Sample Count": d,
                "3M MA Reserves": e,
                "1M Reserve Change": f,
                "3M Reserve Change": g,
                "6M Reserve Change": h,
                "12M Reserve Change": i,
                "3M Reserve Growth": j,
                "6M Reserve Growth": k,
                "12M Reserve Growth": l,
                "Reserve Level Percentile": _banking_reserves_percent_display(m),
                "Reserve Level Score": n,
                "3M Change Percentile": _banking_reserves_percent_display(o),
                "3M Change Score": p,
                "6M Change Percentile": _banking_reserves_percent_display(q),
                "6M Change Score": r,
                "12M Change Percentile": _banking_reserves_percent_display(s),
                "12M Change Score": t,
                "Reserve Liquidity Regime": _banking_reserves_regime(e, g, h),
                "Risk Asset Liquidity Bias": _banking_reserves_asset_bias_label(ad),
                "Reserve Shock Flag": _banking_reserves_shock_label(f),
                "Reserve Impulse Score": x,
                "Reserve Cycle Turning Point Score": y,
                "Reserve Shock Score": z,
                "Reserve Drain Risk Score": aa,
                "Reserve Scarcity Stress Score": ab,
                "Reserve Extreme Score": ac,
                "Coincident Score": ad,
                "Leading Score": ae,
                "Warning Score": af,
                "State": _banking_reserves_conditions_regime(ad),
                "Regime": _banking_reserves_momentum_label(ad, ae),
                "Signal Comment": _banking_reserves_signal_interpretation(ae, af),
                "Reliability": reliability,
                "Signal Validity": data_status,
                "Warning Flag": _banking_reserves_warning_label(af),
                "Level Z-Score": am,
                "3M Change Z-Score": an,
                "6M Change Z-Score": ao,
                "12M Change Z-Score": ap,
                "Extreme Flag": _banking_reserves_outlier_label([am, an, ao, ap]),
            }
        )
    return make_dataframe(rows, BANKING_RESERVES_OUTPUT_COLUMNS)


def calculate_central_bank_liquidity_outputs(raw_df: Any) -> Any:
    records = df_records(raw_df)
    source_dates = [r.get("Date", r.get("A", "")) for r in records]
    parsed_dates = [to_date_or_none(value) for value in source_dates]
    b_sources = [
        r.get(
            "Central Bank Total Assets",
            r.get("Raw Value", r.get("B", r.get("Value", ""))),
        )
        for r in records
    ]
    c_sources = [
        r.get("Cental Bank General Account", r.get("Source C", r.get("C", "")))
        for r in records
    ]
    d_sources = [
        r.get("Central Bank RRP", r.get("Source D", r.get("D", ""))) for r in records
    ]

    net_liquidity: list[Any] = []
    for b, c, d in zip(b_sources, c_sources, d_sources):
        b_num, b_ok = _numeric_or_zero_for_liquidity(b)
        c_num, c_ok = _numeric_or_zero_for_liquidity(c)
        d_num, d_ok = _numeric_or_zero_for_liquidity(d)
        net_liquidity.append(b_num - c_num - d_num if b_ok and c_ok and d_ok else "")

    mtd_average = _mtd_average_liquidity(parsed_dates, net_liquidity)
    f_counts = _metric_counts(mtd_average)
    liquidity_counts = [max(0, count - 2) for count in f_counts]
    moving_average_liquidity: list[Any] = []
    one_period_changes: list[Any] = []
    three_period_changes: list[Any] = []
    six_period_changes: list[Any] = []
    twelve_period_changes: list[Any] = []
    three_period_growth: list[Any] = []
    six_period_growth: list[Any] = []
    twelve_period_growth: list[Any] = []

    for idx, f_value in enumerate(mtd_average):
        if f_counts[idx] < 3:
            h = ""
        else:
            window = [
                value
                for value in mtd_average[max(0, idx - 2) : idx + 1]
                if to_float_or_none(value) is not None
            ]
            h = _central_bank_liquidity_mean_sheets(window)
        moving_average_liquidity.append(h)
        g = liquidity_counts[idx]
        lag_specs = (
            (1, 2, one_period_changes),
            (3, 4, three_period_changes),
            (6, 7, six_period_changes),
            (12, 13, twelve_period_changes),
        )
        for lag, min_g, target in lag_specs:
            if (
                g < min_g
                or is_blank(h)
                or idx < lag
                or is_blank(moving_average_liquidity[idx - lag])
            ):
                target.append("")
            else:
                target.append(h - moving_average_liquidity[idx - lag])
        three_period_growth.append(
            _liquidity_growth(
                h, moving_average_liquidity[idx - 3] if idx >= 3 else "", g >= 4
            )
        )
        six_period_growth.append(
            _liquidity_growth(
                h, moving_average_liquidity[idx - 6] if idx >= 6 else "", g >= 7
            )
        )
        twelve_period_growth.append(
            _liquidity_growth(
                h, moving_average_liquidity[idx - 12] if idx >= 12 else "", g >= 13
            )
        )

    h_counts = _metric_counts(moving_average_liquidity)
    j_counts = _metric_counts(three_period_changes)
    k_counts = _metric_counts(six_period_changes)
    l_counts = _metric_counts(twelve_period_changes)
    h_ranks = _central_bank_liquidity_metric_ranks_sheets(moving_average_liquidity)
    j_ranks = _central_bank_liquidity_metric_ranks_sheets(three_period_changes)
    k_ranks = _central_bank_liquidity_metric_ranks_sheets(six_period_changes)
    l_ranks = _central_bank_liquidity_metric_ranks_sheets(twelve_period_changes)
    h_zscores = _central_bank_liquidity_rounded_expanding_zscores(
        moving_average_liquidity, h_counts
    )
    j_zscores = _central_bank_liquidity_rounded_expanding_zscores(
        three_period_changes, j_counts
    )
    k_zscores = _central_bank_liquidity_rounded_expanding_zscores(
        six_period_changes, k_counts
    )
    l_zscores = _central_bank_liquidity_rounded_expanding_zscores(
        twelve_period_changes, l_counts
    )

    rows: list[dict[str, Any]] = []
    for idx, b_source in enumerate(b_sources):
        e = net_liquidity[idx]
        f = mtd_average[idx]
        g = liquidity_counts[idx]
        h = moving_average_liquidity[idx]
        i = one_period_changes[idx]
        j = three_period_changes[idx]
        k = six_period_changes[idx]
        l = twelve_period_changes[idx]
        m = three_period_growth[idx]
        n = six_period_growth[idx]
        o = twelve_period_growth[idx]
        p = h_ranks[idx]
        q = _central_bank_liquidity_score_percentile(p)
        r = j_ranks[idx]
        s_score = _central_bank_liquidity_score_percentile(r)
        t = k_ranks[idx]
        u = _central_bank_liquidity_score_percentile(t)
        v = l_ranks[idx]
        w = _central_bank_liquidity_score_percentile(v)
        aa = (
            _central_bank_liquidity_sheets_round(
                clamp(
                    _central_bank_liquidity_weighted_sum(
                        (0.45, s_score), (0.35, u), (0.15, w), (0.05, q)
                    ),
                    -10,
                    10,
                ),
                2,
            )
            if all(not is_blank(x) for x in (s_score, u, w, q))
            else ""
        )
        ab = _central_bank_liquidity_recovery_score(j, k)
        ac = _central_bank_liquidity_shock_score(i)
        ao = h_zscores[idx]
        ap = j_zscores[idx]
        aq = k_zscores[idx]
        ar = l_zscores[idx]
        ad = _central_bank_liquidity_withdrawal_risk_score(ao, ap, aq, j, k)
        ae = _central_bank_liquidity_outlier_score([ao, ap, aq, ar])
        af = (
            _central_bank_liquidity_sheets_round(
                clamp(
                    _central_bank_liquidity_weighted_sum(
                        (0.40, q), (0.30, s_score), (0.20, u), (0.10, w)
                    ),
                    -10,
                    10,
                ),
                2,
            )
            if all(not is_blank(x) for x in (q, s_score, u, w))
            else ""
        )
        ag = (
            _central_bank_liquidity_sheets_round(
                clamp(
                    _central_bank_liquidity_weighted_sum(
                        (0.15, q),
                        (0.25, s_score),
                        (0.25, u),
                        (0.20, w),
                        (0.10, aa),
                        (0.05, ab),
                    ),
                    -10,
                    10,
                ),
                2,
            )
            if all(not is_blank(x) for x in (q, s_score, u, w, aa, ab))
            else ""
        )
        ah = (
            _central_bank_liquidity_sheets_round(
                clamp(
                    _central_bank_liquidity_weighted_sum(
                        (0.30, ab), (0.25, ac), (0.30, ad), (0.15, ae)
                    ),
                    -10,
                    10,
                ),
                2,
            )
            if all(not is_blank(x) for x in (ab, ac, ad, ae))
            else ""
        )
        reliability = (
            ""
            if is_blank(b_source)
            else (
                "Insufficient history"
                if g < 60
                else ("Medium reliability" if g < 120 else "High reliability")
            )
        )
        data_status = (
            "Missing Data"
            if is_blank(b_source)
            else (
                "Low Sample"
                if g < 60
                else (
                    "Incomplete Score"
                    if any(is_blank(x) for x in (af, ag, ah))
                    else "Valid"
                )
            )
        )
        rows.append(
            {
                "Central Bank Net Liquidity": e,
                "Monthly Net Liquidity": f,
                "Sample Count": g,
                "3M MA Net Liquidity": h,
                "1M Net Liquidity Change": i,
                "3M Net Liquidity Change": j,
                "6M Net Liquidity Change": k,
                "12M Net Liquidity Change": l,
                "3M Net Liquidity Growth": m,
                "6M Net Liquidity Growth": n,
                "12M Net Liquidity Growth": o,
                "Liquidity Level Percentile": _central_bank_liquidity_percent_display(
                    p
                ),
                "Liquidity Level Score": q,
                "3M Change Percentile": _central_bank_liquidity_percent_display(r),
                "3M Change Score": s_score,
                "6M Change Percentile": _central_bank_liquidity_percent_display(t),
                "6M Change Score": u,
                "12M Change Percentile": _central_bank_liquidity_percent_display(v),
                "12M Change Score": w,
                "Liquidity Regime": _central_bank_liquidity_regime(h, j, k),
                "Risk Asset Liquidity Bias": _central_bank_liquidity_asset_bias_label(
                    af
                ),
                "Liquidity Shock Flag": _central_bank_liquidity_shock_label(i),
                "Liquidity Impulse Score": aa,
                "Liquidity Cycle Turning Point Score": ab,
                "Liquidity Shock Score": ac,
                "Liquidity Withdrawal Risk Score": ad,
                "Liquidity Extreme Score": ae,
                "Coincident Score": af,
                "Leading Score": ag,
                "Warning Score": ah,
                "State": _central_bank_liquidity_conditions_regime(af),
                "Regime": _central_bank_liquidity_momentum_label(af, ag),
                "Signal Comment": _central_bank_liquidity_signal_interpretation(ag, ah),
                "Reliability": reliability,
                "Signal Validity": data_status,
                "Warning Flag": _central_bank_liquidity_warning_label(ah),
                "Level Z-Score": ao,
                "3M Change Z-Score": ap,
                "6M Change Z-Score": aq,
                "12M Change Z-Score": ar,
                "Extreme Flag": _central_bank_liquidity_outlier_label([ao, ap, aq, ar]),
            }
        )
    return make_dataframe(rows, CENTRAL_BANK_LIQUIDITY_OUTPUT_COLUMNS)


def calculate_interbank_rate_outputs(raw_df: Any) -> Any:
    records = df_records(raw_df)
    raw_values = [
        to_float_or_none(r.get("Raw Value", r.get("B", r.get("Value", ""))))
        for r in records
    ]
    raw_counts = _metric_counts(raw_values)
    moving_averages: list[Any] = []
    smoothed_count = 0
    smoothed_counts_so_far: list[int] = []
    one_period_changes: list[Any] = []
    three_period_changes: list[Any] = []
    six_period_changes: list[Any] = []
    twelve_period_changes: list[Any] = []

    for idx, current in enumerate(raw_values):
        if raw_counts[idx] < 3:
            moving_averages.append("")
        else:
            window = [v for v in raw_values[max(0, idx - 2) : idx + 1] if v is not None]
            moving_averages.append(
                "" if not window else _interbank_rate_mean_sheets(window)
            )

        c = moving_averages[idx]
        if not is_blank(c):
            smoothed_count += 1
        smoothed_counts_so_far.append(smoothed_count)
        if (
            smoothed_count < 2
            or is_blank(c)
            or idx < 1
            or is_blank(moving_averages[idx - 1])
        ):
            one_period_changes.append("")
        else:
            one_period_changes.append(c - moving_averages[idx - 1])
        for lag, min_count, target in (
            (3, 4, three_period_changes),
            (6, 7, six_period_changes),
            (12, 13, twelve_period_changes),
        ):
            if (
                smoothed_count < min_count
                or is_blank(c)
                or idx < lag
                or is_blank(moving_averages[idx - lag])
            ):
                target.append("")
            else:
                target.append(c - moving_averages[idx - lag])

    smoothed_counts = smoothed_counts_so_far
    f_counts = _metric_counts(three_period_changes)
    g_counts = _metric_counts(six_period_changes)
    h_counts = _metric_counts(twelve_period_changes)
    c_ranks = _interbank_rate_metric_ranks_sheets(moving_averages)
    f_ranks = _interbank_rate_metric_ranks_sheets(three_period_changes)
    g_ranks = _interbank_rate_metric_ranks_sheets(six_period_changes)
    h_ranks = _interbank_rate_metric_ranks_sheets(twelve_period_changes)
    c_zscores = _rounded_expanding_zscores(moving_averages, smoothed_counts, 60)
    f_zscores = _rounded_expanding_zscores(three_period_changes, f_counts, 60)
    g_zscores = _rounded_expanding_zscores(six_period_changes, g_counts, 60)
    h_zscores = _rounded_expanding_zscores(twelve_period_changes, h_counts, 60)

    rows: list[dict[str, Any]] = []
    for idx, current in enumerate(raw_values):
        c = moving_averages[idx]
        d = smoothed_counts[idx]
        e = one_period_changes[idx]
        f = three_period_changes[idx]
        g = six_period_changes[idx]
        h = twelve_period_changes[idx]
        i = c_ranks[idx]
        j = _interbank_rate_score_percentile(i)
        k = f_ranks[idx]
        l = _interbank_rate_score_percentile(k)
        m = g_ranks[idx]
        n = _interbank_rate_score_percentile(m)
        o = h_ranks[idx]
        p = _interbank_rate_score_percentile(o)
        t = (
            _interbank_rate_sheets_round(
                clamp(
                    _interbank_rate_weighted_sum(
                        (0.05, j), (0.45, l), (0.35, n), (0.15, p)
                    ),
                    -10,
                    10,
                ),
                2,
            )
            if all(not is_blank(x) for x in (j, l, n, p))
            else ""
        )
        u = _interbank_rate_recovery_tightening_score(c, f, g)
        v = _interbank_rate_shock_score(e)
        w = _interbank_rate_restriction_score(c, f, g)
        ah = c_zscores[idx]
        ai = f_zscores[idx]
        aj = g_zscores[idx]
        ak = h_zscores[idx]
        x = _interbank_rate_outlier_score([ah, ai, aj, ak])
        y = (
            _interbank_rate_sheets_round(
                clamp(
                    _interbank_rate_weighted_sum(
                        (0.45, j), (0.30, l), (0.15, n), (0.10, p)
                    ),
                    -10,
                    10,
                ),
                2,
            )
            if all(not is_blank(val) for val in (j, l, n, p))
            else ""
        )
        z = (
            _interbank_rate_sheets_round(
                clamp(
                    _interbank_rate_weighted_sum(
                        (0.10, j), (0.35, l), (0.25, n), (0.15, p), (0.10, t), (0.05, u)
                    ),
                    -10,
                    10,
                ),
                2,
            )
            if all(not is_blank(val) for val in (j, l, n, p, t, u))
            else ""
        )
        aa = (
            _interbank_rate_sheets_round(
                clamp(
                    _interbank_rate_weighted_sum(
                        (0.30, u), (0.25, v), (0.30, w), (0.15, x)
                    ),
                    -10,
                    10,
                ),
                2,
            )
            if all(not is_blank(val) for val in (u, v, w, x))
            else ""
        )
        reliability = (
            ""
            if current is None
            else (
                "Insufficient history"
                if d < 60
                else ("Medium reliability" if d < 120 else "High reliability")
            )
        )
        data_status = (
            "Missing Data"
            if current is None
            else (
                "Low Sample"
                if d < 60
                else (
                    "Incomplete Score"
                    if any(is_blank(val) for val in (y, z, aa))
                    else "Valid"
                )
            )
        )
        rows.append(
            {
                "3M MA Rate": c,
                "Sample Count": d,
                "1M Rate Change": e,
                "3M Rate Change": f,
                "6M Rate Change": g,
                "12M Rate Change": h,
                "Rate Level Percentile": _interbank_rate_percent_display(i),
                "Rate Level Score": j,
                "3M Change Percentile": _interbank_rate_percent_display(k),
                "3M Change Score": l,
                "6M Change Percentile": _interbank_rate_percent_display(m),
                "6M Change Score": n,
                "12M Change Percentile": _interbank_rate_percent_display(o),
                "12M Change Score": p,
                "Interbank Rate Regime": _interbank_rate_level_regime(c, f),
                "Interbank Rate Policy Bias": _interbank_rate_policy_bias_label(y),
                "1M Interbank Rate Shock Flag": _interbank_rate_shock_label(e),
                "Interbank Rate Impulse Score": t,
                "Interbank Rate Cycle Turning Point Score": u,
                "Interbank Rate Shock Score": v,
                "Interbank Rate Pressure Score": w,
                "Interbank Rate Extreme Score": x,
                "Coincident Score": y,
                "Leading Score": z,
                "Warning Score": aa,
                "State": _interbank_rate_pressure_regime(y),
                "Regime": _interbank_rate_momentum_label(y, z),
                "Signal Comment": _interbank_rate_signal_interpretation(z, aa),
                "Reliability": reliability,
                "Signal Validity": data_status,
                "Warning Flag": _interbank_rate_warning_label(aa),
                "Level Z-Score": ah,
                "3M Change Z-Score": ai,
                "6M Change Z-Score": aj,
                "12M Change Z-Score": ak,
                "Extreme Flag": _interbank_rate_outlier_label([ah, ai, aj, ak]),
            }
        )
    return make_dataframe(rows, INTERBANK_RATE_OUTPUT_COLUMNS)


