def output_end_col_for_columns(columns: Sequence[str]) -> str:
    cols = list(columns)
    if cols == list(MANUFACTURING_NEW_ORDERS_OUTPUT_COLUMNS):
        return "AB"
    if cols == list(CONSUMER_SENTIMENT_OUTPUT_COLUMNS) or cols == list(
        CONSUMER_EXPECTATIONS_OUTPUT_COLUMNS
    ):
        return "AE"
    if cols == list(CENTRAL_BANK_LIQUIDITY_OUTPUT_COLUMNS):
        return "AS"
    if cols == list(BANKING_RESERVES_OUTPUT_COLUMNS):
        return "AQ"
    if cols == list(BROAD_MONEY_OUTPUT_COLUMNS):
        return "AO"
    if cols == list(FISCAL_BALANCE_OUTPUT_COLUMNS):
        return "AJ"
    if cols == list(REAL_GOVERNMENT_SPENDING_OUTPUT_COLUMNS):
        return "AM"
    if cols == list(GOVERNMENT_REVENUE_OUTPUT_COLUMNS):
        return "AP"
    if cols == list(PUBLIC_DEBT_OUTPUT_COLUMNS):
        return "AN"
    if cols == list(INTEREST_COVERAGE_OUTPUT_COLUMNS):
        return "AN"
    if cols == list(FINANCIAL_CONDITIONS_OUTPUT_COLUMNS):
        return "AM"
    if cols == list(BANK_CREDIT_OUTPUT_COLUMNS):
        return "AP"
    if cols == list(CORPORATE_CREDIT_SPREADS_OUTPUT_COLUMNS):
        return "AL"
    if (
        cols == list(BUILDING_PERMITS_OUTPUT_COLUMNS)
        or cols == list(CORE_INFLATION_OUTPUT_COLUMNS)
        or cols == list(CORE_CPI_INFLATION_OUTPUT_COLUMNS)
        or cols == list(HEADLINE_CPI_INFLATION_OUTPUT_COLUMNS)
        or cols == list(CORE_PPI_OUTPUT_COLUMNS)
        or cols == list(HEADLINE_PPI_OUTPUT_COLUMNS)
        or cols == list(REAL_YIELD_OUTPUT_COLUMNS)
        or cols == list(TWO_YEAR_YIELD_OUTPUT_COLUMNS)
        or cols == list(TEN_YEAR_YIELD_OUTPUT_COLUMNS)
        or cols == list(YIELD_CURVE_OUTPUT_COLUMNS)
        or cols == list(TERM_PREMIUM_OUTPUT_COLUMNS)
        or cols == list(INTERBANK_RATE_OUTPUT_COLUMNS)
    ):
        return "AL"
    if (
        cols == list(INDUSTRIAL_PRODUCTION_OUTPUT_COLUMNS)
        or cols == list(CONSUMER_SPENDING_OUTPUT_COLUMNS)
        or cols == list(INITIAL_CLAIMS_OUTPUT_COLUMNS)
        or cols == list(EMPLOYMENT_GROWTH_OUTPUT_COLUMNS)
        or cols == list(AVERAGE_HOURS_OUTPUT_COLUMNS)
        or cols == list(WAGE_GROWTH_OUTPUT_COLUMNS)
        or cols == list(SHORT_TERM_INFLATION_EXPECTATIONS_OUTPUT_COLUMNS)
    ):
        return "AJ"
    if cols == list(OUTPUT_COLUMNS):
        return "AB"
    raise ValueError(f"Unsupported output column count: {len(columns)}")


def engine_spec_for_engine(engine: Callable[[Any], Any]) -> IndicatorEngineSpec:
    columns = output_columns_for_engine(engine)
    output_end = output_end_col_for_columns(columns)
    if engine is calculate_manufacturing_new_orders_outputs:
        return IndicatorEngineSpec(
            "MANUFACTURING_NEW_ORDERS_ENGINE",
            engine,
            input_start_col="A",
            input_end_col="B",
            output_start_col="C",
            output_end_col="AB",
            output_columns=MANUFACTURING_NEW_ORDERS_OUTPUT_COLUMNS,
            summary_level_col="Level Score",
            summary_leading_col="Leading Score",
            summary_warning_col="Warning Score",
            summary_status_col="Signal Validity",
        )
    if engine is calculate_industrial_production_outputs:
        return IndicatorEngineSpec(
            "INDUSTRIAL_PRODUCTION_ENGINE",
            engine,
            input_start_col="A",
            input_end_col="B",
            output_start_col="C",
            output_end_col="AJ",
            output_columns=INDUSTRIAL_PRODUCTION_OUTPUT_COLUMNS,
            summary_level_col="YoY Growth Score",
            summary_leading_col="Leading Score",
            summary_warning_col="Warning Score",
            summary_status_col="Signal Validity",
        )
    if engine is calculate_average_hours_outputs:
        return IndicatorEngineSpec(
            "AVERAGE_HOURS_ENGINE",
            engine,
            input_start_col="A",
            input_end_col="B",
            output_start_col="C",
            output_end_col="AJ",
            output_columns=AVERAGE_HOURS_OUTPUT_COLUMNS,
            summary_level_col="YoY Growth Score",
            summary_leading_col="Leading Score",
            summary_warning_col="Warning Score",
            summary_status_col="Signal Validity",
        )
