def select_indicator_engine_spec(
    sheet_name: str, control_cell: str
) -> IndicatorEngineSpec:
    return engine_spec_for_engine(select_indicator_engine(sheet_name, control_cell))


def _parse_a1_single_column_range(range_name: str) -> tuple[str, int, int | None]:
    if ":" in range_name:
        start, end = range_name.split(":", 1)
    else:
        start, end = range_name, range_name
    start_col = "".join(ch for ch in start if ch.isalpha()).upper()
    end_col = "".join(ch for ch in end if ch.isalpha()).upper()
    if start_col != end_col:
        raise ValueError(
            f"Only single-column control ranges are supported: {range_name}"
        )
    start_row_text = "".join(ch for ch in start if ch.isdigit())
    end_row_text = "".join(ch for ch in end if ch.isdigit())
    if not start_row_text:
        raise ValueError(f"Control range must include a starting row: {range_name}")
    return start_col, int(start_row_text), int(end_row_text) if end_row_text else None


def _cell_ref(column: str, row: int) -> str:
    return f"{column.upper()}{row}"


def _control_values_to_specs(
    values: list[list[Any]], column: str, start_row: int, stop_at_first_blank: bool
) -> list[BatchIndicatorSpec]:
    specs: list[BatchIndicatorSpec] = []
    for offset, row in enumerate(values):
        value = row[0] if row else ""
        if is_blank(value):
            if stop_at_first_blank:
                break
            continue
        specs.append(
            BatchIndicatorSpec(
                str(value).strip(), _cell_ref(column, start_row + offset)
            )
        )
    return specs


def read_control_panel_indicator_specs(
    workbook: Any, control_range: str, stop_at_first_blank: bool
) -> list[BatchIndicatorSpec]:
    column, start_row, _ = _parse_a1_single_column_range(control_range)
    values = workbook.worksheet(CONTROL_PANEL_SHEET_NAME).get(control_range)
    return _control_values_to_specs(values, column, start_row, stop_at_first_blank)


def build_indicator_specs(
    workbook: Any, args: argparse.Namespace
) -> list[BatchIndicatorSpec]:
    if args.indicator_sheet:
        return [BatchIndicatorSpec(args.indicator_sheet, args.control_cell)]
    if args.all:
        return read_control_panel_indicator_specs(
            workbook, "A3:A", stop_at_first_blank=True
        )
    if args.control_range:
        return read_control_panel_indicator_specs(
            workbook, args.control_range, stop_at_first_blank=False
        )
    return [
        BatchIndicatorSpec(
            read_control_panel_indicator_name(workbook, args.control_cell),
            args.control_cell,
        )
    ]


def filter_indicator_specs(
    specs: list[BatchIndicatorSpec],
    only: Sequence[str] | None,
    exclude: Sequence[str] | None,
) -> list[BatchIndicatorSpec]:
    only_set = set(only or [])
    exclude_set = set(exclude or [])
    filtered = []
    for spec in specs:
        if only_set and spec.sheet_name not in only_set:
            continue
        if spec.sheet_name in exclude_set:
            continue
        filtered.append(spec)
    return filtered


def process_indicator(
    workbook: Any, spec: BatchIndicatorSpec, write: bool, verify: bool
) -> BatchIndicatorResult:
    try:
        LOGGER.info(
            "Selected indicator sheet name: %s (control cell %s)",
            spec.sheet_name,
            spec.control_cell,
        )
        worksheet = workbook.worksheet(spec.sheet_name)
        engine_spec = select_indicator_engine_spec(spec.sheet_name, spec.control_cell)
        input_range = f"{engine_spec.input_start_col}2:{engine_spec.input_end_col}"
        if engine_spec.input_value_render_option:
            input_values = worksheet.get(
                input_range, value_render_option=engine_spec.input_value_render_option
            )
        else:
            input_values = worksheet.get(input_range)
        raw_df = read_indicator_values(input_values, engine_spec.input_end_col)
        output_df = engine_spec.calculate(raw_df)
        output_columns = engine_spec.output_columns
        summary = build_summary(spec.sheet_name, raw_df, output_df)
        summary = IndicatorRunSummary(
            summary.indicator_sheet_name,
            summary.rows_read,
            summary.rows_calculated,
            f"{engine_spec.output_start_col}2:{engine_spec.output_end_col}{summary.rows_calculated + 1}",
            summary.first_date,
            summary.last_date,
            summary.nonblank_raw_values,
        )
        print_summary(summary, output_df)
        if write:
            write_indicator_outputs(
                worksheet,
                output_df,
                summary.rows_calculated + 1,
                output_columns,
                engine_spec.output_end_col,
                engine_spec.output_start_col,
            )
            if verify:
                verify_written_outputs(
                    worksheet,
                    output_df,
                    summary.rows_calculated + 1,
                    output_columns,
                    engine_spec.output_end_col,
                    engine_spec.output_start_col,
                )
                LOGGER.info(
                    "Write and verification completed successfully for %s.",
                    spec.sheet_name,
                )
            else:
                LOGGER.info(
                    "Write completed for %s; verification skipped by --no-verify.",
                    spec.sheet_name,
                )
        else:
            LOGGER.info("Dry-run only for %s; no values written.", spec.sheet_name)
        return BatchIndicatorResult(spec.sheet_name, True, summary.output_range)
    except Exception as exc:
        LOGGER.exception("Indicator failed: %s", spec.sheet_name)
        return BatchIndicatorResult(spec.sheet_name, False, error=str(exc))


def print_batch_summary(results: Sequence[BatchIndicatorResult]) -> None:
    ok = [r for r in results if r.ok]
    failed = [r for r in results if not r.ok]
    if os.getenv("US_PIPELINE_COMPACT_OUTPUT") == "1":
        print(
            f"Analysis sheets: {len(ok)}/{len(results)} succeeded, "
            f"{len(failed)} failed."
        )
        for result in failed:
            print(f"  FAILED {result.sheet_name}: {result.error}")
        return
    LOGGER.info(
        "Batch summary: total=%s succeeded=%s failed=%s",
        len(results),
        len(ok),
        len(failed),
    )
    for result in ok:
        LOGGER.info("Succeeded: %s %s", result.sheet_name, result.output_range)
    for result in failed:
        LOGGER.error("Failed: %s error=%s", result.sheet_name, result.error)


def quote_sheet_name(sheet_name: str) -> str:
    escaped = sheet_name.replace("'", "''")
    return f"'{escaped}'"


def indicator_input_range(
    sheet_name: str, input_end_col: str = "B", input_start_col: str = "A"
) -> str:
    return f"{quote_sheet_name(sheet_name)}!{input_start_col}2:{input_end_col}"


def indicator_output_range(
    sheet_name: str,
    last_data_row: int,
    output_end_col: str = "AB",
    output_start_col: str = "C",
) -> str:
    assert_safe_output_range(
        f"{output_start_col}2:{output_end_col}{last_data_row}",
        output_end_col,
        output_start_col,
    )
    return f"{quote_sheet_name(sheet_name)}!{output_start_col}2:{output_end_col}{last_data_row}"


def chunked(items: Sequence[Any], chunk_size: int) -> list[list[Any]]:
    if chunk_size < 1:
        raise ValueError("chunk_size must be >= 1")
    return [list(items[i : i + chunk_size]) for i in range(0, len(items), chunk_size)]


def is_quota_error(exc: BaseException) -> bool:
    text = str(exc).lower()
    status = getattr(getattr(exc, "response", None), "status_code", None)
    return status == 429 or "429" in text or "quota" in text


def call_with_backoff(
    fn: Callable[[], Any],
    *,
    operation_name: str,
    max_attempts: int = 7,
    base_sleep_seconds: float = 1.0,
) -> Any:
    for attempt in range(1, max_attempts + 1):
        try:
            return fn()
        except Exception as exc:
            if not is_quota_error(exc) or attempt == max_attempts:
                raise
            sleep_for = base_sleep_seconds * (2 ** (attempt - 1)) + random.uniform(
                0, 0.5
            )
            LOGGER.warning(
                "%s hit quota; retrying in %.1fs attempt %s/%s",
                operation_name,
                sleep_for,
                attempt,
                max_attempts,
            )
            time.sleep(sleep_for)
    raise RuntimeError(f"{operation_name} failed unexpectedly")


def batch_get_values(
    workbook: Any,
    ranges: list[str],
    *,
    value_render_option: str = "UNFORMATTED_VALUE",
    chunk_size: int = 20,
    sleep_between_batches: float = 0.0,
    max_retries: int = 7,
) -> dict[str, list[list[object]]]:
    results: dict[str, list[list[object]]] = {}
    calls = 0
    for chunk in chunked(ranges, chunk_size):

        def do_get() -> Any:
            return workbook.values_batch_get(
                ranges=chunk, params={"valueRenderOption": value_render_option}
            )

        response = call_with_backoff(
            do_get,
            operation_name=f"values_batch_get[{len(chunk)}]",
            max_attempts=max_retries,
        )
        calls += 1
        value_ranges = (
            response.get("valueRanges", []) if isinstance(response, dict) else []
        )
        for requested_range, value_range in zip(chunk, value_ranges):
            results[requested_range] = value_range.get("values", [])
        for requested_range in chunk:
            results.setdefault(requested_range, [])
        if sleep_between_batches > 0 and calls * chunk_size < len(ranges):
            time.sleep(sleep_between_batches)
    LOGGER.info("Batch read %s ranges using %s API calls", len(ranges), calls)
    return results


def _parse_quoted_sheet_range(a1_range: str) -> tuple[str, str]:
    if "!" not in a1_range:
        raise ValueError(f"Range must include sheet name: {a1_range}")
    sheet_part, cell_range = a1_range.split("!", 1)
    if sheet_part.startswith("'") and sheet_part.endswith("'"):
        sheet_part = sheet_part[1:-1].replace("''", "'")
    return sheet_part, cell_range


def batch_update_values(
    workbook: Any,
    updates: list[dict[str, object]],
    *,
    value_input_option: str = "RAW",
    chunk_size: int = 20,
    sleep_between_batches: float = 0.0,
    max_retries: int = 7,
) -> int:
    calls = 0
    for chunk in chunked(updates, chunk_size):
        from notifications import changes

        comparisons = None
        if changes.enabled():
            try:
                previous = batch_get_values(
                    workbook,
                    [str(item["range"]) for item in chunk],
                    chunk_size=chunk_size,
                )
                comparisons = [
                    changes.compare(previous[str(item["range"])], item["values"])
                    for item in chunk
                ]
            except Exception:
                comparisons = [{"unknown": True} for item in chunk]

        if hasattr(workbook, "values_batch_update"):

            def do_update() -> Any:
                return workbook.values_batch_update(
                    {"valueInputOption": value_input_option, "data": chunk}
                )

        else:

            def do_update() -> None:
                for update in chunk:
                    sheet_name, cell_range = _parse_quoted_sheet_range(
                        str(update["range"])
                    )
                    workbook.worksheet(sheet_name).update(
                        range_name=cell_range,
                        values=update["values"],
                        value_input_option=value_input_option,
                    )

        call_with_backoff(
            do_update,
            operation_name=f"values_batch_update[{len(chunk)}]",
            max_attempts=max_retries,
        )
        if comparisons is not None:
            for item, counts in zip(chunk, comparisons):
                changes.record(
                    "Indicator analysis",
                    _parse_quoted_sheet_range(str(item["range"]))[0],
                    **counts,
                )
        calls += 1
        if sleep_between_batches > 0 and calls * chunk_size < len(updates):
            time.sleep(sleep_between_batches)
    LOGGER.info("Batch wrote %s ranges using %s API calls", len(updates), calls)
    return calls


def read_indicator_values(values: list[list[Any]], input_end_col: str = "B") -> Any:
    rows = []
    end_col = input_end_col.upper()
    has_c = end_col >= "C"
    wide = end_col >= "D"
    for row in values:
        a = row[0] if len(row) > 0 else ""
        b = row[1] if len(row) > 1 else ""
        c = row[2] if len(row) > 2 else ""
        d = row[3] if len(row) > 3 else ""
        if (
            is_blank(a)
            and is_blank(b)
            and (not has_c or is_blank(c))
            and (not wide or is_blank(d))
        ):
            break
        if wide:
            rows.append({"Date": a, "Raw Value": b, "Source C": c, "Source D": d})
        elif has_c:
            rows.append({"Date": a, "Raw Value": b, "Source C": c})
        else:
            rows.append({"Date": a, "Raw Value": b})
    columns = (
        ["Date", "Raw Value", "Source C", "Source D"]
        if wide
        else (["Date", "Raw Value", "Source C"] if has_c else ["Date", "Raw Value"])
    )
    return make_dataframe(rows, columns)


def read_indicator_ab_values(values: list[list[Any]]) -> Any:
    return read_indicator_values(values, "B")


def read_indicator_ab(worksheet: Any) -> Any:
    return read_indicator_ab_values(worksheet.get("A2:B"))


def output_rows(
    output_df: Any, output_columns: Sequence[str] | None = None
) -> list[list[Any]]:
    columns = list(output_columns or getattr(output_df, "columns", OUTPUT_COLUMNS))
    return (
        output_df[columns].values.tolist()
        if hasattr(output_df, "values")
        else [[r.get(c, "") for c in columns] for r in df_records(output_df)]
    )


def dataframe_to_sheet_rows(
    output_df: Any, output_columns: Sequence[str] | None = None
) -> list[list[Any]]:
    return output_rows(output_df, output_columns)


def assert_safe_output_range(
    output_range: str, output_end_col: str = "AB", output_start_col: str = "C"
) -> None:
    expected_prefix = f"{output_start_col}2:{output_end_col}"
    if output_start_col not in ("C", "D", "E"):
        raise AssertionError(f"Unsafe output start column {output_start_col!r}")
    if output_start_col == "C" and output_end_col == "AS":
        raise AssertionError("C-starting ranges must not use AS; A29 must start at E")
    if output_start_col == "D" and output_end_col != "AN":
        raise AssertionError(
            "D-starting output ranges are reserved for D2:AN interest coverage outputs"
        )
    if output_start_col == "E" and output_end_col != "AS":
        raise AssertionError(
            "E-starting output ranges are reserved for E2:AS central bank liquidity outputs"
        )
    if not output_range.startswith(expected_prefix):
        raise AssertionError(
            f"Unsafe output range {output_range!r}; expected {expected_prefix}n"
        )
    try:
        last_row = int(output_range.split(f":{output_end_col}", 1)[1])
    except Exception as exc:
        raise AssertionError(f"Invalid output range {output_range!r}") from exc
    if last_row < 2:
        raise AssertionError(
            f"Unsafe output range {output_range!r}; last row must be >= 2"
        )


def normalize_grid(
    rows: list[list[object]], row_count: int, col_count: int
) -> list[list[object]]:
    out: list[list[object]] = []
    for r in range(row_count):
        source = rows[r] if r < len(rows) else []
        padded = list(source[:col_count]) + [""] * max(0, col_count - len(source))
        out.append(padded)
    return out


def values_equivalent(expected: object, actual: object, tol: float = 1e-9) -> bool:
    if is_blank(expected) and is_blank(actual):
        return True
    if is_blank(expected) or is_blank(actual):
        return False
    expected_num = to_float_or_none(expected)
    actual_num = to_float_or_none(actual)
    if expected_num is not None and actual_num is not None:
        return abs(expected_num - actual_num) <= tol
    return str(expected).strip() == str(actual).strip()


def build_summary(
    indicator_sheet_name: str, raw_df: Any, output_df: Any
) -> IndicatorRunSummary:
    recs = df_records(raw_df)
    dates = [str(r.get("Date", "")) for r in recs if not is_blank(r.get("Date", ""))]
    last_data_row = len(recs) + 1
    return IndicatorRunSummary(
        indicator_sheet_name,
        len(recs),
        len(output_df),
        f"C2:AB{last_data_row}",
        dates[0] if dates else "",
        dates[-1] if dates else "",
        sum(to_float_or_none(r.get("Raw Value")) is not None for r in recs),
    )


def validate_write_range(
    output_df: Any,
    last_data_row: int,
    start_col: str = "C",
    start_row: int = 2,
    output_columns: Sequence[str] | None = None,
    output_end_col: str | None = None,
) -> str:
    columns = list(output_columns or getattr(output_df, "columns", OUTPUT_COLUMNS))
    end_col = output_end_col or output_end_col_for_columns(columns)
    if start_row != 2 or start_col not in ("C", "D", "E"):
        raise AssertionError(
            "Write range must avoid protected row 1 and protected source columns"
        )
    if start_col == "D" and end_col != "AN":
        raise AssertionError("Only interest coverage outputs may start at D")
    if start_col == "E" and end_col != "AS":
        raise AssertionError("Only central bank liquidity outputs may start at E")
    if start_col == "C" and end_col == "AS":
        raise AssertionError("Central bank liquidity outputs must start at E")
    if len(output_df) != last_data_row - 1:
        raise AssertionError("Output row count does not match last_data_row")
    if getattr(output_df, "shape")[1] != len(columns):
        raise AssertionError(f"Output must have exactly {len(columns)} columns")
    output_range = f"{start_col}2:{end_col}{last_data_row}"
    assert_safe_output_range(output_range, end_col, start_col)
    return output_range


def write_indicator_outputs(
    worksheet: Any,
    output_df: Any,
    last_data_row: int,
    output_columns: Sequence[str] | None = None,
    output_end_col: str | None = None,
    output_start_col: str = "C",
) -> str:
    columns = list(output_columns or getattr(output_df, "columns", OUTPUT_COLUMNS))
    end_col = output_end_col or output_end_col_for_columns(columns)
    rows = dataframe_to_sheet_rows(output_df, columns)
    if output_df.shape[1] != len(columns):
        raise AssertionError(
            f"Expected {len(columns)} output columns, got {output_df.shape[1]}"
        )
    if len(rows) != last_data_row - 1:
        raise AssertionError(
            f"Output row count mismatch: rows={len(rows)}, last_data_row={last_data_row}"
        )
    output_range = f"{output_start_col}2:{end_col}{last_data_row}"
    assert_safe_output_range(output_range, end_col, output_start_col)
    from notifications import changes

    counts = changes.capture(
        lambda: worksheet.get(output_range, value_render_option="UNFORMATTED_VALUE"),
        rows,
    )
    worksheet.update(range_name=output_range, values=rows, value_input_option="RAW")
    if counts is not None:
        changes.record(
            "Indicator analysis", getattr(worksheet, "title", output_range), **counts
        )

    return output_range


def verify_written_outputs(
    worksheet: Any,
    output_df: Any,
    last_data_row: int,
    output_columns: Sequence[str] | None = None,
    output_end_col: str | None = None,
    output_start_col: str = "C",
) -> None:
    columns = list(output_columns or getattr(output_df, "columns", OUTPUT_COLUMNS))
    end_col = output_end_col or output_end_col_for_columns(columns)
    expected_rows = dataframe_to_sheet_rows(output_df, columns)
    row_count = len(expected_rows)
    col_count = output_df.shape[1]
    if col_count != len(columns):
        raise AssertionError(f"Expected {len(columns)} output columns, got {col_count}")
    output_range = f"{output_start_col}2:{end_col}{last_data_row}"
    assert_safe_output_range(output_range, end_col, output_start_col)
    actual_rows = worksheet.get(output_range, value_render_option="UNFORMATTED_VALUE")
    actual_norm = normalize_grid(actual_rows, row_count, col_count)
    for r in range(row_count):
        for c in range(col_count):
            expected = expected_rows[r][c]
            actual = actual_norm[r][c]
            if not values_equivalent(expected, actual):
                sheet_row = r + 2
                sheet_col = c + 3
                raise AssertionError(
                    f"Value mismatch at output row={r}, output col={c}, "
                    f"sheet row={sheet_row}, sheet col={sheet_col}: "
                    f"actual={actual!r} expected={expected!r}"
                )


def first_existing_column(df: Any, candidates: Sequence[str]) -> str | None:
    columns = set(getattr(df, "columns", []))
    for col in candidates:
        if col in columns:
            return col
    return None


def count_nonblank_column(df: Any, column_name: str | None) -> int:
    if not column_name or column_name not in set(getattr(df, "columns", [])):
        return 0
    return sum(not is_blank(r.get(column_name, "")) for r in df_records(df))


def count_matching_column(df: Any, column_name: str | None, expected: object) -> int:
    if not column_name or column_name not in set(getattr(df, "columns", [])):
        return 0
    return sum(r.get(column_name) == expected for r in df_records(df))


def print_summary(summary: IndicatorRunSummary, output_df: Any) -> None:
    LOGGER.info("Indicator sheet: %s", summary.indicator_sheet_name)
    LOGGER.info(
        "Rows read/calculated: %s/%s; date range: %s -> %s",
        summary.rows_read,
        summary.rows_calculated,
        summary.first_date,
        summary.last_date,
    )
    LOGGER.info(
        "Output range: %s; valid raw values: %s",
        summary.output_range,
        summary.nonblank_raw_values,
    )
    level_col = first_existing_column(output_df, LEVEL_SCORE_COLUMNS)
    leading_col = first_existing_column(output_df, LEADING_SCORE_COLUMNS)
    warning_col = first_existing_column(output_df, WARNING_SCORE_COLUMNS)
    status_col = first_existing_column(output_df, STATUS_COLUMNS)
    for label, col in (
        ("level", level_col),
        ("leading", leading_col),
        ("warning", warning_col),
        ("status", status_col),
    ):
        if col is None:
            LOGGER.warning(
                "Summary column not found for %s: %s",
                summary.indicator_sheet_name,
                label,
            )
    level_count = count_nonblank_column(output_df, level_col)
    leading_count = count_nonblank_column(output_df, leading_col)
    warning_count = count_nonblank_column(output_df, warning_col)
    valid_rows = count_matching_column(output_df, status_col, "Valid")
    LOGGER.info(
        "Valid score counts: level=%s (%s), leading=%s (%s), warning=%s (%s), valid_rows=%s",
        level_count,
        level_col or "not present",
        leading_count,
        leading_col or "not present",
        warning_count,
        warning_col or "not present",
        valid_rows,
    )


