    class FakeCentralBankWorksheet:
        def __init__(self, rows: list[list[Any]]) -> None:
            self.rows = rows
            self.get_calls: list[tuple[str, str | None]] = []
            self.update_calls: list[tuple[str, list[list[Any]], str]] = []

        def get(
            self, range_name: str, value_render_option: str | None = None
        ) -> list[list[Any]]:
            self.get_calls.append((range_name, value_render_option))
            return self.rows

        def update(
            self, range_name: str, values: list[list[Any]], value_input_option: str
        ) -> None:
            self.update_calls.append((range_name, values, value_input_option))

