    # A31 fixed protected-source fixture: January 1959 through October 2013.
    # Packing keeps the offline regression data compact without consulting Sheets.
    import base64
    import zlib

    broad_money_fixture = ""
    broad_money_values = [
        float(value)
        for value in zlib.decompress(base64.b64decode(broad_money_fixture))
        .decode()
        .split(",")
    ]
    assert (
        len(broad_money_values) == 658
        and broad_money_values[:3] == [286.6, 287.7, 289.2]
        and broad_money_values[-1] == 10986.3
    )

    def broad_money_month_end(offset: int) -> date:
        year = 1959 + offset // 12
        month = 1 + offset % 12
        next_month = date(year + 1, 1, 1) if month == 12 else date(year, month + 1, 1)
        return next_month - timedelta(days=1)

    broad_money_dates = [
        broad_money_month_end(i) for i in range(len(broad_money_values))
    ]
    broad_money_raw_rows = [
        {"Date": dt.isoformat(), "Raw Value": value}
        for dt, value in zip(broad_money_dates, broad_money_values)
    ]
    broad_money_raw = make_dataframe(broad_money_raw_rows, ["Date", "Raw Value"])
    broad_money_out = calculate_broad_money_outputs(broad_money_raw)
    broad_money_rows = df_records(broad_money_out)
    broad_money_spec = select_indicator_engine_spec(
        "Unmapped broad money sheet", CONTROL_PANEL_TWENTY_NINTH_INDICATOR_CELL
    )
    assert (
        select_indicator_engine(
            "Unmapped broad money sheet", CONTROL_PANEL_TWENTY_NINTH_INDICATOR_CELL
        )
        is calculate_broad_money_outputs
    )
    assert broad_money_spec.calculate is calculate_broad_money_outputs
    assert (
        broad_money_spec.input_start_col == "A"
        and broad_money_spec.input_end_col == "B"
    )
    assert (
        broad_money_spec.output_start_col == "C"
        and broad_money_spec.output_end_col == "AO"
    )
    assert list(broad_money_out.columns) == BROAD_MONEY_OUTPUT_COLUMNS
    assert broad_money_out.shape[1] == len(BROAD_MONEY_OUTPUT_COLUMNS) == 39
    assert output_end_col_for_columns(BROAD_MONEY_OUTPUT_COLUMNS) == "AO"
    assert indicator_input_range("Broad Money") == "'Broad Money'!A2:B"
    assert indicator_output_range("Broad Money", 659, "AO") == "'Broad Money'!C2:AO659"

