    def revenue_growth_series(lag: int, gate: int) -> list[Any]:
        return [
            _gov_revenue_growth(
                current,
                c_values[idx - lag] if idx >= lag else "",
                d_values[idx] >= gate,
            )
            for idx, current in enumerate(c_values)
        ]

